/* Kitap sayfasının yanında, basılı sırayı izleyen özgün öğretmen notları. Sayfalar basılı numaralardır. */
(function () {
  const guides = {};
  const s = (title, pages, explanation, look, question, answer) => ({ title, pages, explanation, look, check: { question, answer } });
  const add = (id, title, book, intro, sections) => { guides[id] = { title, book, intro, sections }; };

  add('bio-tyt-01', 'Canlıların Ortak Özellikleri', 'TYT-bio', 'Kitabın 9–15. sayfalarını Hücresel Yapı başlığından Büyüme ve Gelişme başlığına kadar sırayla okuyacağız.', [
    s('Hücresel Yapı', [9], [
      'Sayfanın ilk açıklamasında hücreyi canlıların temel yapı ve görev birimi olarak tanıyoruz. Ardından verilen hücre örneklerini yalnız dış görünüşleriyle karşılaştırma: kalıtsal maddenin zarla çevrili bir çekirdekte bulunup bulunmadığını izle. Prokaryot ve ökaryot ayrımını belirleyen bu düzenlenmedir. Bir canlının tek hücreli olması ise ayrı bir bilgidir; tek hücreli bir ökaryot da olabilir.',
      'Örnekleri okurken iki sütunlu bir karşılaştırma yap: hücre sayısı ve hücresel yapı. Birinci sütun tek/çok hücreli, ikinci sütun prokaryot/ökaryot bilgisini taşır. Böylece iki farklı sınıflandırma ölçütünü tek özellik sanmazsın. Hücrenin yaşamsal olayları birlikte yürütmesi, sonraki sayfalardaki beslenme ve enerji elde etmenin de hücresel temele dayandığını gösterir.'
    ], 'Hücresel Yapı açıklamasındaki çekirdek düzeni ile tek/çok hücrelilik örneklerini ayrı ayrı izle.', 'Tek hücreli bir canlının ökaryot olması neden mümkündür?', 'Hücre sayısı kaç hücre bulunduğunu, ökaryotluk ise kalıtsal maddenin zarla çevrili çekirdekte bulunmasını anlatır. Bu iki ölçüt birbirini dışlamaz.'),
    s('Beslenme', [10], [
      'Beslenme başlığını, canlının büyüme, onarım ve metabolizma için madde sağlaması olarak oku. Kitabın üretici ve tüketici örneklerinde temel soru, organik besinin nasıl elde edildiğidir. Ototrof canlılar inorganik maddelerden organik besin sentezleyebilir. Heterotrof canlılar organik maddeleri hazır alır. Bitkinin ağızla yemek almaması, beslenme gerçekleştirmediği anlamına gelmez.',
      'Sayfadaki açıklamaları madde girişi açısından takip et. Bir üretici de çevresinden su ve mineral gibi maddeler alır; organik besin üretmesi bütün gereksinimlerini dışarıyla ilişki kurmadan sağladığı anlamına gelmez. Beslenme biçimini belirlerken yalnız su alımına bakmak yeterli değildir. Organik maddeyi üretme veya hazır alma ayrımını kullan. Bu ayrım, ekosistem bölümündeki üretici-tüketici ilişkilerinin de başlangıcıdır.'
    ], 'Beslenme bölümündeki ototrof ve heterotrof örneklerinde organik maddenin kaynağını bul.', 'Fotosentez yapan bir bitki neden yine de beslenir?', 'Beslenme gerekli maddelerin sağlanmasıdır. Bitki organik besinini sentezler; bu sentez ve diğer yaşamsal işler için çevreden su, mineral ve karbondioksit gibi maddeler alır.'),
    s('Besinlerden Enerji Elde Etme ve Boşaltım', [11], [
      'Kitap besinlerden enerji elde etmeyi beslenmeden sonra ele alıyor. Bu sıra önemlidir: bir besinin sağlanması ile onun enerjisinin hücresel işlerde kullanılabilir biçime aktarılması farklı basamaklardır. Solunum ve fermantasyon açıklamalarını okurken ortak sonucu, hücrenin ATP gereksiniminin karşılanmasını izle. Oksijen kullanımının bütün canlılara ortak olduğu sonucuna gitme.',
      'Aynı sayfadaki Boşaltım başlığı metabolizma sonucunda oluşan atıkların uzaklaştırılmasıyla ilgilidir. Bunu sindirim kanalındaki sindirilmemiş besinlerin atılmasıyla özdeşleştirme. Kitabın örneklerinde oluşan maddenin kaynağını sorgula: hücre tepkimelerinde oluşmuşsa metabolik atıktır. Tek hücreli canlılarda da metabolik atık oluştuğu için boşaltım ihtiyacı vardır; böbreğin bulunması bu özelliğin koşulu değildir.'
    ], 'Enerji elde etme yollarının açıklamaları ile Boşaltım başlığının örneklerini sırayla oku.', 'Bir canlının oksijen kullanmaması, enerji elde etmediğini gösterir mi?', 'Göstermez. Canlılar farklı enerji elde etme yolları kullanabilir. Ortak ihtiyaç ATP ile enerji aktarımıdır; bunun tek yolu oksijenli solunum değildir.'),
    s('Hareket ve Uyarılara Tepki', [12], [
      'Hareket başlığındaki örnekleri, bütün canlının yer değiştirmesi ile canlıdaki bir yapının hareketini ayırarak incele. Hayvanın yürümesi kolay fark edilir; bir bitkinin yönelme hareketi veya hücre içindeki hareketler de canlılıkla ilişkilidir. Bu nedenle hareketi yalnız bir yerden başka yere gitme olarak tanımlarsan bitki örneklerini açıklayamazsın.',
      'Uyarılara Tepki başlığında ise değişiklik ile verilen yanıt arasındaki bağlantıyı kur. Işık, sıcaklık veya dokunma bir uyarı olabilir; yanıt her zaman aynı hızda veya aynı biçimde ortaya çıkmaz. Kitabın örneğinde önce hangi çevre koşulunun değiştiğini, sonra canlıda ne olduğunu söyle. Bu iki basamağı ayırmak, bir hareketin hangi uyarıyla ilişkili olduğunu açıklamana yardım eder.'
    ], 'Hareket ve Uyarılara Tepki başlıklarında uyarı ile ortaya çıkan yanıtı ayrı işaretle.', 'Bitkinin ışığa yönelmesi hangi iki ortak özellikle ilişkilidir?', 'Bitkide bir yönelme hareketi vardır ve bu hareket ışık uyarısına verilen yanıttır. Yer değiştirme olmaması hareket ve tepkinin bulunmasını engellemez.'),
    s('Metabolizma, Homeostazi ve Uyum', [13], [
      'Metabolizma başlığında önce yapım ve yıkım örneklerini ayır. Küçük moleküllerden büyük molekül kurulması anabolizma, büyük moleküllerin parçalanması katabolizmadır. İkisi birlikte metabolizmayı oluşturur. Bir olayın yıkım olması, tek başına o olayda ATP üretildiğini kanıtlamaz; olayın hangi tepkime olduğunu ayrıca bilmek gerekir.',
      'Homeostazi açıklamasında iç ortam koşullarının belirli sınırlar içinde tutulduğunu izle. Terleme gibi bir düzenleyici yanıt, sıcaklık artışının etkisini azaltır; iç ortamın hiç değişmediğini göstermez. Uyum başlığını bununla karıştırma: kalıtsal özelliklerin yaşama ve üreme başarısıyla ilişkisi, bireyin anlık düzenleyici tepkisinden farklıdır. Üç başlığı aynı örneğe rastgele uygulamak yerine tepkimenin, iç denge yanıtının veya kalıtsal özelliğin anlatılıp anlatılmadığını belirle.'
    ], 'Anabolizma-katabolizma örneklerinden sonra Homeostazi ve Uyum başlıklarının açıklamalarını karşılaştır.', 'Protein sentezi ile terleme aynı tür canlılık olayı mıdır?', 'Protein sentezi anabolik bir metabolik tepkimedir. Terleme ise ısı kaybına katkı sağlayarak homeostatik düzenlemede rol alır. Aynı canlıda bulunmaları işlevlerini aynı yapmaz.'),
    s('Organizasyon, Üreme, Büyüme ve Gelişme', [14,15], [
      'Organizasyon sayfasındaki basamakları küçükten büyüğe takip et. Çok hücreli canlılarda benzer görevli hücrelerin birlikte çalışması daha üst yapı düzeylerini mümkün kılar. Basamakları ezberlerken her birinin önceki düzeydeki birimlerin düzenlenmesiyle oluştuğunu açıklamaya çalış; çok hücreli bir örneğin düzenini tek hücreli canlıya aynen uygulama.',
      'Son sayfada Üreme ile Büyüme ve Gelişme ayrı başlıklardır. Üreme türün devamıyla ilgilidir; bir bireyin üreyememesi o bireyi cansız yapmaz. Büyüme miktar veya boyut artışını, gelişme ise yapı ve işlev bakımından olgunlaşmayı içerir. Kitabın örneklerinde hangisinin hücre sayısı/büyüklüğü, hangisinin farklılaşma ve görev kazanımı anlattığını belirle. Böylece ortak özellik sorusunda bireyin o anda yaptığı işle türün yaşam döngüsündeki özelliğini ayırabilirsin.'
    ], 'Organizasyon sırasını p14’te, Üreme ve Büyüme ve Gelişme başlıklarını p15’te izle.', 'Üreyemeyen yetişkin bir hayvanın canlılığı neden reddedilemez?', 'Üreme türün devamını sağlar. Birey hücresel düzenini ve metabolizmasını sürdürebilir, uyarılara yanıt verebilir ve iç dengesini koruyabilir; üreyememesi bu süreçleri ortadan kaldırmaz.')
  ]);

  add('bio-tyt-02', 'Canlıların Yapısında Bulunan İnorganik ve Organik Bileşikler', 'TYT-bio', 'İnorganik bileşiklerden ATP’ye kadar kitap sırasını izliyoruz. Enzimler ayrı derste 31–35. sayfalar üzerinden ayrıntılı işlenir.', [
    s('İnorganik Bileşiklerin Genel Özellikleri ve Suyun Görevleri', [16,17], [
      'Önce inorganik bileşiklerin genel özelliklerini oku, ardından suyla ilgili açıklamalara geç. Suyun çözücü olması maddelerin hücre içinde taşınmasını ve tepkime ortamında bulunmasını kolaylaştırır. Isı değişimlerine karşı gösterdiği özellikler ve buharlaşması, canlıların sıcaklık dengesinde önem taşır. Bu işlevleri suyun enerji verici bir besin olmasıyla açıklama.',
      'Kitabın su özelliklerini okurken her özellik için bir sonuç kur: çözünme madde taşınmasına, buharlaşma ısı kaybına nasıl katkı verir? Aynı sayfadaki asit-baz açıklaması ise ortamın kimyasal koşulunu anlamamızı sağlar. Bir maddenin su içinde çözünmesiyle asit veya baz olması aynı özellik değildir. Özellikleri tek bir “yararlıdır” ifadesine indirmek yerine molekülün hangi fiziksel veya kimyasal etkisinin anlatıldığını belirle.'
    ], 'Suyun Görevleri listesindeki her maddeyi yanındaki açıklamayla ilişkilendir; ardından Asit ve Bazlar başlığını oku.', 'Terlemenin serinletici etkisini suyun hangi davranışı açıklar?', 'Suyun buharlaşması için çevreden ısı alınır. Deriden su buharlaşırken ısı kaybı gerçekleşir; bu etki suyun ATP için yakıt olmasından kaynaklanmaz.'),
    s('Tuzlar ve Mineraller', [18,19], [
      'Mineral tablosunu satır satır incele. İyot, magnezyum, demir, kalsiyum ve diğer minerallerin adları aynı sınıfta bulunsa da görevleri aynı değildir. Bazıları belirli moleküllerin yapısına katılır, bazıları kemik gibi yapılarda veya sinir-kas çalışması gibi düzenleyici olaylarda rol alır. Bir minerali yalnız tek bir görevle sınırlamadan kitabın verdiği görevleri birlikte oku.',
      'Tabloda eksiklikle ilgili bir sonuç varsa önce normal görevi söyle, sonra bu görevin aksamasının sonucunu açıkla. Mineralin az miktarda gerekli olması önemsiz olduğu anlamına gelmez. Su ve minerallerin sindirimle organik yapı taşlarına ayrılması gerekmez; bunları protein veya nişastanın hidroliziyle aynı grupta düşünme. Görev, gereksinim miktarı ve enerji verme birbirinden ayrı ölçütlerdir.'
    ], 'İnsan Vücudunun Gereksinim Duyduğu Bazı Mineraller ve Görevleri tablosunu iki sayfa boyunca izle.', 'Demir ve kalsiyumun ikisinin de mineral olması görevlerinin aynı olduğunu gösterir mi?', 'Göstermez. Mineral sınıfı kimyasal bir ortaklık belirtir; demirin oksijen taşınmasıyla, kalsiyumun kemik yapısı ve düzenleyici süreçlerle ilişkisi gibi görevler ayrıca değerlendirilir.'),
    s('Organik Bileşikler, Dehidrasyon, Hidroliz ve Karbonhidratlar', [20,21,22,23,24], [
      'p20’deki okları suyun yönüne bakarak oku. Basit organik maddelerden daha büyük bir yapı kurulurken dehidrasyonda su açığa çıkar; hidrolizde bağların parçalanması için su kullanılır. Birbirinin tersi yönleri gösteren okların yalnız “madde büyüdü/küçüldü” bilgisini değil, suyun tepkimeye katılma veya ayrılma durumunu da anlattığını gör.',
      'Monosakkaritlerden disakkarit ve polisakkaritlere doğru kitap sırasını takip et. p23’te nişasta ve glikojen depo, selüloz ve kitin yapısal başlıkları altında verilir. Nişasta, glikojen ve selülozun glikoz temelli olması görevlerini eşitlemez; birimlerin bağlanma ve düzenlenme biçimi farklı sonuçlar doğurur. p24’teki önem açıklamasını bu ayrımlarla ilişkilendir. İnsan için selülozun sindirilememesini “glikoz içermez” diye açıklamak yerine uygun enzimin bulunmamasıyla ilişkilendir.'
    ], 'p20’de Su Çıkışı/Su Girişi oklarını; p22’de birleşme tepkimelerini; p23’te depo/yapısal ayrımını izle.', 'Selüloz ile nişastanın yapı taşı ortaksa neden görevleri aynı değildir?', 'Bir molekülün görevi yalnız yapı taşının adına bağlı değildir. Bağların ve üç boyutlu düzenlenmenin farklılığı, selüloza çeper yapısında, nişastaya depolamada işlev kazandırır.'),
    s('Lipitler', [25,26,27], [
      'Lipitler bölümünde önce Yapısı başlığındaki gliserol ve yağ asidi ilişkisini izle. Trigliserit oluşumunda bir gliserolle üç yağ asidi bağlanır. Bunu çok sayıda aynı monomerden oluşan bir polisakkarit zinciri gibi düşünme. Doymuş ve doymamış yağ asitlerini karşılaştırırken kitabın gösterdiği bağ farkına bak; adların yalnız yağın bulunduğu canlı grubunu tanımlamadığını gör.',
      'p26’daki fosfolipit açıklaması depo yağından zar yapısına geçer. Suya dönük ve sudan kaçınan bölgelerin bulunması, hücre zarındaki çift tabaka düzeninin anlaşılmasına yardım eder. p27’de görev ve önem başlıklarını okurken enerji depolama, yapı oluşturma ve yalıtım gibi işlevleri ayır. “Yağdır, yalnız enerji verir” genellemesi fosfolipitlerin zar görevini açıklayamaz.'
    ], 'Trigliserit yapısını izledikten sonra p26’daki fosfolipit şeklinin farklı uçlarına ve p27’de görev listesine bak.', 'Trigliserit ile fosfolipidi yalnız enerji deposu olarak tanımlamak neden eksiktir?', 'Trigliserit depolamada önemlidir. Fosfolipitlerin suyla farklı etkileşen bölümleri zarın çift tabakasını kurmaya katkı verir; bu yapısal işlev enerji deposu tanımına sığmaz.'),
    s('Proteinler', [28,29,30], [
      'p28’de amino asit çiziminde amino, karboksil ve radikal grupları bul. Amino asitler arasında kurulan peptit bağını, çizimde birbirine bağlanan grupları izleyerek öğren. Radikal grubun değişmesi amino asit çeşitliliğiyle ilişkilidir. Bir protein yalnız amino asit sayısıyla tanımlanmaz; amino asit çeşitleri, dizilişleri ve katlanması da işlevini etkiler.',
      'p29’daki görevleri okurken enzim, taşıma, savunma ve yapısal görevleri ayrı örneklerle eşleştir. p30’daki önem ve kritik bilgi açıklamalarını molekülün yapısıyla ilişkilendir: yüksek sıcaklık gibi koşullar üç boyutlu düzeni bozduğunda işlev kaybolabilir. İşlevin kaybolmasıyla protein zincirinin bütün peptit bağlarının hidroliz edilmesi aynı olay değildir. Büyük proteinlerin sindirimi ise amino asitlerin yeniden kullanılabilmesini sağlayan ayrı bir süreçtir.'
    ], 'p28’de Peptit bağı etiketini ve amino/karboksil gruplarını; ardından Görevi ve Canlılar İçin Önemi başlıklarını izle.', 'Aynı sayıda amino asit içeren iki protein neden farklı görev yapabilir?', 'Amino asitlerin çeşidi ve sırası ile proteinin katlanma biçimi farklı olabilir. Bu farklar bağlanma bölgelerini ve işlevi değiştirir; yalnız toplam amino asit sayısı yeterli bilgi değildir.'),
    s('Vitaminler ve Hormonlar', [36,37], [
      'Vitaminler başlığında önce Görevi açıklamasını, ardından vitaminlerin gruplandırılmasını oku. Vitaminlerin organik olması onları başlıca enerji deposu yapmaz. Düzenleyici görevleri ve bazı enzimlerin çalışmasına yardımcı olmaları, enerji sağlayan besinlerle aynı ölçütle değerlendirilmemelidir. Yağda ve suda çözünen grupları, çözünme özelliği üzerinden karşılaştır.',
      'p37’de vitaminlerin önemi ve hormonların görevi ayrı başlıklardır. Hormonlar hücreler ve organlar arasında düzenleme sağlayan kimyasal habercilerdir; her hormon protein yapılı olmadığı gibi her vitamin de hormon değildir. Kitabın sınıflandırmasına bakarak bir maddenin kimyasal grubu ile işlevinin farklı bilgi türleri olduğunu gör. Bir vitaminin eksikliği belirli bir süreci aksatabilir; buradan vitaminin o süreçte yakıt olarak tüketildiği sonucu çıkarılmaz.'
    ], 'p36’daki vitamin gruplarını, p37’de ayrı açılan Hormonlar/Görevi başlığını incele.', 'Vitaminlerin organik olması neden başlıca enerji kaynağı olduklarını kanıtlamaz?', 'Organik olmak kimyasal yapı sınıfını belirtir. Vitaminler düzenleyici görevleriyle önemlidir; enerji veren besinlerin hücresel yakıt olarak kullanılması farklı bir işlevdir.'),
    s('Nükleik Asitler', [38,39,40,41], [
      'p38’de Nükleotit Yapısı şemasından başla. Bir nükleotit baz, beş karbonlu şeker ve fosfat içerir. DNA ile RNA’nın ayrımını yalnız baz adlarına indirgeme: şekerleri de farklıdır. Pürin ve pirimidin gruplarını halkalı yapılarına göre ayır; bir bazın ait olduğu grup, karşısına herhangi bir karşı grup bazının gelebileceği anlamına gelmez.',
      'p39’daki DNA açıklamalarından sonra p40–41’de mRNA, tRNA ve rRNA görevlerini oku. mRNA bilgi taşır, tRNA amino asit taşınması ve kodonla eşleşmede görev alır, rRNA ribozom yapısına katılır. p41’deki DNA ve RNA Karşılaştırması tablosunu bu bilgilerle satır satır açıkla. “RNA protein sentezinde görev yapar” ortak ifadesi, bütün RNA çeşitlerinin aynı işi yaptığını göstermez.'
    ], 'Nükleotit şemasındaki üç bileşeni; RNA çeşitlerinin çizimlerini; p41’deki DNA ve RNA Karşılaştırması tablosunu izle.', 'DNA ve RNA’daki adenin nükleotitleri neden tamamen aynı değildir?', 'Adenin bazı ve fosfat ortak olsa da şeker farklıdır: DNA’da deoksiriboz, RNA’da riboz bulunur. Nükleotidin tamamı bu üç bileşenle tanımlanır.'),
    s('ATP (Adenozin trifosfat)', [42,43], [
      'p42’de ATP’nin yapısındaki adenin, riboz ve fosfatları bul. Üç fosfat taşıması, ATP’nin hücredeki enerji aktarımında görev almasıyla ilişkilidir. ATP’yi nişasta veya yağ gibi uzun süreli bir besin deposu olarak düşünme; hücre onu sürekli sentezleyip kullanır. ATP üretimi ve tüketimi hücresel işlerle bağlantılıdır.',
      'p43’te ATP + H2O → ADP + Pi ifadesini ve enerji akışını gösteren okları izle. Besinlerden enerji elde edilmesi, ATP sentezi ve ATP’nin hücresel işlerde kullanılması birbirine bağlanır. Enzimlerin aktivasyon enerjisini azaltmasıyla ATP’nin enerji aktarımını aynı görev sayma. Kitabın endergonik ve ekzergonik tepkime ayrımında enerji gerektiren işlemin başka bir dönüşümden sağlanan enerjiyle yürütülmesini açıklamaya çalış.'
    ], 'p42’de ATP molekülünü; p43’te Besindeki Enerji, ATP/ADP ve hücresel iş arasındaki okları sırayla takip et.', 'ATP ile glikojenin ikisini de yalnız enerji deposu olarak anlatmak neden yetersizdir?', 'Glikojen bir depo polisakkarittir. ATP ise hücresel işler için enerjiyi kısa süreli olarak aktaran, sürekli yenilenen bir moleküldür; aynı zaman ölçeğinde ve aynı görevde değildirler.')
  ]);

  add('bio-tyt-03', 'Enzimler', 'TYT-bio', 'Kitabın Enzimler bölümünü 31–35. sayfalar arasında, her şekil ve grafiği kendi paragrafıyla birlikte okuyacağız.', [
    s('Yapısı — aktivasyon enerjisi grafiği', [31], [
      'Yapısı başlığındaki ilk iki maddeden sonra gelen grafiğe bak. Düşey eksen enerji, yatay eksen tepkime ilerlemesidir. İki eğri aynı substrat enerji düzeyinden başlar ve aynı ürün düzeyinde biter. Aralarındaki fark, tepkime sırasında aşılması gereken tepenin yüksekliğidir. Enzimli eğrinin tepesi daha düşük olduğu için aktivasyon enerjisi azalır ve uygun koşullarda daha fazla molekül tepkimeye katılabilir.',
      'Kesikli çizgiler arasındaki aktivasyon enerjisi oklarını başlangıç düzeyinden tepeye kadar izle. Bunlar ürün ile substrat arasındaki toplam enerji farkını göstermez. Enzim enerji üretip sisteme yakıt sağlamaz; daha düşük enerji engelli bir tepkime yolu sağlar. Aynı ürün düzeyine ulaşılması, enzimin tepkimenin ürününü veya giren-ürün enerji farkını değiştirmediğini görmene yardım eder. Eğrinin yüksekliğini ürün miktarı ya da tepkime hızı olarak okuma; hız bu enerji engelinden etkilenir ama grafiğin düşey ekseni enerji olarak etiketlidir.'
    ], 'Enerji–Tepkime İlerlemesi grafiğinde iki tepeyi, ortak başlangıç/bitiş düzeylerini ve aktivasyon enerjisi oklarını karşılaştır.', 'Enzimli eğrinin daha alçak tepeye sahip olması ürünlerin daha az enerji taşıdığını gösterir mi?', 'Hayır. Ürünlerin son enerji düzeyi iki eğride aynıdır. Azalan büyüklük başlangıçtan tepeye kadar gereken aktivasyon enerjisidir; girenlerle ürünler arasındaki enerji farkı değişmez.'),
    s('Enzimin Yapısı — Basit Enzim ve Bileşik Enzim (Holoenzim)', [31], [
      'Enerji grafiğinin altındaki sınıflandırmayı sırayla oku. Basit enzim yalnız protein kısmından oluşur. Bileşik enzimde protein kısım ile yardımcı kısım birlikte bulunur. Protein kısmına apoenzim, tamamına holoenzim denir. Sayfadaki dallanma şeması önce basit/bileşik ayrımını, sonra bileşik enzimin yardımcı kısmındaki koenzim/kofaktör ayrımını gösterir.',
      'Yardımcı kısım organik olduğunda koenzim, metal iyonları gibi inorganik olduğunda kofaktör olarak adlandırılır. Kitap metninde “kofaktör” sözcüğü önce yardımcı kısmın genel adı olarak da kullanıldığı için şemadaki organik-inorganik ayrımını özellikle izle. Hatırlayalım kutusunda apoenzimin substratı tanıması, yardımcı kısmın dönüşümde rol alması vurgulanır. Bu görev ayrımı, her bileşenin tek başına aynı işi yaptığı anlamına gelmez; çalışan bütün, uygun apoenzim-yardımcı birlikteliğidir. Alttaki Dikkat kutusu bir yardımcı kısmın farklı apoenzimlerle kullanılabilmesini ayrıca belirtir.'
    ], 'Enzimin Yapısı ağacında Basit Enzim → yalnız protein; Holoenzim → protein + yardımcı kısım dallarını izle.', 'Bir metal iyonunun ortamda bulunması neden tek başına bütün substratların parçalanmasını sağlamaz?', 'Bileşik enzimin çalışması uygun apoenzimle yardımcı kısmın birlikteliğine bağlıdır. Substratı tanıyan protein yapısı da gereklidir; yardımcı kısmın bulunması özgül enzimin yerini tutmaz.'),
    s('Substrat, ürün ve anahtar-kilit ilişkisi', [31,32], [
      'p31’in altındaki çizimde substratın enzimin belirli bir bölgesine oturduğunu gör. p32’nin ilk maddeleri bu bölgeyi aktif bölge olarak adlandırır. Enzimin etki ettiği başlangıç maddesi substrat, dönüşüm sonunda oluşan madde üründür. Anahtar-kilit benzetmesi, her enzimin her substrata etki etmediğini anlatmak için kullanılır; benzetmenin amacı kimyasal özgüllüğü görünür kılmaktır.',
      'p31’de yeniden kullanım açıklamasını da bu çizimle ilişkilendir. Enzim bir tepkime turunun sonunda serbestleşir ve başka bir substrata bağlanabilir. Bu, enzimin hiçbir zaman eskimediği anlamına gelmez: zamanla yapısı bozulan enzimler yıkılır ve yenileri sentezlenir. Gen kontrolünde sentezlenmesi, enzimin protein kısmının hücre tarafından üretilmesiyle ilgilidir. Bir tepkime sırasında tüketilmeme ile canlının yaşamı boyunca hiç yenilenmeme farklı durumlardır.'
    ], 'p31 altındaki Substrat–Aktif bölge–Enzim çizimini, p32 başındaki özgüllük ve aktif bölge maddeleriyle birlikte oku.', 'Enzimin tepkimede tüketilmemesi, hücrenin yeni enzim sentezlemesine gerek olmadığı anlamına gelir mi?', 'Gelmez. Enzim bir tepkime turunda substrat gibi tüketilmez; fakat zamanla yapısı bozulabilir, yıkılıp yenisi sentezlenebilir. Tekrar kullanılma ile sınırsız ömür aynı özellik değildir.'),
    s('Enzimatik bir tepkimenin gerçekleşmesi', [32], [
      'Sayfanın üstündeki renkli şeridi soldan sağa takip et. A substratı B enzimine bağlanır, A-B olarak gösterilen geçici enzim-substrat bileşiği oluşur. Sonraki çizimde B enzimi yeniden serbesttir; C ve D ürünleri ayrılmıştır. Burada şekli değişen ve ürünlere dönüşen başlangıç maddesini, tepkime sonunda yeniden görünen enzimden ayır.',
      'Şeritteki artı işaretleri aynı ortamda bulunan bileşenleri, oklar ise ardışık durumları anlatır. Enzim-substrat kompleksinin oluşması enzimin substratla kalıcı olarak birleştiği anlamına gelmez. Bu geçici temas, uygun bağların dönüşmesini kolaylaştırır. Görsel parçalanma örneği üzerinden çizilmiştir; bundan bütün enzimlerin yalnız büyük molekülleri parçaladığı sonucu çıkmaz. Enzimler yapım tepkimelerinde de görev alır. Bu şemada öğreneceğin temel düzen, bağlanma–geçici kompleks–ürünün ayrılması–enzimin yeniden kullanılabilmesidir.'
    ], 'A + B → A-B → B + C + D dizisinde B’nin ilk ve son durumunu karşılaştır.', 'Şekilde ürünler C ve D iken B neden ürün sayılmaz?', 'B başlangıçta da bulunan enzimdir ve tepkime sonunda yeniden serbestleşir. Ürünler substrat A’nın dönüşümüyle ortaya çıkan C ve D’dir; B substratın tüketilip oluşan yeni bir ürünü değildir.'),
    s('Karbonik anhidrazın tersinir çalışması ve katalaz', [32], [
      'İlk şemadan sonra karbonik anhidraz örneğine geç. CO2 ile suyun karbonik aside dönüşümü ve bunun ters yönü iki karşılıklı okla gösterilmiştir. Doku ve akciğer kılcallarındaki koşullarla bağlantılı olarak tepkimenin farklı yönleri önem kazanır. Aynı enzimin uygun koşullarda iki yönü de hızlandırabilmesi tersinir çalışmayı anlatır; enzimin tek başına yönü keyfî biçimde seçtiği anlamına gelmez.',
      'Hemen altındaki Dikkat kutusunda katalazın hidrojen peroksiti su ve oksijene ayırması verilir. Katalaz tepkimenin iki yanında da gösterilerek yeniden kullanılma vurgulanır. Kitap bu örneği ve sindirim enzimlerini tersinirlik genellemesinin dışında tutar. Dolayısıyla “enzimdir, mutlaka iki yönlüdür” çıkarımı yapamazsın. İki çizimi karşılaştırırken hangi maddenin dönüştüğünü, okun yönünü ve enzimin tekrar görünmesini ayrı ayrı değerlendir.'
    ], 'Karbonik anhidrazdaki karşılıklı okları, katalaz şemasındaki tek yönlü oku ve iki tarafta görünen katalazı karşılaştır.', 'Enzimin yeniden kullanılabilmesi ile tepkimenin tersinir olması aynı özellik midir?', 'Değildir. Yeniden kullanım enzimin tepkime sonunda tüketilmeden kalmasını anlatır. Tersinirlik tepkimenin iki yönde yürütülebilmesiyle ilgilidir. Katalaz örneğinde enzim yeniden kullanılırken şema tek yönlüdür.'),
    s('Üretim yeri, çalışma yeri ve enzimlerin adlandırılması', [32], [
      'Katalaz kutusundan sonraki madde, enzimlerin hücre içinde üretildiğini fakat hücre içinde veya dışında çalışabildiğini söyler. Bu iki yeri ayır. Sindirim boşluğunda çalışan bir enzim, orada hücre olmadan kendiliğinden üretilmiş değildir; bir hücre tarafından sentezlenip dışarı verilmiş olabilir. Çalışma ortamı ile sentez yeri farklı sorulara yanıt verir.',
      'Sonraki adlandırma maddesinde lipaz, maltaz ve sükraz örneklerini substratlarıyla eşleştir. Ardından pepsinojen ve tripsinojenin inaktif öncüller olduğunu oku. İsimdeki “jen” ekinin kalkması, protein yapılı öncülün etkin bir biçime dönüştürülmesiyle ilişkilidir. İki ad farklı konumlarda kullanıldığında bunları mutlaka iki bağımsız görevli enzim sayma. Bu ayrım, p35’te HCl’nin pepsinojeni etkinleştirmesi anlatılırken yeniden kullanılacak.'
    ], '“Hücre içinde üretilir” maddesini, lipaz/maltaz/sükraz ve pepsinojen/tripsinojen örneklerini sırayla oku.', 'Bağırsak boşluğunda çalışan bir enzimin hücre dışında sentezlendiği söylenebilir mi?', 'Söylenemez. Kitap üretim ve çalışma yerini ayırır. Enzim hücre içinde sentezlenip salgılanabilir; hücre dışında etkili olması üretimin de orada gerçekleştiğini göstermez.'),
    s('Amilaz ve maltazın takım hâlinde çalışması; geri besleme', [32], [
      'Alt yarıdaki iki tepkimeyi yukarıdan aşağıya oku. Amilazın nişasta üzerindeki etkisiyle oluşan ürünler arasında maltoz vardır. İkinci satırda maltoz, maltazın substratı olarak kullanılır ve glikozlar oluşur. Birinci enzimin ürününün ikinci enzimin başlangıç maddesi olması, “takım hâlinde çalışma” ifadesinin somut karşılığıdır. İki enzimin aynı maddeye aynı işi yaptığını söylemek yerine aralarındaki madde aktarımını takip et.',
      'Her iki satırda da suyun bulunduğunu gör; burada besinin daha küçük birimlere ayrılması hidrolizle ilişkilidir. Şeklin altındaki geri besleme paragrafı son ürün birikiminin tepkime hızını azaltabilmesini anlatır. Bu sayfada ayrıntılı bir düzenleme döngüsü çizilmediği için yalnız şekilden belli bir geri besleme bağlanma bölgesi çıkarmaya çalışma. Öğrenilecek bağlantı, ardışık enzimlerin ürün/substrat ilişkisi ve ürün miktarının süreç üzerindeki düzenleyici etkisidir.'
    ], 'Üst satırdaki Maltoz etiketini alt satırın başlangıcındaki Maltoz ile birleştir; ardından feed back paragrafını oku.', 'Maltazın etkinliği azalırsa bu takımın son ürünü olan glikoz oluşumu neden etkilenebilir?', 'Maltozdan glikoza geçişi maltaz yürütür. Amilaz maltoz oluşturmaya devam etse bile sonraki basamak yavaşlarsa maltozun glikoza dönüşümü sınırlanabilir; ardışık basamaklar birbirine bağlıdır.'),
    s('Enzimlerin Çalışmasına Etki Eden Faktörler — Sıcaklık', [33], [
      'Önce Sıcaklık başlığındaki paragrafı, sonra altındaki grafiği oku. Düşey eksen tepkime hızı, yatay eksen sıcaklıktır. Bu örnekte eğri 37°C civarında tepeye ulaşır, daha yüksek sıcaklıklarda düşer. Tepe, çizilen enzimin bu koşullarda en iyi çalıştığı optimum değeri gösterir. Bu sayıyı bütün canlıların bütün enzimleri için ortak bir sabit yapma.',
      'Düşük sıcaklıkta moleküler hareket ve uygun karşılaşmalar azalır; kitap çok düşük sıcaklıkta inaktif durumda kalan enzimin yapısı korunursa ısınınca yeniden çalışabileceğini vurgular. Yüksek sıcaklıkta ise protein yapısının bozulması aktif bölgenin görevini kaybetmesine yol açabilir. Yapısı tamamen bozulan enzimi soğutmak, onu yeniden çalışır hâle getirmeyi garanti etmez. Grafiğin iki yanındaki düşük hızlar aynı nedenden doğmadığı için “soğuk da sıcak da yalnız yavaşlatır” açıklaması yeterli değildir.'
    ], 'Grafikte 0, 20, 37 ve 50°C noktalarını; 37’deki kesikli çizgiyi ve tepe sonrası düşüşü izle.', '0°C’de ve yüksek sıcaklıkta etkinliğini kaybeden iki enzim uygun sıcaklığa getirildiğinde neden farklı davranabilir?', 'Düşük sıcaklıkta yapı korunmuşsa etkinlik geri dönebilir. Yüksek sıcaklık protein yapısını tamamen bozmuşsa aktif bölge işlevini kaybedebilir; koşulu düzeltmek tek başına bu yapıyı geri kurmaz.'),
    s('pH Derecesi — pepsin ve tripsin grafiği', [33], [
      'Sıcaklık grafiğinin altındaki pH Derecesi açıklamasını ve iki eğriyi birlikte oku. Pepsin eğrisi asidik bölgede, yaklaşık pH 2 çevresinde; tripsin eğrisi bazik bölgede, yaklaşık pH 8 çevresinde tepe yapar. İkisi aynı eksen takımında gösterildiği için çalışma ortamlarının farklılığını doğrudan karşılaştırabilirsin. Eğrilerin tepe konumları enzime özgü optimum koşulları anlatır.',
      'Aynı pH değerinde bir enzimin iyi, diğerinin zayıf çalışması çelişki değildir. pH, enzimin yapısını ve substratla etkileşmesini etkileyebilir. Bir enzimin optimum aralığını başka bir enzime taşımak, midede çalışan pepsin ile bağırsakta çalışan tripsin örneğini açıklayamaz. “Enzimler genellikle nötrde çalışır” ifadesini okurken kitabın hemen ardından verdiği bu iki örneğin genel ifadeyi sınırladığını gör. Grafiği yorumlarken önce hangi renkli eğrinin hangi enzime ait olduğunu belirle.'
    ], 'Pepsin ve Tripsin adlarının altındaki tepe noktalarını aynı pH ekseninde karşılaştır.', 'Ortam pH’sını 2’den 8’e çıkarmak her enzimin tepkime hızını artırır mı?', 'Artırmaz. Bu grafikte pH 8 tripsin için uygunken pepsin optimumundan uzaklaşır. Etki enzimin kendisine ve başlangıç koşuluna bağlıdır; tek bir pH değişiminin bütün enzimlere aynı sonucu vereceği söylenemez.'),
    s('Enzim ve Substrat Miktarı — substrat yeterliyken', [33], [
      'Sayfanın son grafiğinde yatay eksen enzim derişimi, düşey eksen tepkime hızıdır. Çizginin üstündeki “Substrat yeterli” ifadesi grafiğin temel koşuludur. Bu koşul altında enzim miktarı arttıkça aynı anda substrata bağlanabilecek aktif bölge sayısı artar. Birim zamanda oluşan ürün miktarı, yani hız, artabilir. Grafikte enzim miktarını artırırken substratın yeterliliğinin korunduğu varsayılır.',
      'Bu grafik p34’teki sabit enzim grafiğiyle karıştırılmamalıdır. Burada değiştirilen enzim, orada substrattır. Her grafikten önce değişen ekseni ve sabit tutulan koşulu söylemek, ezberlenen “önce artar sonra sabit” kalıbının yanlış grafiğe uygulanmasını önler. Ayrıca hız ile birikmiş toplam ürün farklı büyüklüklerdir. Birim zamanda daha çok ürün elde etmek, başlangıçta sınırlı verilen toplam substrattan elde edilebilecek son ürün miktarının mutlaka artması anlamına gelmez.'
    ], '“Substrat yeterli” notunu ve Enzim derişimi eksenini birlikte oku.', 'Yeterli substrat varken enzim miktarının artırılması neden hızı artırabilir?', 'Daha fazla enzim, aynı anda çalışan daha fazla aktif bölge sağlar. Substrat ve diğer koşullar sınırlayıcı değilse birim zamanda daha fazla substrat ürüne dönüşebilir.'),
    s('Sınırlı enzim miktarının reaksiyon hızına etkisi', [34], [
      'p34’ün ilk grafiğinde yatay eksen substrat konsantrasyonu, düşey eksen tepkime hızıdır. Eğrinin yanındaki “x kadar enzim varken” notu enzim miktarının sabit olduğunu belirtir. Başlangıçta substrat eklenmesi uygun karşılaşmaları artırır ve hız yükselir. Eğrinin yataylaştığı bölgede enzimlerin aynı anda çalışabilme kapasitesi sınıra yaklaşmıştır.',
      'Yatay bölümde eğri sıfıra inmiyor; tepkime belirli bir hızla sürüyor. Bu yüzden plato “ürün oluşumu durdu” diye okunmaz. Aynı süre boyunca ürün birikmeye devam edebilir. Daha fazla substrat eklemek, dolu aktif bölgelere yeni çalışma kapasitesi eklemez. Yeterli substratın bulunduğu bu durumda enzimi artırmak ise yeni aktif bölgeler sağlayabilir. p33 ve p34 grafiklerini yan yana düşün: farklı değişkenleri artırdığımız için sonuçların farklı görünmesi, koşulların farklılığından kaynaklanır.'
    ], '“x kadar enzim varken” notuna, substrat eksenine ve eğrinin sıfırın üstündeki yatay kısmına bak.', 'Plato bölgesinde ürün oluşumu neden devam eder?', 'Plato tepkime hızının yaklaşık sabit kaldığını gösterir; hız sıfır değildir. Enzimler çalışmayı sürdürür, fakat ek substrat sabit enzim miktarının eşzamanlı çalışma kapasitesini artırmaz.'),
    s('Sınırlı substrat miktarının reaksiyon hızına etkisi', [34], [
      'İkinci grafikten önceki cümle, substrat sınırlıysa substrat tükendiğinde tepkimenin biteceğini söylüyor. Bunu zamana bağlı bir deney olarak düşün: dönüştürülebilecek başlangıç maddesi sınırlıdır ve tükendiğinde yeni ürün üretimi için madde kalmaz. Enzimin kendisi tükenmiş olmak zorunda değildir. Son ürün miktarıyla son andaki hız burada farklı sorulardır.',
      'Bu çizimde bir gösterim sorunu var: yatay eksen “Enzim derişimi” olarak yazılmış, fakat azalıp sıfıra inen eğriye eşlik eden metin substratın zamanla tükenmesini anlatıyor. Bu nedenle çizimden “enzim ekledikçe bir noktadan sonra anlık tepkime hızı düşer ve sıfırlanır” kuralı çıkarma. Enzim derişimi dışında koşullar aynıysa daha fazla enzim toplam sınırlı substratı daha kısa sürede tüketebilir; substrat tükendikten sonra ölçülen hızın sıfır olması bu tüketim sonucudur. Grafiğin ekseniyle paragrafın anlattığı süreci birlikte denetlemek gerekir.'
    ], 'İkinci grafiğin Enzim derişimi eksenini, Substrat sınırı notunu ve üstündeki “substrat bitince” cümlesini karşılaştır.', 'Substrat bitince hızın sıfırlanması enzimin tüketildiğini gösterir mi?', 'Göstermez. Dönüştürülecek substrat kalmamıştır. Enzim uygun yapısını koruyorsa yeni substratla yeniden çalışabilir. Buradaki çizim enzim miktarı ile zaman etkisini açık ayırmadığı için yalnız eğriden enzim fazlalığının hızı düşürdüğü sonucu çıkarılamaz.'),
    s('Su Miktarı', [34], [
      'Su Miktarı başlığında enzimlerin çalışmasıyla hücredeki su miktarı ilişkilendirilir. Kitabın düşük su oranı açıklamasını, suyun tepkime ortamını ve maddelerin karşılaşmasını sağlamasıyla düşün. Kurutulmuş besin, bal ve reçel örneklerinde suyun mikroorganizmaların yararlanabileceği biçimde az bulunması, etkinliklerini ve çoğalmalarını sınırlar. Böylece besinin bozulması yavaşlayabilir.',
      'Metindeki %15 ifadesi kitabın kullandığı basitleştirilmiş ders modelidir; her besin ve her mikroorganizma için evrensel bir saklama eşiği gibi kullanılmamalıdır. Gerçek korunmada suyun kullanılabilirliği, şeker/tuz, asitlik ve mikroorganizma türü de önem taşır. Bu sayfada öğrenilecek ana ilişki, yeterli suyun bulunmasının enzim etkinliği ve mikrobiyal faaliyet için önemli olmasıdır. “Daha fazla su her koşulda daha hızlı tepkime” de deme; kitap aşırı artışta hızın azalabileceğini ayrıca belirtir.'
    ], 'Su Miktarı altındaki düşük su, su artışı ve gıda örneklerini üç ayrı durum olarak oku.', 'Kurutulmuş meyvenin yeniden nemlenmesi bozulma olasılığını neden artırabilir?', 'Mikroorganizmaların ve enzimlerin yararlanabileceği su artabilir. Uygun diğer koşullarla birlikte metabolik etkinlik ve çoğalma kolaylaşır; kurutmanın sağladığı sınırlama azalır.'),
    s('Substrat Yüzeyi', [34], [
      'Substrat Yüzeyi paragrafından sonra Püf Nokta kutusunu oku. Enzimlerin substratla temas etmesi gerekir. Aynı miktardaki katı substrat küçük parçalara ayrıldığında toplam dış yüzey artar; enzimlerin erişebildiği temas alanı büyüyebilir. Kutudaki iyice çiğneme ve kıyılmış et örnekleri bu ilişkiyi günlük bir duruma taşır.',
      'Alttaki grafikte yatay eksen substrat yüzeyi, düşey eksen reaksiyon hızıdır. Çizgi, karşılaştırılan koşullarda yüzey artışının hızı artırmasını temsil eder. Bu değişimi enzim miktarının artması veya substratın toplam kütlesinin çoğalmasıyla karıştırma. Aynı besin miktarı farklı büyüklükte parçalara ayrılabilir. Mekanik parçalama tek başına besinin bütün kimyasal bağlarını hidroliz etmek değildir; enzimatik sindirimin daha geniş yüzeyden ilerlemesine yardım eder. Sonuç, deneyin diğer koşullarıyla birlikte değerlendirilir.'
    ], 'Püf Nokta kutusundaki kıyılmış et–kuşbaşı et örneğini Substrat yüzeyi–Reaksiyon hızı grafiğine bağla.', 'Eşit kütlede etin kıyılması sindirimi neden hızlandırabilir?', 'Toplam dış yüzey artar ve sindirim enzimlerinin temas edebileceği alan genişler. Etin kütlesi veya enzimin miktarı artmak zorunda değildir; değişen büyüklük erişilebilir substrat yüzeyidir.'),
    s('Aktivatör ve İnhibitör Etkisi, Görevi ve Canlılar İçin Önemi', [35], [
      'Son sayfada önce aktivatör ve inhibitör maddelerini oku. HCl’nin pepsinojeni etkin pepsine dönüştürmesi, p32’deki inaktif öncül adlandırmasını tamamlar. İnhibitörler etkinliği yavaşlatabilir veya durdurabilir; kitap ağır metal ve bazı zehir örneklerini bu başlıkta verir. Ortam koşullarının enzimin yapısına etkisiyle belirli bir maddenin enzimi inhibe etmesi aynı mekanizma olmak zorunda değildir.',
      'Görevi başlığı p31’deki grafiğe geri döner: enzim enerjiyi sağlamaz, aktivasyon enerjisini azaltır. Canlılar İçin Önemi bölümündeki süt, dondurucu, kurutulmuş meyve ve reçel görsellerini buna bağla. Isıtma enzimin yapısını bozabilir; soğutma ve suyun azaltılması etkinliği sınırlar. Bunlar aynı etki değildir. Görsellerdeki saklama örneklerini “her koşulda bozulma tamamen önlenir” iddiası olarak okumadan, enzim etkinliğinin yaşam ve gıda üretimindeki rolünü açıklayan örnekler olarak değerlendir. Son paragraf da endüstride enzim kullanımını bu önemle ilişkilendirir.'
    ], 'HCl–pepsinojen örneğini, Görevi başlığını ve kaynatılan süt/dondurucu/kurutma/reçel fotoğraflarını sırayla incele.', 'Kaynatma ve dondurma örneklerinin enzim üzerindeki etkisini nasıl ayırırsın?', 'Yüksek sıcaklık protein yapısını bozabilir; düşük sıcaklıkta yapı korunurken etkinlik azalabilir ve uygun koşullarda geri dönebilir. İki uygulama mikrobiyal faaliyeti farklı yollarla sınırlar; düşük etkinlik her durumda yapının bozulduğunu göstermez.')
  ]);

  add('bio-tyt-04', 'Hücresel Yapılar ve Görevleri', 'TYT-bio', 'Hücre konusunu 46–63. sayfalarda, hücre teorisinden plastitlere kadar kitabın başlık sırasıyla okuyacağız.', [
    s('Hücre Teorisi, Prokaryot ve Ökaryot Hücre Yapısı', [46,47,48,49], [
      'Bölümün başlangıcını okuduktan sonra p48’de Hücre Teorisi başlığına gel. Canlıların hücrelerden oluşması, hücrenin temel yapı ve görev birimi olması ve yeni hücrelerin mevcut hücrelerden oluşması birbiriyle bağlantılıdır. Bu açıklama hücrenin yalnız bir yapı taşı olmadığını, yaşamsal süreçleri yürüten bir düzen olduğunu gösterir.',
      'p48’deki prokaryot örneğini p49’daki ökaryot hücreyle karşılaştır. Zarla çevrili çekirdek ve zarlı organeller ayrımı belirler. Prokaryotta ribozom bulunur; zarlı organel bulunmaması protein sentezi veya enerji dönüşümünün bulunmadığı anlamına gelmez. Tek hücrelilik ile prokaryotluğu aynı sayma; karşılaştırmada çekirdek düzenini esas al.'
    ], 'p48 Prokaryot Hücre ve p49 Ökaryot Hücre çizimlerinde kalıtsal maddenin konumunu bul.', 'Bir bakteride mitokondri olmamasından ATP üretemediği sonucu çıkar mı?', 'Çıkmaz. Mitokondri ökaryot hücrenin belirli enerji dönüşümlerini yürüttüğü organeldir. Bakteriler kendi enzim ve zar düzenleriyle ATP sentezleyebilir.'),
    s('Hücre Zarı, Hücre Duvarı, Sitoplazma, Çekirdek', [50,51,52,53], [
      'p50’deki zar açıklamasında üç temel molekül grubunu ve bunların çizimdeki yerlerini izle. Fosfolipitlerin çift tabakasıyla proteinlerin yerleşimi birlikte seçici geçirgen bir sınır oluşturur. Hücre duvarı ile hücre zarı aynı yapı değildir; bitki hücresinde ikisinin birlikte bulunması görevlerinin farklı olduğunu görmeyi sağlar.',
      'Devam sayfalarında sitoplazma ve çekirdeğe geç. Sitoplazma yalnız organellerin arasında kalan boşluk değildir; çok sayıda tepkimenin gerçekleştiği ortamdır. Çekirdeğin kalıtsal maddeyle ilişkisini, hücre faaliyetlerinin düzenlenmesiyle bağla. Zardaki protein, sitoplazmadaki enzim ve çekirdekteki DNA aynı kimyasal türde veya aynı görevde değildir. Şekillerde bir yapının sınırını bulup sonra işlevini söylemek isim ezberinden daha sağlamdır.'
    ], 'p50’de Hücre zarının 3 temel molekülü vardır ifadesinin altındaki molekülleri; devamında çeper ve çekirdek sınırlarını izle.', 'Bitki hücresindeki çeper neden hücre zarının yerine geçmez?', 'Çeper destek ve dayanıklılık sağlar; hücre zarı ise hücre içi ile dışı arasındaki seçici madde alışverişinde görev yapar. Birinin varlığı diğerinin görevini ortadan kaldırmaz.'),
    s('Ribozom ve Endoplazmik Retikulum', [54,55], [
      'p54’te Ribozom = rRNA + protein ifadesini oku. Ribozom zarsızdır ve protein sentezinde görev yapar. Bu yapı prokaryotlarda da bulunduğu için protein sentezini yalnız çekirdekli hücrelere özgü sayamazsın. Ribozomun protein üretmesiyle bir proteinin daha sonra düzenlenip paketlenmesi farklı basamaklardır.',
      'p55’te granüllü ve granülsüz endoplazmik retikulumu karşılaştır. Granüllü görünümü ribozomlarla ilişkilendir; salgılanacak bazı proteinler bu sistemle bağlantılı üretilip işlenir. Granülsüz ER’nin görevlerini de ayrı oku. Her hücresel proteinin mutlaka ER’den geçeceği sonucuna gitme. Kitabın yapı-görev düzenini izleyerek önce ribozomun sentezini, ardından zar sistemi içindeki işleme ve taşımayı açıkla.'
    ], 'Ribozom bileşimini ve p55’te granüllü/granülsüz ER çizimlerinin ribozom farkını karşılaştır.', 'Bir proteinin ER üzerinden taşınması sentezi ER zarının yaptığı anlamına gelir mi?', 'Hayır. Polipeptit sentezini ribozom gerçekleştirir. ER, ilişkili proteinlerin işlenmesi ve hücre içindeki taşınma düzeninde görev alır.'),
    s('Golgi Aygıtı, Lizozom ve Koful', [56,57,58], [
      'p56’da Golgi’nin yapı ve görev açıklamalarını, bir önceki sayfadaki ER’ye bağla. Golgi gelen maddeleri düzenler, ayırır ve paketler. Salgı etkinliği yüksek bir hücrede bu işleme-paketleme düzeninin gelişmesi beklenebilir. Ancak Golgi’nin paketlediği bir proteini Golgi’nin sentezlediğini söyleme.',
      'p57’de lizozomun hidroliz enzimleriyle parçalama işlevini oku; hücre içi sindirimi ATP üretimiyle aynı işlem sayma. p58’de kofulların besin, depo, boşaltım ve kontraktil türlerini karşılaştır. Aynı genel ad altında bulunan kesecikler farklı görevlerde özelleşebilir. Kontraktil kofulu özellikle su dengesine bağla. Üç sayfada ortak olan kesecikli zar düzeni, bütün bu yapıların aynı maddeleri aynı şekilde işlediğini göstermez.'
    ], 'Golgi’nin paketleme açıklamasını, lizozomun sindirim açıklamasını ve p58’deki dört koful türünü sırayla incele.', 'Golgi ve lizozomun ikisinin de zarlı olması görevlerini aynı yapar mı?', 'Yapmaz. Golgi düzenleme ve paketlemede, lizozom hidrolizle parçalamada görev alır. Zar yapısı ortak olabilir; içerik ve yürütülen süreçler farklıdır.'),
    s('Peroksizom, Sentrozom ve Hücre İskeleti', [59,60], [
      'Bu iki sayfada organelleri birbirinin devamı olan tek bir üretim hattı gibi okumadan, kitabın ayrı yapı ve görev açıklamaları üzerinden ilerle. Peroksizomun oksidatif tepkimeler ve hidrojen peroksitin işlenmesiyle ilişkisini, lizozomun hidrolizle parçalama işlevinden ayır. İkisinin de bazı maddelerin zararlı etkilerini sınırlandırması aynı enzimleri taşıdıkları anlamına gelmez.',
      'Sentrozomu bölünme sırasında oluşan düzenle ilişkilendir. Hücre iskeletinin elemanlarını ise yalnız hücreyi sabit tutan çubuklar gibi düşünme; biçimin korunması, hücre içi taşıma ve hareket de bu sistemle bağlantılıdır. Sayfadaki elemanların görünüşünü görev cümlesiyle eşleştir. Bir yapı proteinlerden oluşabilir ama bu bilgi tek başına onun ribozom veya enzim olduğunu göstermez.'
    ], 'Peroksizom, Sentrozom ve Hücre İskeleti başlıklarının her birinde önce yapıyı, ardından verilen görevi bul.', 'Hücre iskeletinin yalnız destek sağladığını söylemek neden eksiktir?', 'Hücre iskeleti biçimin korunmasına ek olarak hareket, hücre içi taşıma ve bölünme düzeni gibi süreçlerle ilişkilidir. Destek bu işlevlerin yalnız bir bölümüdür.'),
    s('Mitokondri ve Plastitler', [61,62,63], [
      'p61’de mitokondrinin dış ve iç zarını, iç kıvrımlarını ve iç ortamını çizim üzerinde ayır. Bu bölmeler oksijenli solunumun farklı basamaklarını anlamak için önemlidir. Mitokondrinin kendi DNA ve ribozomlarına sahip olması, bütün gereksinimlerini hücreden bağımsız karşıladığı anlamına gelmez.',
      'p62’de kloroplast çiziminde stroma, tilâkoit ve granum etiketlerini bul. Fotosentezle ilişkili bu yapıyı mitokondriyle karşılaştırırken ikisini de “enerji üretir” sözüne indirgeme; gerçekleştirdikleri dönüşümler farklıdır. p63’te kromoplast ve lökoplast başlıkları plastit çeşitliliğini tamamlar. Bitkinin her hücresinin kloroplast taşımasını bekleme: depo veya renk görevi farklı plastitlerle ilişkili olabilir. Hücrenin görevi, bulunduğu doku ve plastit türü birlikte değerlendirilir.'
    ], 'p61 mitokondri ile p62 kloroplastın zar ve iç bölmelerini, ardından p63’te diğer plastitleri karşılaştır.', 'Bitki kökündeki bir depo hücresinde kloroplast bulunmaması neden çelişki değildir?', 'Bitkinin bütün hücreleri fotosentez yapmaz. Depo hücresinin görevi ve plastit türü farklı olabilir; bitki olmak her hücrede kloroplast bulunmasını zorunlu kılmaz.')
  ]);

  add('bio-tyt-05', 'Hücre Zarından Madde Geçişleri', 'TYT-bio', '64–71. sayfalardaki sınıflandırma, zar çizimleri, osmoz örnekleri ve kesecikli taşıma sırasını izleyeceğiz.', [
    s('Hücre Zarından Madde Geçişleri ve Pasif Taşıma', [64], [
      'Önce sayfadaki sınıflandırmayı oku: küçük moleküllerin taşınması ile büyük moleküllerin taşınması farklı dallarda gösterilir. Hücre zarının seçici geçirgen olması, bütün maddelerin aynı yoldan ve aynı hızla geçmediğini anlatır. Maddenin büyüklüğü, kimyasal özelliği, derişim farkı ve kullanılan yapı hangi yolun mümkün olduğunu etkiler.',
      'Pasif Taşıma açıklamasında moleküllerin kendi hareketiyle net geçişin derişim farkı yönünde gerçekleşmesini izle. Taşıma için hücrenin doğrudan ATP harcamaması, moleküllerin hareketsiz olduğu anlamına gelmez. Denge kurulduğunda iki yönlü hareket sürebilir; dengelenen, bir yöndeki fazladan geçiştir. Şekilde tek ok gördüğünde bunun çoğunlukla net yönü gösterdiğini düşün.'
    ], 'Küçük Moleküllerin Taşınması/Büyük Moleküllerin Taşınması dallarını ve Pasif Taşıma açıklamasını izle.', 'Derişim dengesi oluştuğunda moleküller tamamen durur mu?', 'Hayır. Moleküller iki yönde hareket etmeye devam eder. İki yönlü geçiş dengelendiğinde net geçiş sıfır olur.'),
    s('Basit Difüzyon, Kolaylaştırılmış Difüzyon ve Diyaliz', [65,66], [
      'p65’te iki taşıma yolunu karşılaştır. Basit difüzyonda uygun küçük moleküller zarın lipit tabakasından geçebilir. Kolaylaştırılmış difüzyonda kanal veya taşıyıcı protein kullanılır. Her ikisinde de madde kendi gradyanı yönünde ilerler; protein kullanılması tek başına aktif taşıma kanıtı değildir.',
      'Çizimde önce maddenin yoğun olduğu tarafı belirle, sonra geçtiği yapıya bak. Böylece yön ile mekanizmayı ayrı okursun. p66’daki diyaliz açıklamasını da seçici geçirgen bir sınır üzerinden bazı maddelerin geçebilmesiyle ilişkilendir. Zarın her iki tarafında bulunan maddelerin tamamı için aynı sonucu varsayma; geçebilen ve geçemeyen maddeyi ayrı değerlendirmek gerekir. Basit difüzyonun adı, olayın canlıdan bağımsız bütün zarlar için sınırsız geçiş sağladığı anlamına gelmez.'
    ], 'p65’te iki zar çiziminde proteinin kullanılıp kullanılmadığını; p66’da geçebilen maddeyi bul.', 'Bir iyon kanalının kullanılması neden aktif taşımayı kesinleştirmez?', 'Kanal aracılı geçiş gradyan yönünde kolaylaştırılmış difüzyon olabilir. Aktif taşımayı değerlendirmek için enerji kullanımı ve taşınma yönü de bilinmelidir.'),
    s('Osmoz', [67], [
      'Osmoz sayfasında hareket eden maddenin su olduğunu baştan belirle. Seçici geçirgen zarın iki tarafında suyun ve çözünen maddenin durumunu karşılaştır. Basınç etkilerinin başlangıçta aynı olduğu basit modelde su, çözünen madde bakımından daha seyreltik taraftan daha derişik tarafa net geçer. Çözünen maddenin zarı geçip geçememesi bu yorumda önemlidir.',
      'Osmotik basınç, turgor basıncı ve emme kuvvetiyle ilgili açıklamaları aynı nicelikler sanma. Çözünen madde etkisi su alma eğilimini artırırken oluşan basınç bu net hareketi dengeleyebilir. Kitabın düzeneklerinde seviyeler veya basınçlar değiştiğinde yalnız başlangıçtaki derişim okunu sonsuza kadar sürdürme. Dengenin kurulması, su moleküllerinin hareketinin bitmesi değil net geçişin dengelenmesidir.'
    ], 'Osmoz düzeneğinde zarı, suyun net yönünü ve basınçla ilgili açıklamaları birlikte incele.', 'Derişik tarafın su alması neden sonsuza kadar aynı hızla sürmez?', 'Su geçişi derişimleri ve varsa sıvı düzeyi/basıncını değiştirir. Karşı etkiler net hareketi azaltıp dengeleyebilir; başlangıç koşulları sabit kalmaz.'),
    s('Çözelti Çeşitleri ve Osmoza Bağlı Gerçekleşen Olaylar', [68], [
      'Dış ortamı hücre içiyle karşılaştırarak hipertonik, izotonik ve hipotonik adlarını kullan. Hipertonik dış ortam hücreden net su çıkışına, hipotonik dış ortam hücreye net su girişine yol açabilir. İzotonik durumda su iki yönde dengeli geçer. Çözeltinin adını, hangi hücreye göre karşılaştırıldığı belirtilmeden mutlak bir özellik gibi söyleme.',
      'Bitki ve hayvan hücresi çizimlerini aynı dış ortamda karşılaştır. Hayvan hücresi aşırı su alımında parçalanabilirken bitki hücresinin çeperi genişlemeyi sınırlar ve turgor gelişir. Bitki hücresinin su kaybında zarın çeperden uzaklaşması plazmolizdir; çeperin de zarla aynı biçimde büzüldüğünü varsayma. Çizimlerde özellikle zar-çeper aralığının değişimini izle.'
    ], 'Aynı çözelti koşulundaki bitki ve hayvan hücrelerini; bitkide zar ile çeperin konumunu karşılaştır.', 'Hipotonik ortamda bitki ve hayvan hücrelerinin farklı sonuç göstermesini hangi yapı açıklar?', 'Bitki hücresindeki çeper genişlemeyi sınırlar ve turgor basıncı oluşmasına katkı verir. Hayvan hücresinde aynı sert çeper desteği bulunmaz.'),
    s('Aktif Taşıma', [69], [
      'Aktif Taşıma sayfasında taşıyıcı protein ve enerji kullanımını, maddenin taşınma yönüyle birlikte incele. Hücre belirli maddeleri gradyanlarına karşı taşıyarak iç ve dış ortam arasında farklı derişimleri sürdürebilir. Bu farklılık kendiliğinden dengelenmeye karşı korunduğu için enerji gerektirir.',
      'Pasif taşımayla karşılaştırırken yalnız proteinin bulunmasına bakma. Kolaylaştırılmış difüzyon da protein kullanır; ayrımı belirleyen temel noktalardan biri enerjiyle yürütülen gradyana karşı taşımadır. Çizimde başlangıçta hangi tarafta maddenin daha fazla olduğunu ve okun nereye yöneldiğini söyle. Aktif taşımanın küçük maddelerle ilişkisini de p64 sınıflandırmasına geri bağla; büyük parçacıkların kesecikle alınması sonraki başlığın konusudur.'
    ], 'Taşıyıcı proteini, ATP kullanımını ve düşük/yüksek derişim taraflarını aynı çizimde bul.', 'Taşıma proteini ile ATP bilgisini birlikte bilmek neden daha güçlü bir kanıttır?', 'Protein kullanımı pasif taşımada da görülebilir. Enerji kullanımı ve gradyana karşı yön bilgisi aktif taşımanın mekanizmasını ayırt etmeyi sağlar.'),
    s('Endositoz ve Ekzositoz', [70,71], [
      'p70’te endositozu, hücre zarının içeri doğru şekillenip maddeyi kesecik içine alması olarak takip et. Fagositoz ve pinositoz çizimlerinde alınan maddenin özelliklerini karşılaştır. Maddenin zarın lipit tabakasından tek tek geçmesiyle, zarla çevrili bir kesecik içinde alınması aynı yol değildir.',
      'p71’de ekzositoz şemasında hücre içindeki keseciğin zarla birleşip içeriğini dışarı verdiğini izle. Kitabın Endositoz ve Ekzositoz karşılaştırmasını yön, kesecik ve zar ilişkisi üzerinden oku. Enerji kullanılması bu olayları p69’daki küçük molekül taşıyıcı pompasıyla aynı mekanizma yapmaz. Bir salgı proteininin ER–Golgi–salgı keseciği yolculuğunun son basamağını bu zar birleşmesiyle ilişkilendirebilirsin.'
    ], 'p70’te içeri kesecik oluşumunu; p71’de dışarı salgılama sırasında zar birleşmesini ve karşılaştırmayı incele.', 'Ekzositozla salınan büyük bir protein zarın içinden kanal aracılığıyla mı geçer?', 'Bu mekanizmada protein bir salgı keseciğinde taşınır; kesecik hücre zarıyla birleşerek içeriğini dışarı verir. Kanal içinden tek tek geçişten farklıdır.')
  ]);

  add('bio-tyt-06', 'Hücre Döngüsü ve Mitoz', 'TYT-bio', '101–108. sayfalarda bölünme gereksinimi, interfaz, mitoz, sitokinez, sayı grafikleri ve döngü kontrolünü takip edeceğiz.', [
    s('Hücre Neden Bölünür? ve kromozomun yapısı', [101], [
      'Sayfanın ilk sorusunu hücre büyüdükçe yüzey ve hacmin aynı oranda değişmemesiyle ilişkilendir. Madde alışverişi yüzey üzerinden gerçekleşirken hücrenin gereksinimleri hacimle bağlantılıdır. Bölünme gereksinimini yalnız hücrenin dış görünüşte büyümesi olarak açıklama; madde alışverişi ve hücresel yönetim de birlikte düşünülür.',
      'Aynı sayfadaki kalıtsal madde çiziminde nükleotit, kromozom, kromatit ve kinetokor etiketlerini izle. DNA eşlendiğinde bir kromozom iki kardeş kromatitli hâle gelebilir; kromatit sayısıyla kromozom sayısı aynı sayım değildir. Mitoz evrelerini okumadan önce bu kelimeleri çizimde doğru yapıya bağlamak, daha sonra hangi yapının ayrıldığını anlamanı sağlar.'
    ], 'Hücre Neden Bölünür? açıklamasından sonra kromozom çizimindeki Kromatit ve Kinetokor etiketlerini bul.', 'DNA eşlenmesi her durumda kromozom sayısının hemen iki katına çıkması mıdır?', 'Hayır. Eşlenme sonrası kardeş kromatitler birbirine bağlıyken kromozom sayımı değişmez; DNA miktarı artar. Kardeşlerin ayrılması farklı bir aşamadır.'),
    s('Hücre Döngüsü ve İnterfaz', [102,103], [
      'Döngü şemasında interfazı mitotik evreden ayır ve G1, S, G2 sırasını takip et. İnterfaz hücrenin hiçbir iş yapmadığı bir bekleme dönemi değildir. Büyüme, gerekli maddelerin sentezi ve bölünmeye hazırlık sürer. S evresinde DNA eşlenmesi, kalıtsal bilginin iki hücreye aktarılmasının ön koşulunu oluşturur.',
      'Her evrede hangi niceliğin değiştiğini ayrı söyle. DNA miktarı artarken kromozom sayısı aynı kalabilir; organeller ve proteinler de hazırlık sürecinin parçalarıdır. Döngü şemasındaki bir dilimin büyüklüğünü bütün hücre türleri için değişmez süre olarak kullanma. Hücrenin tipi ve koşulları süreyi etkileyebilir. Devam sayfasındaki açıklamaları bu sıra üzerine yerleştirerek mitoz öncesi hazırlığın mantığını kur.'
    ], 'Hücre döngüsünde G1 → S → G2 → mitotik evre sırasını ve S evresindeki eşlenme açıklamasını izle.', 'İnterfazın dinlenme dönemi denmesi neden yanıltıcıdır?', 'Hücre büyüme, sentez, metabolizma ve DNA eşlenmesi gibi etkin süreçleri yürütür. Bölünme şekillerinin henüz görülmemesi hücresel etkinliğin durduğu anlamına gelmez.'),
    s('Mitozun Genel Özellikleri ve Mitotik Evre', [104], [
      'Mitozun Genel Özellikleri maddelerini okumadan doğrudan evre adlarına geçme. Temel amaç eşlenmiş kalıtsal bilginin iki çekirdeğe düzenli dağıtılmasıdır. Normal mitoz sonucunda oluşan hücrelerde başlangıç hücresinin kromozom sayısı korunur. Bu ifade, olayın yalnız diploit hücrelerde gerçekleşebileceğini söylemez.',
      'Sayfadaki interfaz ve mitotik evre ayrımını p102’deki döngüyle birleştir. DNA’nın eşlenmesi hazırlıkta olur; mitoz aynı DNA’yı yeniden çoğaltma işlemi değildir. Çekirdek bölünmesi ile sitoplazma bölünmesini de ayrı tut. İkisi aynı bölünme sürecinin parçalarıdır ama farklı yapıların ayrılmasını anlatır. Bu ayrım sonraki iki sayfada çizilen evreler ile sitokinez görsellerini doğru okumaya yardım eder.'
    ], 'İnterfaz ve Mitotik Evre etiketlerini, Mitozun Genel Özellikleri maddeleriyle birlikte oku.', 'Haploit bir hücre mitoz geçirirse yavru hücreler neden zorunlu olarak diploit olmaz?', 'Mitoz kromozom takımını ikiye katlayan bir olay değildir; eşlenmiş bilgiyi dağıtarak başlangıç kromozom sayısının korunmasını sağlar. Haploit başlangıçtan normalde haploit yavrular oluşur.'),
    s('Mitoz (Karyokinez): Profaz, Metafaz, Anafaz, Telofaz', [105], [
      'Evre çizimlerini sırasıyla izle. Profazda kromozomlar belirginleşir ve bölünme düzeneği kurulur. Metafazda kromozomlar ekvator bölgesinde sıralanır. Anafazın ayırt edici olayı kardeş kromatitlerin ayrılıp zıt kutuplara gitmesidir. Telofazda yeni çekirdek düzenleri oluşur. Her çizimde yalnız adı söylemek yerine bir önceki çizime göre neyin değiştiğini belirt.',
      'Anafazda ayrılan kardeşleri homolog kromozom çiftleriyle karıştırma. Mitozda her yavruya eşlenmiş bilginin bir kopyası aktarılır. Kardeşler ayrıldığı anda hücrenin tamamı için yapılan kromozom sayımı geçici değişebilir; bu durum son iki yavrunun her birinin iki kat kromozomla kalacağı anlamına gelmez. Sayımı yaparken hücrenin tamamını mı, bir kutbu mu yoksa oluşan bir yavruyu mu ele aldığını belirt.'
    ], 'Metafazdaki ortak ekvator düzenini ve Anafaz çiziminde zıt kutuplara giden kardeşleri karşılaştır.', 'Anafazda ayrılan iki yapı homolog kromozom mudur?', 'Mitozun anafazında ayrılanlar kardeş kromatitlerdir. Homolog çiftlerin ayrılması mayoz I’in ayırt edici olayıdır.'),
    s('Sitokinez ve Kromozom Sayısı–DNA Miktarı Değişimi', [106], [
      'Sitoplazma Bölünmesi çizimlerinde hayvan hücresindeki dıştan içe boğumlanmayı, bitki hücresindeki hücre plağının içten dışa gelişmesini karşılaştır. Bitki çeperi hayvan hücresindeki gibi boğumlanmaya izin vermediğinden fiziksel ayrılma biçimi farklıdır. Bu fark, kalıtsal bilginin mitozla dağıtılmasının temel sonucunu değiştirmez.',
      'Alt bölümde kromozom sayısı ve DNA miktarı grafiklerini ayrı ayrı oku. DNA eşlenince DNA miktarı artar; kardeşler bağlıyken kromozom sayısı aynı kalabilir. Sitokinez sonrası bir yavru hücreyi ele aldığında DNA miktarı başlangıç düzeyine döner. Grafiğin hangi aşamada bir hücreyi, hangi aşamada bölünmekte olan hücreyi temsil ettiğine dikkat et. İki farklı düşey ekseni tek bir sayı değişimi sanma.'
    ], 'Bitki/hayvan sitokinezini ve Kromozom Sayısı ve DNA Miktarındaki Değişim grafiklerinin ayrı eksenlerini izle.', 'DNA miktarı iki katına çıkmışken kromozom sayısı neden aynı kalabilir?', 'Her kromozom eşlenip iki bağlı kardeş kromatit içerir. DNA kopyası artmıştır, fakat kardeşler ayrılmadan kromozom sayımı aynı kalır.'),
    s('Hücre Döngüsünün Kontrolü', [107,108], [
      'Bölümün sonundaki kontrol açıklamasını, hücre döngüsünün yalnız otomatik bir saat gibi ilerlemediğini görerek oku. Hücre, çoğalma için gerekli koşulları ve hazırlıkların tamamlanmasını denetler. Kalıtsal maddenin uygun biçimde eşlenmesi ve düzenli dağıtılması, bir sonraki aşamaya geçişte önemlidir.',
      'Kitabın kontrol bozukluğu ve kontrolsüz çoğalmayla ilgili açıklamalarını normal bölünmeyle karşılaştır. Bir dokuda bölünme bulunması tek başına hastalık değildir; büyüme ve onarımda normaldir. Sorun düzenleme mekanizmalarının aksamasıyla gereksinimden bağımsız çoğalmanın ortaya çıkabilmesidir. Bu sayfaları evre isimlerinden ayrı bir ek bilgi sayma: kontrol, önceki sayfalarda öğrendiğin süreçlerin doğru sırada ve uygun koşullarda yürütülmesini sağlar.'
    ], 'Hücre Döngüsünün Kontrolü başlığındaki denetim ve kontrolsüz çoğalma açıklamalarını izle.', 'Bir yarada hücre bölünmesinin artması tek başına kontrolsüz çoğalma kanıtı mıdır?', 'Değildir. Onarım gereksinimine uygun düzenlenmiş bölünme normaldir. Kontrolsüz çoğalma, gereksinim ve denetimle ilişkinin bozulmasıyla değerlendirilir.')
  ]);

  add('bio-tyt-07', 'Mayozun Genel Özellikleri ve Evreleri; Eşeyli Üreme', 'TYT-bio', '114–122. sayfalarda tek eşlenme, iki bölünme, sayı grafikleri ve döllenmenin tamamlayıcılığını kitap üzerinden okuyacağız.', [
    s('Mayozun Genel Özellikleri ve İnterfaz', [114], [
      'İlk sayfada mayozun genel sonucunu ve interfazı birlikte oku. DNA bir kez eşlenir, ardından iki bölünme gerçekleşir. Bu düzen, mayozu iki ayrı DNA eşlenmesi yapan bir süreç gibi düşünmeni önler. Diploit başlangıç hücresinden haploit ürünlerin oluşması, homolog kromozom takımlarının paylaşılmasıyla ilişkilidir.',
      'Kromozom sayısı, DNA miktarı ve hücre sayısını ayrı takip et. Başlangıçtaki eşlenme DNA miktarını artırır; takım sayısını kendiliğinden artırmaz. Daha sonra kromozomların nasıl dağıtıldığı takım sayısını etkiler. Genel özellikler içinde verilen çeşitlilik açıklamasını da tek bir nedene indirgeme; sonraki sayfalarda hem parça değişimi hem homologların dağılımı için mekanizma göreceksin.'
    ], 'Mayoz–İnterfaz düzeninde DNA eşlenmesinin yalnız başlangıçta yer aldığını izle.', 'İki bölünme gerçekleşmesi neden DNA’nın iki kez eşlendiği anlamına gelmez?', 'Bölünme ve DNA eşlenmesi ayrı olaylardır. Mayozdan önce bir eşlenme olur; mayoz I ile mayoz II arasında yeniden eşlenme gerçekleşmez.'),
    s('Mayoz I ve Profaz I', [115], [
      'Profaz I çiziminde önce homolog çifti bul. Homolog kromozomların biri anne, diğeri baba kökenlidir; aynı karakterlerle ilgili genleri taşırlar fakat alelleri farklı olabilir. Her homolog eşlenmiş olduğunda iki kardeş kromatit içerir. Yan yana gelen iki homolog böylece dört kromatitli tetrat düzeni oluşturur.',
      'Krossing over çiziminde değişim yapan parçaları izle. Olay homologların kardeş olmayan kromatitleri arasında gösterilir. Bu değişim mevcut alellerin aynı kromozom üzerindeki birlikteliklerini değiştirebilir; mutlaka yeni bir alel üretmesi gerekmez. Kritik Bilgi kutusunu çizimle bağla: kardeş ve homolog kavramlarını doğru ayırmak, değişimin hangi iki yapı arasında gerçekleştiğini açıklamanı sağlar.'
    ], 'Profaz I’de iki homologu, dört kromatidi ve parça değişiminin gerçekleştiği iki kromatidi ayrı ayrı göster.', 'Krossing over neden mutlaka mutasyonla aynı olay değildir?', 'Krossing over mevcut homolog kromatit parçalarının karşılıklı değişimidir ve alellerin kombinasyonunu değiştirebilir. Yeni bir alelin oluşmasını zorunlu kılmaz; mutasyon farklı bir değişim türüdür.'),
    s('Metafaz I, Anafaz I ve Telofaz I', [116], [
      'Metafaz I’de homolog çiftlerin ekvatordaki karşılıklı yerleşimini incele. Her çiftin hangi üyesinin hangi kutba yöneldiği, diğer çiftlerin yönlenmesinden bağımsız olabilir. Böylece farklı anne-baba kökenli kromozom kombinasyonları oluşabilir. Krossing over görülmese bile bu dağılım çeşitlilik sağlayabilir.',
      'Anafaz I’de ayrılan yapılar homolog kromozomlardır. Kardeş kromatitler bu aşamada birlikte kalır. Her yeni kutup homolog çiftin bir üyesini aldığı için takım sayısı azalır. Telofaz I çizimini okurken “kromozom hâlâ iki kromatitli” ile “hücre haploit” bilgilerinin birlikte doğru olabileceğini gör. Haploitlik kromatit sayısına değil, homolog takımların sayısına ilişkindir.'
    ], 'Anafaz I’de birlikte giden iki kardeşi ve zıt kutba giden homologu ayır.', 'Mayoz I sonunda iki kromatitli kromozom taşıyan hücre nasıl haploit olabilir?', 'Hücre her homolog çiftin yalnız bir üyesini almıştır; bu yüzden tek takım taşır. Kromozomun iki kardeş kromatitli olması takım sayısını iki yapmaz.'),
    s('Sitokinez I ve Mayoz II Evreleri', [117,118], [
      'p117’de sitokinez I’den mayoz II’ye geçerken DNA’nın yeniden eşlenmediğini belirt. Profaz II’den sonra kromozomların metafaz II’de tek sıra dizildiği çizime geç. Bu düzen metafaz I’deki homolog çiftlerin karşılıklı dizilişinden farklıdır.',
      'p118’de anafaz II’nin ayırt edici olayı kardeş kromatitlerin ayrılmasıdır. Mayoz I’de homologları, mayoz II’de kardeşleri ayırarak iki bölünmenin görevlerini ayrı söyle. Telofaz II’ye gelindiğinde başlangıçtaki kopyalanmış DNA’nın farklı ürünlere dağıtımı tamamlanır. Çizimlerde farklı renkte parçalar görüyorsan bunları önceki krossing over düzeniyle ilişkilendir. İkinci bölünmede yeni bir parça değişiminin mutlaka gerçekleştiğini varsayma; görülen renk düzeni önceki aşamaların sonucunu taşıyabilir.'
    ], 'Metafaz II’nin tek sıralı düzenini ve Anafaz II’de kardeşlerin ayrılmasını p116 ile karşılaştır.', 'Anafaz I ve anafaz II’nin ayrılan yapılarını nasıl ayırırsın?', 'Anafaz I’de homolog kromozomlar, anafaz II’de kardeş kromatitler ayrılır. Bu ayrım iki bölünmenin takım sayısı ve kopyaların paylaşımı üzerindeki farklı işlevlerini açıklar.'),
    s('Sitokinez II, Kromozom Sayısı ve DNA Miktarı', [119], [
      'p119’da son sitokinez açıklamasını okuduktan sonra sayı grafiklerine geç. Bir kez eşlenme ve iki bölünme bilgilerini grafikteki artış ve azalışlarla eşleştir. DNA miktarı eşlenmede artar; ardışık bölünmelerle bir ürün hücre başına düşen DNA miktarı azalır. Kromozom takımının azalması ise homologların ayrıldığı birinci bölünmeyle ilişkilidir.',
      'Grafikte toplam süreç ile bir hücredeki miktarı karıştırma. Başlangıç hücresi 2n = 12 ise normal son ürünlerin her biri n = 6 taşır; dört ürünün sayısını toplayıp bir ürünün kromozom sayısı gibi söyleyemezsin. Gamet oluşumunda sitoplazmanın her zaman eşit paylaşılması da zorunlu değildir. Grafiklerin gösterdiği çekirdek/kromozom dağılımını hücre büyüklüğüyle özdeşleştirme.'
    ], 'DNA miktarı ve kromozom sayısı grafiklerini ayrı eksenlerden oku; her basamakta tek hücrenin durumunu belirt.', '2n = 12 başlangıçtan oluşan normal mayoz ürünlerinin her biri kaç kromozom taşır?', 'Her biri n = 6 taşır. Mayoz homolog takımlarını ayırarak takım sayısını yarıya indirir; dört ürün oluşması her ürünün altı kromozom taşıdığı bilgisini değiştirmez.'),
    s('Mitoz ve Mayozun Karşılaştırılması', [120], [
      'Karşılaştırma tablosunu sütun sütun ezberlemek yerine her satırda aynı ölçütü iki olay için sor. Bölünme sayısı, oluşan ürün sayısı, kromozom sayısının sonucu ve genetik benzerlik farklı ölçütlerdir. Mitozun koruyucu dağıtımıyla mayozun homolog takımlarını ayırması arasındaki mekanizma bu sonuçları açıklar.',
      'Bir satırı başka satırın nedeni gibi kullanırken dikkatli ol. “Dört hücre oluşur” tek başına çeşitliliğin mekanizması değildir; bağımsız dağılım ve parça değişimi önemlidir. “İki hücre oluşur” da tek başına mitozu tanımlamak için yeterli değildir; mayoz I sonunda da iki hücre bulunabilir. Tabloyu evre çizimlerinden öğrendiğin ayrılan yapılarla birlikte kullan.'
    ], 'Mitoz/Mayoz tablosunda aynı satırı iki sütun boyunca okuyarak karşılaştır.', 'Yalnız iki hücre oluştuğunu görmek neden olayın kesin mitoz olduğunu göstermez?', 'Mayozun birinci bölünmesi sonunda da iki hücre oluşabilir. Hangi yapıların ayrıldığı, DNA eşlenme düzeni ve kromozom takımı gibi ek bilgiler gerekir.'),
    s('Eşeyli Üremenin Genel Özellikleri ve Örnekleri', [121,122], [
      'p121’de eşeyli üreme açıklamasını mayozun sonuna bağla. Haploit gamet çekirdeklerinin birleşmesi diploit durumu yeniden kurar. Böylece mayozun takım azaltmasıyla döllenmenin takım tamamlaması, nesiller boyunca kromozom sayısının korunmasına birlikte katkı verir.',
      'p122’de eşeyli ve eşeysiz üreme karşılaştırmasını okurken hücre bölünmesiyle birey oluşumunu aynı düzeyde değerlendirme. Mitoz çok hücrelide onarım sağlayabilir, tek hücrelide yeni birey oluşturabilir. Eşeyli üremede farklı gametlerin rastgele birleşmesi, mayoz sırasında oluşmuş çeşitliliğe yeni kombinasyonlar ekler. Bir bireyin kalıtsal özelliklerini yalnız anne ya da yalnız baba kopyası gibi yorumlamak bu iki sürecin birleşimini gözden kaçırır.'
    ], 'Eşeyli Üreme açıklamasında gamet–döllenme bağlantısını ve p122 karşılaştırmasını izle.', 'Mayoz takım sayısını azaltıyorsa türün kromozom sayısı nesiller boyunca neden sürekli azalmaz?', 'Döllenmede iki haploit gamet çekirdeği birleşerek diploit durumu yeniden kurar. Mayoz ile döllenmenin tamamlayıcı etkileri takım sayısını yaşam döngüsünde dengeler.')
  ]);

  add('bio-tyt-08', 'Kalıtımla İlgili Kavramlar, Olasılık İlkeleri ve Mendel Çaprazlamaları', 'TYT-bio', '123–131. sayfalarda kavramlardan başlayıp gametler, monohibrit/dihibrit tablolar ve kontrol çaprazlamasına ilerleyeceğiz.', [
    s('Kalıtımla İlgili Kavramlar', [123], [
      'Önce gen, alel, genotip ve fenotip ifadelerini kitabın örnekleri üzerinde ayır. Bir karakterin farklı biçimleriyle, bu biçimlerin ortaya çıkmasında rol alan alelleri aynı sözcük gibi kullanma. Genotip alel birleşimini; fenotip gözlenen veya ölçülen özelliği anlatır. Baskınlık, bir alelin heterozigot durumda nasıl ifade edildiğiyle ilgilidir.',
      'Baskın fenotipin aynı anda iki farklı genotiple görülebileceğini düşün: AA ve Aa. Bu yüzden yalnız dış görünüş, her zaman alellerin ikisini birden belirlemeye yetmez. Homozigot ve heterozigot kavramlarını hücrenin haploit/diploit olmasıyla karıştırma. İlki belirli bir lokustaki alellerin aynı/farklı oluşunu, ikincisi kromozom takımı durumunu anlatır.'
    ], 'Kavram açıklamalarında genotip örneklerini ve aynı fenotipin farklı alel birleşimleriyle oluşmasını izle.', 'Baskın fenotipli bir bireyin kesin AA olduğu söylenebilir mi?', 'Söylenemez. Tam baskınlık modelinde AA ve Aa aynı baskın fenotipi gösterebilir; genotipi ayırmak için ek bilgi gerekir.'),
    s('Olasılık İlkeleri ve Gamet Çeşitlerinin Bulunması', [124,125,126], [
      'Önce olasılık kurallarını oku, sonra gamet örneklerine uygula. Bir gamet her homolog çiftin bir üyesini taşıdığı için belirli bir genin alellerinden birini alır. Aa bireyden A veya a taşıyan gametler oluşabilir. Birden çok gen için gametleri yazarken alelleri aynı lokustan iki kez seçme.',
      '2 üzeri heterozigot gen sayısı biçimindeki kısa yolu, genlerin bağımsız dağıldığı model ve sorunun verdiği koşullarla birlikte kullan. Kitabın örneklerinde her lokustan bir alel seçerek gametleri gerçekten yazmak, formülün neyi saydığını açıklar. Birden fazla bağımsız olayın birlikte gerçekleşmesinde olasılıklar çarpılır; birbirini dışlayan alternatif sonuçların toplamında toplanır. Bir önceki çocuğun sonucu sonraki bağımsız döllenmenin olasılığını değiştirmez.'
    ], 'Olasılık kurallarını izledikten sonra gamet çeşitleri örneklerinde her gamette her lokustan bir alel bulunduğunu denetle.', 'AaBb için bağımsız dağılım modelinde neden dört gamet türü yazılır?', 'A/a seçenekleri B/b seçenekleriyle birleşir: AB, Ab, aB, ab. Her lokustan bir alel seçilir; iki bağımsız ikili seçimin çarpımı dört kombinasyondur.'),
    s('Mendel’in Çalışmaları ve Monohibrit Çaprazlama', [127], [
      'Mendel’in bezelye karakterlerini gösteren tabloyu incele. Karakter ile karakterin farklı özelliklerini ayır; örneğin bir satırın karakteri ile baskın/çekinik görünümleri aynı düzeyde adlandırılmaz. Deneyde izlenen karakteri net belirlemek, daha sonra yazılan harflerin neyi temsil ettiğini anlamanı sağlar.',
      'Monohibrit çaprazlamada önce ebeveyn genotiplerini, sonra oluşturabilecekleri gametleri yaz. Bir yavrunun genotipi iki ebeveynden gelen birer alelin birleşmesiyle oluşur. Doğrudan oran ezberine geçersen farklı ebeveynler verildiğinde aynı oranı yanlış kullanabilirsin. Tabloyu doldurmadan önce her gametin neden o aleli taşıyabildiğini açıkla; Mendel’in gözlediği oranların hücresel temelini alellerin ayrılması oluşturur.'
    ], 'Bezelye karakter tablosunda karakter/özellik ayrımına; monohibritte ebeveyn → gamet → yavru sırasına bak.', 'AA × aa çaprazında yavruların hepsinin Aa olmasını nasıl açıklarsın?', 'AA ebeveyni yalnız A, aa ebeveyni yalnız a aleli taşıyan gamet verir. Her döllenmede A ile a birleşir; bu yüzden yavruların genotipi Aa olur.'),
    s('Monohibrit F2: Genotip Oranı 1:2:1, Fenotip Oranı 3:1', [128], [
      'Sayfadaki kendileştirme düzeninde Aa bireylerin A ve a gametlerini karşılaştır. Dört eş olasılıklı birleşme AA, Aa, aA ve aa olarak görünür. Ortadaki iki yazım aynı heterozigot genotipi temsil eder. Böylece genotip sayımı 1 AA : 2 Aa : 1 aa olur.',
      'Tam baskınlık modelinde AA ile Aa aynı fenotipte toplandığı için fenotip oranı 3:1’e dönüşür. Genotip ile fenotip sayımlarının farklılaşma nedenini tabloda göster. Bu oranlar çok sayıdaki bağımsız döllenme için beklenen olasılıklardır; dört yavrulu her ailede zorunlu olarak üç baskın ve bir çekinik olacağını söylemez. Örneklem küçüldükçe gözlenen sayılar beklenen orandan sapabilir.'
    ], 'Genotip Oranı 1:2:1 ve Fenotip Oranı 3:1 ifadelerine karşılık gelen dört birleşmeyi tek tek say.', 'Dört yavrunun tamamı baskın fenotipliyse Aa × Aa modeli kesin dışlanır mı?', 'Dışlanmaz. Her yavrunun baskın fenotip olasılığı 3/4’tür; bağımsız dört yavrunun hepsinin baskın olması mümkündür. Beklenen oran kesin aile kotası değildir.'),
    s('Dihibrit Çaprazlama ve Mendel İlkeleri', [129,130], [
      'p129’da iki karakteri birlikte izleyen çaprazlamaya geç. Ebeveynin dört gametini tablonun kenarına yazarken her gametin iki lokustan birer alel taşıdığını denetle. İçteki her kutu bir yumurta ile bir spermin birleşmesini temsil eder. Aynı fenotipe ait birden fazla genotip bulunabilir.',
      'p130’daki F2 sonuçlarını fenotip sınıflarına ayır. Bağımsız dağılım ve tam baskınlığın varsayıldığı modelde 9:3:3:1 sonucu, iki ayrı 3:1 dağılımın birleşmesiyle açıklanabilir. Bu oranı bütün iki gen sorularında otomatik kullanma; bağlı gen, farklı baskınlık ilişkisi veya farklı ebeveyn genotipleri sonucu değiştirebilir. Mendel İlkeleri başlığını, tablodaki gametlerin oluşumuna geri bağlayarak oku.'
    ], 'Dişi ve erkek gamet başlıklarını; p130’da F2 genotip/fenotip gruplarını ve Mendel İlkeleri açıklamasını izle.', 'Dihibrit tabloda 16 kutu olması neden 16 farklı fenotip olacağı anlamına gelmez?', 'Farklı alel birleşimleri aynı fenotipi oluşturabilir. Kutular gamet birleşmelerini gösterir; fenotipler baskınlık ilişkisine göre bu kutuların gruplandırılmasıyla sayılır.'),
    s('Kontrol Çaprazlaması (Test Çaprazlaması)', [131], [
      'Kontrol çaprazlamasında bilinmeyen baskın fenotipli bireyin, ilgili karakter için homozigot çekinik bireyle çaprazlandığını oku. Çekinik ebeveyn tek tür alel verdiği için yavru genotipleri diğer ebeveynin gametleri hakkında bilgi taşır. Amaç baskın görünümün AA mı Aa mı olduğunu ayırt etmektir.',
      'Sayfadaki soruda birden çok lokus varsa aynı mantığı her lokusta uygula. Çekinik fenotipli bir yavrunun oluşması, baskın fenotipli ebeveynin çekinik aleli taşıdığını gösterir. Buna karşılık az sayıda yavrunun hepsinin baskın görülmesi, heterozigotluğu her zaman kesin dışlamaz; olasılık ile kesin kanıtın gücünü ayır. Çözümü ebeveyn → gamet → yavru sırasıyla kurduğunda test çaprazlaması ayrı bir ezber olmaktan çıkar.'
    ], 'Kontrol Çaprazlaması başlığındaki bilinmeyen ebeveyn ve çekinik eşin gametlerini; ardından verilen soruyu incele.', 'Baskın fenotipli ebeveynden çekinik fenotipli yavru oluşması hangi bilgiyi verir?', 'Yavru çekinik aleli iki ebeveynden de almıştır. Baskın fenotipli ebeveynin de çekinik aleli taşıdığı, dolayısıyla bu lokusta heterozigot olduğu anlaşılır.')
  ]);

  add('bio-tyt-09', 'Canlıların Sınıflandırılması, Canlı Âlemleri ve Virüsler', 'TYT-bio', '73–100. sayfaları sınıflandırma ölçütlerinden âlemlere ve virüslere kadar kitabın sırasıyla okuyacağız.', [
    s('Sınıflandırmanın Amacı; Yapay ve Doğal Sınıflandırma', [73,74], [
      'p73’te sınıflandırmanın bilgiyi düzenleme ve canlılar arasındaki ilişkileri anlama amacını oku. Ardından p74’te yapay ve doğal sınıflandırmayı karşılaştır. Dış görünüş veya aynı görevi yerine getirme, tek başına yakın akrabalık kanıtı değildir. Doğal sınıflandırmada köken ve kalıtsal benzerlikler önem taşır.',
      'Homolog ve analog yapıları, benzerliğin hangi ölçüte dayandığını sorarak ayır. Homologluk ortak kökenle, analogluk benzer görevle ilişkilidir. Bir yapının uçmaya yaraması o yapının başka uçma organıyla aynı kökenden geldiğini zorunlu kılmaz. Kitabın karşılaştırma örneklerinde “ne işe yarar?” ve “hangi kökenden gelişmiştir?” sorularına ayrı yanıt ver.'
    ], 'p73’te ölçüt/yaklaşım şemasını, p74’te Yapay ve Doğal Sınıflandırma başlıklarını karşılaştır.', 'İki canlının uçabilmesi neden tek başına yakın akrabalık göstermez?', 'Uçma benzer bir görevdir. Bu işlev farklı kökenden gelen yapılarda da ortaya çıkabilir; akrabalık için köken ve kalıtsal benzerlik gibi veriler gerekir.'),
    s('Kategoriler Arasındaki Hiyerarşi ve İkili Adlandırma', [75,76], [
      'p75’te kategorileri türden âleme doğru izle. Üst kategorilere çıkıldıkça kapsanan canlı grubu genişler; ortak ayrıntılı özellikler genellikle azalır. Aynı türe ait bireyler daha dar ve ortak özellikleri daha fazla olan bir grupta bulunur. Hiyerarşiyi birbirinden bağımsız kutular gibi değil, iç içe kümeler olarak düşün.',
      'p76’da bilimsel isim örneklerini iki parçaya ayır. İlk sözcük cins adıdır; ikinci sözcük tanımlayıcı addır. Türün bilimsel adı ikisi birlikte kullanılarak belirtilir. Yalnız ikinci sözcüğü ortak olan iki canlının aynı cins veya tür olduğunu söyleyemezsin. Aynı cinsteki farklı türler ortak üst kategorilerde de yer alır; üst kategoride ortaklık ise mutlaka aynı tür olmayı gerektirmez.'
    ], 'p75’te Tür–Cins–Aile–Takım–Sınıf–Şube–Âlem sırasını, p76’da iki sözcüklü adları izle.', 'Aynı ailede bulunan iki canlının aynı cinste olması zorunlu mudur?', 'Değildir. Aile birden çok cinsi kapsayabilir. Daha geniş bir kategoride ortaklık, daha dar kategorilerin mutlaka aynı olduğu anlamına gelmez.'),
    s('Bakteriler Âlemi ve Arkeler Âlemi', [77,78,79,80,81], [
      'Bakteri ve arke başlıklarını hücresel düzen açısından oku. İki grup da prokaryottur; kalıtsal madde zarla çevrili çekirdekte bulunmaz. Ancak bu ortaklık onları aynı grup yapmaz. Kitabın yapı ve metabolizma özelliklerini ayrı karşılaştır; hücre duvarı, zar ve yaşama koşullarıyla ilgili farklılıklar sınıflandırmada anlam taşır.',
      'Örnekleri yalnız “yararlı/zararlı” diye ayırma. Bakteriler ve arkeler çok farklı enerji elde etme ve beslenme yolları kullanabilir. Arke örneklerinin bazıları uç koşullarda verilse de bütün arkelerin yalnız böyle ortamlarda bulunması gerektiği sonucuna gitme. Canlı grubunun tanımını tek bir dikkat çekici örneğe indirmek yerine bölümdeki ortak yapı özelliklerini esas al.'
    ], 'Bakteri ve arke sayfalarında çekirdek düzeni, hücre duvarı ve metabolizma örneklerini ayrı sütunlarda karşılaştır.', 'Bakteri ve arkelerin ikisinin de prokaryot olması neden aynı âlem olduklarını göstermez?', 'Prokaryotluk hücresel düzenin bir ortak özelliğidir. Zar, hücre duvarı ve moleküler özellikler gibi başka ölçütler iki grubun farklılığını ortaya koyar.'),
    s('Protista, Bitkiler ve Mantarlar Âlemleri', [82,83,84,85,86,87,88,89], [
      'Protista bölümünde verilen örneklerin ökaryot olduğunu, buna karşılık hücre sayısı ve beslenme açısından çeşitlilik gösterebildiğini izle. Tek hücreli olmak prokaryotluk anlamına gelmez. Örnek canlıyı tanırken çekirdeğin düzenini, hareket biçimini ve beslenmesini ayrı özellikler olarak kullan.',
      'Bitkiler bölümünden mantarlara geçtiğinde fotosentez, hücre duvarı ve depo maddesi gibi ölçütleri karşılaştır. Mantarların bitkiler gibi görünmesi veya yer değiştirmemesi onları bitki yapmaz. Mantarlar heterotrof beslenir; organik maddeyi dışarıdan sağlar. Her grupta kitabın verdiği örnekleri tanımlayıcı özelliklere bağla. Bir örneğin tek bir ortak özelliğinden bütün gruplandırmayı çıkarmak yerine birden çok ölçütü birlikte kullan.'
    ], 'Protist örneklerinden sonra Bitkiler ve Mantarlar başlıklarında beslenme ve hücre duvarı açıklamalarını karşılaştır.', 'Mantarın yer değiştirmemesi neden bitki olduğunu kanıtlamaz?', 'Yer değiştirme sınıflandırma için tek başına yeterli değildir. Mantarların beslenmesi ve hücre duvarı gibi temel özellikleri bitkilerden farklıdır; kalıtsal yakınlık da dikkate alınır.'),
    s('Hayvanlar Âlemi: Omurgasızlar ve Omurgalılar', [90,91,92,93,94,95,96,97], [
      'Hayvanlar bölümündeki grupları, önce omurganın bulunması ölçütüyle ayır. Omurgasız örneklerin tümünü tek tip basit canlı gibi düşünme; farklı vücut düzenleri ve organ sistemleri bulunur. Kitabın grup başlıklarında verilen ayırt edici özellikleri o grubun örnekleriyle eşleştir.',
      'Omurgalılar sayfalarında grupları solunum, dolaşım, vücut örtüsü, üreme ve gelişme gibi aynı ölçütlerle karşılaştır. Bir hayvanın suda yaşaması balık olduğunu kesinleştirmez; yaşam alanı ile sınıflandırma özellikleri farklıdır. Tablo veya örneklerde ölçüt değiştirirken bunu açıkça belirt. Bir gruba ait birçok özelliği birlikte değerlendirmek, yalnız görünüşe dayanan yapay sınıflandırmadan uzaklaşmanı sağlar.'
    ], 'Omurgasız ve Omurgalı başlıklarında aynı ölçütleri izleyerek grupları karşılaştır; örneğin solunum biçimini grup adıyla eşleştir.', 'Suda yaşayan bir memeliyi yalnız yaşam alanına göre balık saymak neden yanlıştır?', 'Yaşam alanı tek başına akrabalığı belirlemez. Solunum, üreme, vücut örtüsü ve diğer kalıtsal özellikler memeli grubuyla ilişkisini gösterir.'),
    s('Virüslerin Genel Özellikleri ve Çoğalması', [98,99,100], [
      'Virüsler bölümüne geçerken önceki hücresel canlı âlemlerinden farklı bir yapı incelendiğini fark et. Virüslerin kalıtsal madde ve protein örtüyle ilişkili yapısını oku. Hücresel düzeneğin bulunmaması, kendi başına protein sentezi ve metabolik süreçleri hücre gibi yürütememeleriyle ilişkilidir.',
      'Çoğalma şemasında konak hücreye girişten yeni virüslerin oluşmasına kadar sırayı izle. Konak kaynaklarının kullanılması, virüsün bölünerek iki hücre oluşturduğu anlamına gelmez. Farklı virüslerde kalıtsal madde türü ve çoğalma ayrıntıları değişebilir; tek bir örneği bütün virüslere aynı biçimde uygulama. Virüsü bakteriden ayırırken yalnız küçük boyuta değil, hücresel yapı ve çoğalma bağımlılığına bak.'
    ], 'p98’de genel yapı/çoğalma açıklamasını ve devam sayfalarındaki konak hücreyle ilişkiyi izle.', 'Virüsün çoğalması neden bakterinin hücre bölünmesiyle aynı süreç değildir?', 'Virüs konak hücrenin sentez olanaklarını kullanarak bileşenlerini çoğaltıp yeni parçacıklar oluşturur. Bakteri ise kendi hücresel düzeniyle büyüyüp bölünen bir hücredir.')
  ]);

  add('bio-tyt-10', 'Ekosistem Ekolojisi', 'TYT-bio', '145–158. sayfalarda ekolojik düzeyler, beslenme, besin ağları ve su-karbon-azot döngülerini izleyeceğiz.', [
    s('Ekolojik Kavramlar', [145,146], [
      'İlk sayfalarda birey, popülasyon, komünite ve ekosistem kavramlarını kapsadıkları bileşenlerle ayır. Popülasyon aynı tür bireyleri, komünite aynı alandaki farklı türlerin topluluklarını içerir. Ekosistem ise canlı topluluğuyla birlikte cansız çevreyi ve aralarındaki ilişkileri de kapsar.',
      'Kitabın habitat ve ekolojik niş açıklamalarında yer ile rol farkını kur. Habitat canlının yaşadığı ortamı, niş kaynakları kullanması ve çevresiyle ilişkilerini içeren işlevsel konumunu anlatır. Aynı alanda yaşayan türler mutlaka tamamen aynı nişi paylaşmaz. Örnekleri okurken “nerede?” ve “hangi kaynakları nasıl kullanıyor?” sorularını ayrı yanıtla. Böylece sonraki beslenme ve rekabet ilişkilerinin hangi düzeyde incelendiğini belirlersin.'
    ], 'Ekolojik Kavramlar başlığındaki düzeyleri; habitat ve niş açıklamalarını yan yana karşılaştır.', 'Bir göldeki balıkların tamamı her zaman tek popülasyon mudur?', 'Hayır. Farklı balık türleri bulunabilir. Popülasyon aynı tür bireyleri kapsar; bütün balık türleri birlikte daha geniş bir canlı topluluğunun parçalarıdır.'),
    s('Ekosistemin Canlı ve Cansız Bileşenleri', [147,148], [
      'p147’deki dallanma şemasında biyotik ve abiyotik faktörleri ayır. Işık, sıcaklık ve iklim gibi koşullar canlıların dağılımını ve etkinliğini etkiler. Canlı bileşenler ise beslenme ve diğer ilişkilerle birbirine bağlanır. “Cansız” sözcüğü bu faktörlerin etkisiz olduğu anlamına gelmez.',
      'Devam açıklamalarında bir faktörün etkisini diğerlerinden tamamen bağımsız düşünme. Örneğin ışık, su ve sıcaklık üreticilerin etkinliğini birlikte sınırlayabilir. Bir türün bulunması yalnız bir koşulun uygunluğuna bağlı olmayabilir. Şemayı liste olarak ezberlemek yerine seçtiğin bir canlının hem cansız koşullarla hem diğer canlılarla ilişkisini kur. Ekosistem kavramının komüniteden daha geniş olmasını bu ortak ilişkiler açıklar.'
    ], 'Ekosistemin Bileşenleri ağacında Canlı/Biyotik ve Cansız/Abiyotik dallarını takip et.', 'Bir ormandaki bütün canlıları saymak ekosistemi tamamen tanımlamak için yeterli midir?', 'Yeterli değildir. Toprak, su, ışık ve sıcaklık gibi cansız bileşenler ile canlı-cansız ilişkileri de ekosistemin parçasıdır.'),
    s('Canlılardaki Beslenme Şekilleri', [149,150,151], [
      'Ototroflar başlığından başlayarak organik maddenin kaynağını izle. Üreticiler inorganik maddelerden organik besin sentezleyebilir; heterotroflar organik besini başka kaynaklardan sağlar. Fotosentez ile kemosentez örneklerini, kullanılan enerji kaynağı bakımından ayır.',
      'Tüketici ve ayrıştırıcı örneklerinde alınan organik maddenin nasıl kullanıldığını incele. Ayrıştırıcılar yalnız besin zincirinin en sonunda bir kere çalışan canlılar değildir; farklı trofik düzeylerden gelen organik kalıntıları işleyebilirler. Organik maddelerin inorganik biçimlere dönüşmesi, maddelerin üreticiler tarafından yeniden kullanılmasına katkı verir. Beslenme grubunu belirlerken canlının dış görünüşü yerine organik maddeyi üretme veya alma yolunu esas al.'
    ], 'Ototroflar açıklamasından sonraki tüketici ve ayrıştırıcı örneklerini madde kaynağına göre karşılaştır.', 'Ayrıştırıcılar neden yalnız son tüketicinin kalıntılarından yararlanmak zorunda değildir?', 'Üretici ve farklı tüketici düzeylerinden gelen ölü dokular ve atıklar organik madde sağlayabilir. Ayrıştırma besin ağının birçok noktasından gelen maddeleri işler.'),
    s('Besin Zinciri, Besin Ağı ve Besin Piramidi', [152,153], [
      'p152’de besin zincirindeki okların hangi yönde çizildiğini kontrol et: oklar besinden beslenen canlıya doğru madde ve enerji aktarımını gösterir. Üreticiyi birinci basamağa yerleştir; tüketici sırasını, canlıya ulaşan beslenme yoluna göre belirle. Ayrıştırıcıların farklı basamaklarla bağlantısını ayrıca izle.',
      'p153’te besin ağına geçtiğinde bir canlının birden çok bağlantısı olabileceğini gör. Aynı canlı farklı yollar üzerinden farklı trofik konumlarda yer alabilir. Besin piramidinde ise düşey eksenin neyi gösterdiğine bak: enerji, biyokütle ve birey sayısı aynı büyüklükler değildir. Bir piramit için öğrendiğin şekli ekseni değiştirerek otomatik uygulama; önce hangi niceliğin karşılaştırıldığını söyle.'
    ], 'Zincir oklarını; p153’te aynı canlıya bağlanan farklı okları ve piramidin gösterdiği niceliği izle.', 'Besin ağında bir türün tek bir tüketici basamağına zorunlu olarak yerleştirilememesi nasıl mümkün olur?', 'Farklı trofik düzeylerdeki canlılarla beslenebilir. Üreticiyi yiyen bir yol ile başka tüketiciyi yiyen bir yol, aynı türü farklı beslenme konumlarına yerleştirebilir.'),
    s('Madde ve Enerji Akışı; Biyolojik Birikim', [154,155], [
      'p154’te enerji aktarımını gösteren açıklamalarda her basamaktaki enerjinin tamamının bir üst basamağa geçmediğini gör. Canlıların metabolik etkinlikleri ve ısı kaybı, aktarılabilir enerjiyi sınırlar. Bu nedenle üst düzeylere çıkıldıkça kullanılabilir enerji azalır; enerji aynı biçimde üreticilere dönüp kapalı bir döngü oluşturmaz.',
      'p155’te biyolojik birikim açıklamasını enerji azalmasıyla karıştırma. Kolay parçalanmayan bazı maddelerin canlılarda ve beslenme ilişkileri boyunca yoğunlaşması farklı bir süreçtir. Üst tüketicinin az enerji alması, her kimyasal maddenin de daha düşük derişimde bulunmasını gerektirmez. Hangi niceliğin izlendiğini her örnekte belirt: enerji miktarı mı, canlı dokusundaki kirletici derişimi mi?' 
    ], 'p154’te enerji aktarımını, p155’te Biyolojik Birikim açıklamasını aynı nicelikmiş gibi okumadan karşılaştır.', 'Üst tüketicilere enerji azalırken bazı kirleticilerin derişimi neden artabilir?', 'Enerji metabolizmada kullanılıp ısı olarak dağılır. Kalıcı kirleticiler ise kolay uzaklaştırılmayıp dokularda birikebilir ve beslenme yoluyla yoğunlaşabilir; iki niceliğin davranışı farklıdır.'),
    s('Madde Döngüleri: Su, Karbon ve Azot', [156,157,158], [
      'p156’da su döngüsünü izlerken depolar ile süreçleri ayır: suyun bulunduğu yer başka, buharlaşma veya yağış gibi yer değiştirmesi başka bilgidir. p157’de karbon döngüsünde fotosentezin karbonu organik yapılara katmasını; solunum ve ayrışmanın karbonun çevreye dönmesine katkısını takip et.',
      'p158’de azot döngüsü daha çok kimyasal dönüşüm içerir. Atmosferde bol azot bulunması, bütün canlıların bunu doğrudan kullanabildiği anlamına gelmez. Şemadaki farklı azotlu biçimleri ve mikroorganizma basamaklarını ok yönüyle birlikte incele. Üreticilerin aldığı madde biçimini tüketicilerin organik besinle aldığı azotla ayır. Üç döngüde de madde yeniden kullanılabilir; enerjinin aktarım sırasında ısıya dönüşmesiyle oluşan tek yönlü akış farklı bir düzendir.'
    ], 'Su, Karbon ve Azot döngülerinde her okun başlangıcını, bitişini ve süreç adını tek tek söyle.', 'Azot döngüsünde mikroorganizmaların bulunması neden önemlidir?', 'Farklı azotlu madde biçimleri arasında dönüşüm yaparlar. Böylece canlıların kullanabildiği azot biçimleri oluşur ve azotun çevreye geri dönmesi sağlanır.')
  ]);

  add('bio-ayt-01', 'Sinir Sistemi', 'AYT-bio', '9–22. sayfalarda nörondan impuls ve sinapsa, ardından merkezî/çevresel sinir sistemine kitap sırasıyla ilerleyeceğiz.', [
    s('Sinir Doku — Nöronlar ve yardımcı hücreler', [9,10], [
      'p9’daki nöron çiziminde hücre gövdesi, dendrit ve aksonu bul. Dendritlerin bilgi alması, aksonun iletime katılması ve akson ucunun başka hücrelerle bağlantısı, yapının işlevle ilişkisini gösterir. Nöronları görevlerine göre ayırırken duyu, ara ve motor nöronun bilgi yolundaki yerini düşün.',
      'Devam sayfasındaki yardımcı hücreleri nöronlarla aynı görevde sayma. Destek, koruma ve miyelin oluşumuyla ilgili işlevler sinir dokunun birlikte çalışmasını sağlar. Miyelin kılıfın akson çevresindeki yerini çizimde gör; kılıfla akson zarını özdeşleştirme. Her nöronun aynı sayıda uzantı ve aynı iletim hızına sahip olması gerekmez.'
    ], 'Nöronun gövde–dendrit–akson düzenini ve miyelin/Ranvier boğumu etiketlerini izle.', 'Miyelin bulunması nöronun aksonunun artık hücre zarı taşımadığı anlamına gelir mi?', 'Hayır. Miyelin akson çevresindeki ek yalıtım düzenidir. Aksonun kendi hücre zarı ve bu zardaki iyon hareketleri iletimin temelini oluşturmaya devam eder.'),
    s('Sodyum-Potasyum Pompasının Çalışma Mekanizması', [11], [
      'Sayfadaki dört basamaklı pompa açıklamasını çizimle birlikte oku. Na+ ve K+ iyonlarının hücre içi/dışı derişimleri farklıdır. ATP kullanılması pompa proteininin biçim değiştirerek iyonları taşımasını sağlar. Bu çalışma, hücrenin derişim farklarını sürdürmesine katkı verir.',
      'Pompanın çalışmasını, bir sonraki sayfada kanallardan hızlı iyon geçişiyle oluşan aksiyon potansiyeliyle aynı olay sayma. Dinlenme durumundaki nöron da metabolik olarak etkindir ve gradyanlarını korur. Dışarıda daha çok sodyum, içeride daha çok potasyum bulunmasını hücrenin her noktasının aynı elektrik yükünü taşıdığı şeklinde okumadan, zarın iki yanı arasındaki yük ayrımıyla ilişkilendir.'
    ], 'Numaralı basamaklarda ATP kullanımını ve Na+/K+ iyonlarının taşındığı tarafları takip et.', 'Dinlenme durumundaki nöron neden ATP kullanmaya devam eder?', 'İyon derişim farklarının korunması gibi işler sürer. Dinlenme impuls iletiminin o anda olmamasını belirtir; metabolizmanın veya aktif taşımanın tamamen durmasını anlatmaz.'),
    s('Nöronlarda İmpuls Oluşumu ve İletimi', [12], [
      'Zar potansiyelinin değişimini gösteren sırayı, iyon kanallarının açılması ve kapanmasıyla birlikte oku. Uygun uyarı eşiğe ulaştığında depolarizasyon, ardından repolarizasyon gerçekleşir. İyon geçişlerinin yönünü çizimdeki hücre içi ve dışına göre söyle; yalnız artı/eksi işaretlerini ezberleme.',
      'Eşik üstü uyarılar için aksiyon potansiyelinin büyüklüğüyle impuls sıklığını ayır. Daha şiddetli uyarı aynı aksonda her impulsun daha büyük genlikli olması demek değildir; bilgi impuls sayısı/sıklığı ve etkinleşen yollarla kodlanabilir. Miyelin ve akson çapı gibi yapısal özellikler ise iletim hızını etkiler. Uyarı şiddeti, impuls genliği ve hız farklı büyüklüklerdir.'
    ], 'İyon hareketlerini ve potansiyel değişimindeki yükselme–düşme sırasını aynı anda izle.', 'Eşik üstü uyarıyı artırmak aynı aksondaki her impulsu mutlaka daha büyük yapar mı?', 'Hayır. Aksiyon potansiyeli oluştuğunda genliği belirli özellikler taşır. Şiddetin kodlanması daha sık impuls gibi değişimlerle ilişkili olabilir; genlik ve sıklık karıştırılmaz.'),
    s('Sinapslarda İmpuls Oluşumu ve İletimi; Atlamalı İletim', [13], [
      'Sinaps çiziminde presinaptik akson ucunu, sinaptik kesecikleri, boşluğu ve postsinaptik nöronun dendritini sırayla bul. Elektriksel değişimin akson ucuna ulaşması kimyasal ileticinin salınmasına bağlanır. Nörotransmitterin reseptörle etkileşmesi sonraki hücrenin yanıtını etkiler; ilk hücrenin zarı boşluğu aşarak ikinci hücreye dönüşmez.',
      'Aynı sayfadaki atlamalı iletim çiziminde Ranvier boğumlarını izle. İmpulsun boğumlar arasında hızla ilerlemesini anlatan model, akson boyunca hücresel sürekliliğin kaybolduğu anlamına gelmez. Sinapsta kimyasal aktarım ile miyelinli aksondaki iletim iki farklı konum ve mekanizmadır. Bir çizimin okunu diğerine taşımadan önce hangi yapıda olduğunu söyle.'
    ], 'Sinaptik kesecik → boşluk → reseptör sırasını; ardından miyelin/Ranvier boğumu çizimini takip et.', 'Nörotransmitterin bulunması neden postsinaptik hücrede mutlaka yeni impuls oluşacağını göstermez?', 'Yanıt reseptöre, ileticinin etkisine ve diğer uyarılarla birlikte zar potansiyelinin eşiğe ulaşıp ulaşmamasına bağlıdır. Sinaptik etki uyarıcı veya baskılayıcı olabilir.'),
    s('Sinir Sisteminin Bölümleri ve Ön Beyin', [14,15,16], [
      'Bölüm şemasında merkezî ve çevresel sinir sistemi ayrımını yap. Ardından ön beyin yapılarının yerini ve görevlerini oku. Beyin kabuğunun duyusal bilgilerin değerlendirilmesi ve istemli hareketlerle ilişkisi, farklı bölgelerin iş bölümüne dayanır; beynin bütün bölgelerinin her işi aynı biçimde yaptığı anlamına gelmez.',
      'Talamus ve hipotalamus açıklamalarını görev adlarıyla karıştırma. Duyu aktarımı, iç denge, sıcaklık ve hormonal bağlantılar farklı düzenleme rolleridir. Çizimde yakın görünen iki bölge aynı işleve sahip olmak zorunda değildir. Her yapı için kitaptaki bir görevi, o görevin günlük bir örneğiyle bağla; örneğin iç ortam düzenlenmesini yalnız düşünme veya bilinçli karar verme olarak açıklama.'
    ], 'Merkezî/Çevresel ayrımını yaptıktan sonra ön beyin çizimindeki yapı adlarını görev açıklamalarıyla eşleştir.', 'Hipotalamusun hormon düzenlenmesiyle ilişkili olması sinir ve endokrin sistemlerin tamamen bağımsız olmadığını nasıl gösterir?', 'Hipotalamus sinirsel bilgilerle iç ortamı değerlendirip hormonal yanıtların düzenlenmesine katılır. Böylece iki sistem arasında işlevsel bağlantı kurulur.'),
    s('Orta Beyin, Arka Beyin ve Omurilik', [17,18], [
      'p17’de orta beyin ve arka beyin yapılarını ayrı başlıklardan oku. Pons, omurilik soğanı ve beyincik aynı yapı değildir; farklı hareket ve yaşamsal düzenleme görevleriyle ilişkilidir. Beyinciğin denge ve hareketlerin koordinasyonundaki rolünü, kasların bütün kasılmalarını tek başına başlatması gibi yorumlama.',
      'p18’de omurilik çiziminden refleks yoluna geç. Duyu nöronu, ara nöron ve motor nöronun sıradaki yerini izle. Refleks yanıtın omurilik düzeyinde düzenlenebilmesi, bilginin beyne hiç ulaşmadığını göstermez. İlk yanıtın hızlı düzenlenmesi ile olayın bilinçli algılanması farklı zamanlarda gerçekleşebilir. p17’deki beyin açıklaması yerine refleks için gerçek kaynak olan p18’deki yolu kullan.'
    ], 'p18’de omuriliğe giren duyu yolunu ve çıkan motor yolu çizimde takip et.', 'Elin sıcak yüzeyden hızla çekilmesi, sıcaklığın daha sonra bilinçli algılanmasıyla çelişir mi?', 'Çelişmez. Hızlı refleks yanıt omurilik düzeyinde düzenlenebilirken bilgi üst merkezlere de iletilir; bilinçli algı ile ilk motor yanıt aynı basamak değildir.'),
    s('Çevresel Sinir Sistemi ve Sinir Sistemi Rahatsızlıkları', [19,20,21,22], [
      'Çevresel sinir sistemi bölümünde merkezle organlar arasındaki bağlantıyı izle. Somatik ve otonom ayrımında denetlenen yapıları ve düzenlenme biçimini karşılaştır. Otonom sistemin sempatik ve parasempatik etkileri birçok organda farklı yönlerde düzenleme sağlar; bunları her organda basitçe “biri çalıştırır, diğeri durdurur” kalıbına sıkıştırma.',
      'Rahatsızlıklar ve sağlıklı yapının korunması sayfalarını okurken bir belirtiyle tek başına kesin tanı koymaya çalışma. Kitabın amacı sinir dokudaki aksamanın hareket, duyum veya diğer işlevleri nasıl etkileyebildiğini göstermektir. Hastalık örneklerini önce öğrendiğin yapı ve süreçlerle ilişkilendir; böylece isim listesi, işlevin bozulması üzerinden anlaşılır.'
    ], 'Somatik/otonom ayrımını ve sempatik–parasempatik karşılaştırmasını, sonra sağlığı koruma bölümünü oku.', 'Sempatik etkinliğin bütün organlarda aynı sonucu doğurduğu söylenebilir mi?', 'Söylenemez. Etki organın reseptörlerine ve işlevine bağlıdır. Sistem düzeyindeki yanıt farklı organlarda farklı düzenlemelerin birleşimiyle oluşur.')
  ]);

  add('bio-ayt-02', 'Endokrin Sistem', 'AYT-bio', '23–31. sayfalarda bezler, hormonların hedefleri ve kitaptaki geri bildirim örneklerini başlık sırasıyla okuyacağız.', [
    s('Salgı Bezleri ve Hormonların Genel Özellikleri', [23], [
      'Salgı bezleri açıklamasında salgının nereye verildiğini izle. Endokrin bezlerin hormonları kana vermesi ile dış salgı bezlerinin kanalla belirli yüzey veya boşluklara salgı vermesi farklı düzenlerdir. Karma bez örneğinde aynı organın farklı salgıları farklı yollardan verilebilir.',
      'Hormonların Genel Özellikleri ve Etkileri başlığında hedef hücre kavramını kullan. Kan bir hormonu birçok yere taşıyabilir fakat uygun reseptör taşımayan her hücre aynı yanıtı vermez. Sayfadaki endokrin bezler haritasını görev haritasıyla karıştırma; hormonun üretildiği yerle etkili olduğu yer farklı olabilir. Etkiyi açıklarken bez → hormon → hedef → yanıt sırasını kur.'
    ], 'Bez türlerini salgı yolu açısından karşılaştır; vücut haritasında bezin yeri ile hedefini ayır.', 'Bir hormonun kanda bulunması neden bütün hücreleri aynı biçimde etkilemez?', 'Yanıt uygun reseptör ve hücresel mekanizmalara bağlıdır. Hormonun hücreye ulaşması ile hedef hücrenin onu algılayıp yanıt vermesi ayrı koşullardır.'),
    s('Epifiz Bezi, Hipofiz Bezi ve Hormonları', [24,25], [
      'p24’te epifizden sonra hipofiz başlığına geç. Ön lob hormonlarını görevleriyle birlikte oku; büyüme hormonu ile başka endokrin bezleri uyaran hormonlar aynı hedefe etki etmez. p25’te FSH, LH, prolaktin, TSH ve ACTH gibi adları hedef organla eşleştirerek takip et.',
      'Arka lob bölümünde ADH ve oksitosin için sentez, depolama ve salınma ayrımını yap. Hipotalamusta üretilip hipofizin arka lobundan kana verilen hormonları, ön lobun kendi hücrelerinde sentezlenen hormonlarla özdeşleştirme. Bir hormonun “hipofizden salgılanması”, sentezinin mutlaka aynı hücrelerde yapıldığını tek başına söylemez. Bu ayrım ADH’nin böbrek üzerindeki etkisini öğrenirken de kullanılacak.'
    ], 'Ön lob ve arka lob başlıklarını; hormon–görev eşleşmelerini iki ayrı grupta oku.', 'ADH için üretim yeriyle kana verildiği yerin ayrılması neden gereklidir?', 'ADH hipotalamusta sentezlenir ve hipofizin arka lobundan salınır. Sentez ile salınma basamakları ayrılmazsa sinir-endokrin bağlantısı yanlış kurulmuş olur.'),
    s('Tiroit Bezi, Tiroksin ve Geri Bildirim', [26,27], [
      'p26’da tiroksin açıklamasının ardından vücut sıcaklığının düşmesiyle başlayan düzenleme sırasını izle. Hipotalamus ve hipofiz üzerinden tiroit etkinliğinin değişmesi, birden fazla merkezin birbirine bağlandığını gösterir. Tiroksinin metabolik etkinlikle ilişkisini hedefte oluşan sonuç üzerinden açıkla.',
      'Geri bildirim oklarını yalnız ileri yönlü uyarı zinciri olarak okuma. Sonuçta artan hormon veya düzelmeye başlayan değişken, önceki merkezlerin etkinliğini sınırlandırabilir. Negatif geri bildirim başlangıçtaki sapmayı azaltan düzenlemedir. p27’de tiroit işleviyle ilgili sonuçları okurken az ve fazla salgının farklı etkilerini ayır; tek belirtiyi bütün tiroit durumlarının ortak sonucu yapma.'
    ], 'p26’da “Vücut sıcaklığı düştüğünde” ile başlayan şemada ileri ve geri yönlü okları izle.', 'Tiroksin arttığında önceki merkezlerin uyarısının azalması neden negatif geri bildirimdir?', 'Ortaya çıkan sonuç, kendisini artıran başlangıç uyarısını sınırlar. Böylece hormon düzeyi ve düzenlenen iç koşulun aşırı sapması azaltılır.'),
    s('Paratiroit Bezi ve Timüs Bezi', [28], [
      'Paratiroit açıklamasında düzenlenen büyüklüğün kandaki kalsiyum olduğunu belirle. Bir hormonun etkisini açıklarken yalnız “kemiklere etki eder” demek yetmez; kalsiyumun hangi bölmeden hangisine geçtiğini ve kan düzeyinin hangi yönde değiştiğini söyle. Tiroit bölümündeki kalsiyum düzenlemesiyle karşılaştırırken aynı değişkeni izle.',
      'Timüs başlığına geçtiğinde bunun aynı kalsiyum kontrolünün başka bir basamağı olmadığını gör. Timüsün bağışıklık sistemiyle ilişkili rolü ayrı bir görev alanıdır. Bezlerin boyunda veya göğüs bölgesinde yakın konumlanması, aynı hormonları ürettiklerini göstermez. Yer, hormon ve hedef işlevini ayrı bilgilerin birleşimi olarak öğren.'
    ], 'Paratiroit açıklamasında kan kalsiyumunu; Timüs başlığında bağışıklıkla ilişkiyi bul.', 'Kan kalsiyumunu artıran bir etkiyi değerlendirirken yalnız kemikteki kalsiyuma bakmak yeterli midir?', 'Yeterli değildir. Kan düzeyi, kemik ve diğer organlardaki alım/geri emilim gibi süreçlerin birleşimine bağlıdır. Hangi bölmede artış veya azalış olduğu açıkça belirtilmelidir.'),
    s('Böbrek Üstü Bezleri', [29,30], [
      'p29’da kabuk/korteks hormonlarını, p30’da öz/medulla hormonlarını ayrı oku. Aynı bezin farklı bölgeleri farklı kimyasal yapıda ve farklı işlevde hormonlar üretebilir. Aldosteronun tuz-su düzenlenmesiyle, kortizolün metabolik yanıtlarla ilişkisini birbirinin yerine kullanma.',
      'Öz bölgesi hormonlarını okurken sinir sistemiyle koordinasyonu düşün. Stres veya acil yanıt sırasında kalp, solunum ve enerji kullanımı birlikte değişebilir. Bu etkiler bir organın bütün işlevlerini sınırsız artırma anlamına gelmez; organizmanın belirli koşula verdiği düzenlenmiş yanıttır. Bez adında “böbrek” geçmesi, bütün hormonlarının yalnız böbreğe etki ettiğini göstermez. Üretim konumu ve hedef doku yine farklı kavramlardır.'
    ], 'Korteks ve medulla başlıklarını; Aldosteron, Kortizol ve öz bölgesi hormonlarını ayrı eşleştir.', 'Böbrek üstü bezinin bir hormonunun kalbi etkilemesi neden çelişki değildir?', 'Bez adı üretim yerini belirtir. Hormon kana verildikten sonra uygun reseptör taşıyan uzak hedeflerde de etki gösterebilir.'),
    s('Pankreas ve Eşeysel Bezler', [30,31], [
      'p30’daki pankreas başlığında insülin ve glukagonu aynı değişken üzerinde karşılaştır: kan glikozu. Kan glikozu yükseldiğinde insülinle ilişkili hücresel kullanım ve depolama süreçleri, düştüğünde glukagonla ilişkili depoların kullanımı öne çıkar. İki hormonun karşıt etkileri, dengelenen değişkenin iki yöndeki sapmasına yanıt verir.',
      'p31’de yumurtalık ve testis hormonlarını görevleriyle oku. Östrojen, progesteron ve testosteron yalnız ikincil eşey özellikleriyle sınırlı değildir; üreme düzenlenmesiyle de ilişkilidir. Bir hormonun adını bir cinsiyet etiketi gibi kullanmadan, üretildiği doku ve fizyolojik görevi birlikte düşün. Üreme dersinde bu hormonların zamana bağlı değişimlerini aynı kitaptaki döngü grafiğinde yeniden izleyeceksin.'
    ], 'Pankreasta İnsülin/Glukagon başlıklarını, sonra p31’de Yumurtalık/Testis hormonlarını incele.', 'Kan glikozunun düşmesiyle insülin etkisinin artmasını beklemek neden uygun değildir?', 'İnsülinin temel etkileri kan glikozunun düşürülmesine katkı verir. Düşük glikozda karşı düzenleyici yollar, özellikle glukagonla ilişkili glikoz sağlanması önem kazanır.')
  ]);

  add('bio-ayt-03', 'Duyu Organları', 'AYT-bio', '32–44. sayfalarda reseptörlerden deri, koku/tat, kulak ve göze; ardından rahatsızlıklar bölümüne ilerleyeceğiz.', [
    s('Duyu Reseptörleri, Deri ve Derinin Tabakaları', [32,33,34], [
      'p32’de reseptörleri algıladıkları uyarı türüne göre karşılaştır. Reseptör bir çevresel değişikliği sinir sisteminin işleyeceği sinyale dönüştürür; bütün reseptörler aynı tür enerjiye aynı duyarlılığı göstermez. Duyunun oluşmasında yalnız reseptör değil, sinir yolu ve merkezî değerlendirme de önemlidir.',
      'Deri bölümünde epitel ve bağ dokuyu, ardından üst deri ve alt deriyi izle. p34’teki farklı duyu yapılarının adlarını algıladıkları uyarıyla bağla. Basınç, sıcaklık, dokunma ve ağrı aynı reseptörün tek tip yanıtı gibi ele alınmaz. Bir yapının deride bulunmasıyla derinin bütün tabakalarında eşit dağıldığı sonucu çıkarılamaz. Tabaka çiziminde reseptörün konumu ile görevi birlikte okunur.'
    ], 'Reseptör tablosunu ve deri tabakalarında farklı duyu yapılarının yerlerini karşılaştır.', 'Reseptörün uyarılması neden bilinçli duyunun oluşmasının tamamı değildir?', 'Oluşan sinyalin sinir yollarıyla ilgili merkezlere taşınıp işlenmesi gerekir. Algı, reseptör yanıtı ile merkezî değerlendirmenin birlikte sonucudur.'),
    s('Burun ve Dil', [35], [
      'Koku alma çiziminde koku molekülü, mukus, reseptör ve koku alma yolunu takip et. Molekülün reseptöre ulaşabilmesi için uygun ortamda çözünmesi önemlidir. Koku uyaranının burundan doğrudan düşünceye dönüştüğünü varsaymak yerine reseptörde başlayan sinirsel iletim basamağını açıkla.',
      'Tat açıklamasını okurken besin maddelerinin çözünmesi ve tat reseptörleriyle etkileşmesini koku yoluyla karşılaştır. Tat ve koku farklı reseptör sistemleri olsa da besin algısına birlikte katkı verebilir. Dildeki tek bir bölgenin yalnız tek bir tadı algıladığı şeklindeki katı bölge ezberini kullanma; kitabın reseptör ve uyarı ilişkisini esas al. Uyarının kimyasal olması, iki duyunun aynı sinir yolunu kullandığını göstermez.'
    ], 'Koku moleküllerinden reseptörlere ve koku alma yoluna giden etiketleri; dildeki tat açıklamasını izle.', 'Burun tıkalıyken besinin farklı algılanması tat ve kokunun nasıl ilişkili olduğunu düşündürür?', 'Besinin genel algısına tatla birlikte koku da katkı verir. Koku bilgisinin azalması deneyimi değiştirebilir; bu durum tat ve koku reseptörlerinin aynı yapı olduğu anlamına gelmez.'),
    s('Kulağın Genel Yapısı, Dış Kulak, Orta Kulak ve İç Kulak', [36,37], [
      'p36’da kulağı dış, orta ve iç kulak olarak üç bölgede incele. Sesin toplanması ve mekanik titreşimin aktarılmasıyla ilgili yapıları sıraya koy. Kulak zarı ve orta kulak kemikçiklerini iç kulaktaki duyu reseptörleriyle aynı görevde sayma.',
      'p37’de iç kulak yapılarına geç. Salyangozun işitmeyle, dengeyle ilgili diğer yapıların ise başın hareketi ve konumuyla bağlantısını ayır. İç kulakta sıvı hareketinin bulunması, sesin tüm yol boyunca aynı ortamda ilerlediği anlamına gelmez. p36–37’deki anatomiyi, sonraki işitme olayının haritası olarak kullan; her yapıda enerjinin hangi biçimde aktarıldığını sor.'
    ], 'Dış–orta–iç kulak sınırlarını; kulak zarı, kemikçikler ve salyangozun sırasını çizimde izle.', 'Orta kulak kemikçikleri ile salyangoz reseptörleri aynı işi mi yapar?', 'Hayır. Kemikçikler mekanik titreşimin aktarılmasında görev alır; salyangozdaki reseptörler mekanik etkiyi sinirsel sinyale dönüştürme sürecine katılır.'),
    s('İşitme Olayı ve Denge', [38,39], [
      'p38’de işitme olayını başlangıçtan sona izlerken ses titreşiminin aktarımıyla sinirsel iletimin başladığı noktayı ayır. Salyangoz içindeki mekanik değişimler reseptörleri etkiler, oluşan sinyaller ilgili sinir yollarıyla değerlendirme merkezlerine taşınır. Sesin şiddeti ve frekansı aynı fiziksel büyüklük değildir.',
      'p39’daki Denge başlığı ayrı bir öğrenme durağıdır. Yarım daire kanalları ve diğer denge yapılarının başın farklı hareketleriyle ilişkisini incele. İşitme ile denge aynı organ bölgesinde bağlantılı yapılar kullanır, fakat aynı uyarıyı algılamak zorunda değildir. Dengeyi yalnız kulakla açıklamak da eksik kalır; görsel bilgi ve kas-eklem duyuları vücut konumunun düzenlenmesine katkı verir.'
    ], 'p38’de işitmenin sırasını, p39’da Denge başlığındaki hareket algılayan yapıları ayrı incele.', 'İç kulakta bulunmaları işitme ve denge reseptörlerinin aynı uyarıyı algıladığını gösterir mi?', 'Göstermez. İşitme ses kaynaklı titreşimlerle, denge sistemi başın hareket ve konum değişimleriyle ilişkili mekanik etkileri algılar.'),
    s('Gözün Genel Yapısı, Retina ve Görme Olayı', [40,41,42], [
      'p40’ta gözün tabakalarını dıştan içe izle. Işığın kornea, göz bebeği ve mercek üzerinden retinaya ulaşma yolunu, tabakaların anatomik sırasıyla karıştırma. Merceğin kırma işlevi görüntünün retinaya odaklanmasına yardım eder; iris ise göz bebeği açıklığını düzenler.',
      'p41’de retina ve fotoreseptörleri, p42’de görme yolunu oku. Işığın göze girmesi ile sinirsel sinyalin beyne ulaşması ayrı basamaklardır. Optik sinir ve optik kiyazma çiziminde sağ/sol görme alanlarının yollarını etiketlerden takip et; yalnız gözün sağda veya solda olmasına göre tek bir beyin yarım küresine bütün olarak bağlandığını varsayma. Görme, optik odaklanma ile sinirsel değerlendirmenin birleşimidir.'
    ], 'p40–41’de ışığın retinaya ulaşma yolunu; p42’de Optik kiyazma ve Görme korteksi etiketlerini takip et.', 'Göz merceğinin göreviyle fotoreseptörün görevi nasıl ayrılır?', 'Mercek ışığı kırarak odaklanmaya katkı verir. Fotoreseptör ışığı algılayıp sinirsel sinyal oluşumunu başlatır; odaklama ve sinyal dönüşümü farklı basamaklardır.'),
    s('Duyu Organları Rahatsızlıkları ve Sağlıklı Yapının Korunması', [43,44], [
      'p43’te görme bozuklukları tablosunu Normal Görüş ile karşılaştır. Görüntünün retinanın önünde veya arkasında oluşması, düzeltmede kullanılan mercek türüyle bağlantılıdır. Önce görüntünün konumunu söyle, ardından ışınları hangi yönde düzenlemenin gerekli olduğunu düşün. Astigmatizm için verilen farklı düzeltmeyi diğerleriyle aynı sayma.',
      'p44’te koruma önerilerini ilgili yapının göreviyle bağla. Derinin korunması, göz ve kulağın uygun kullanılması birbirinden farklı gereksinimler içerir. Bu sayfalardaki örnekler tıbbi tanı koydurmak için değil, duyusal yapıların hasar gördüğünde işlevin nasıl etkilenebileceğini öğretmek içindir. Optik bir odaklanma sorunu ile sinirsel iletim sorununun aynı mercekle düzeltilmesi beklenmez.'
    ], 'Normal Görüş–Görme Bozuklukları–Düzeltme Biçimleri tablosunda aynı satırı yatay oku.', 'Miyoplukta görüntünün retinanın önünde oluşmasını düzeltmek için neden uygun mercek gerekir?', 'Gözün optik sisteminin ışınları odaklama düzeni değiştirilmelidir. Uygun mercek görüntünün retina üzerine düşmesine yardım eder; reseptörün görevini değiştirmez.')
  ]);

  add('bio-ayt-04', 'Destek ve Hareket Sistemi', 'AYT-bio', '45–61. sayfalarda kemik ve eklemlerden kas çeşitlerine, sarkomer ve enerji kullanımına ilerleyeceğiz.', [
    s('Kemik Doku, Kemik Çeşitleri ve İskeletin Bölümleri', [45,46,47,48,49], [
      'p45–46’da sıkı ve süngerimsi kemik dokuyu çizimde karşılaştır. Kemiğin canlı hücreler ve hücre dışı maddeden oluştuğunu; yalnız cansız bir mineral kütlesi olmadığını gör. Yapısındaki organik ve inorganik bileşenlerin birlikteliği dayanıklılık ve esneklikle ilişkilidir.',
      'p47’de uzun, kısa, yassı ve düzensiz kemik örneklerini şekil ve işlevle eşleştir. p48–49’da eksen ve üyeler iskeletini takip et. Bir kemiğin uzun kemik sayılması yalnız toplam santimetresiyle ilgili değildir; yapısal biçimi esas alınır. Destek ve koruma kadar hareket, mineral dengesi ve kemik iliğiyle bağlantılı işlevleri de bölümdeki açıklamalardan oku.'
    ], 'Sıkı/süngerimsi doku çizimini; ardından kemik çeşitleri ve iskelet bölümleri başlıklarını izle.', 'Kemik neden yalnız kalsiyumdan oluşan cansız bir yapı gibi açıklanamaz?', 'Canlı kemik hücreleri, organik yapı ve mineral bileşenler birlikte bulunur. Kemik büyüyebilir, yenilenebilir ve metabolik süreçlere katılır.'),
    s('Kıkırdak Doku ve Eklemler', [50,51], [
      'p50’de kondrosit, kondrin, lifler ve verilen kıkırdak örneklerini incele. Kıkırdak çeşitlerini bulundukları yerdeki mekanik gereksinimle ilişkilendir. Kulak kepçesi, soluk borusu ve omurlar arası disk örneklerinin hepsini aynı sertlik ve esneklikte sayma.',
      'p51’de eklem çeşitlerine geç. Hareketin miktarı ve yapısal düzen eklem türüne göre değişir. Oynar eklem çiziminde kıkırdak, kapsül, ligament ve sinoviyal sıvıyı ayrı görevlere bağla. Ligamenti kasın kemiğe bağlanmasını sağlayan tendonla karıştırma. Eklem yüzeylerinin korunması ve kemiklerin bir arada tutulması, hareketin yalnız kas kısalmasından ibaret olmadığını gösterir.'
    ], 'p50’de kıkırdak örneklerini; p51’de Ligament, Sinoviyal sıvı ve Kapsül etiketlerini karşılaştır.', 'Ligament ile tendonun işlevi neden aynı değildir?', 'Ligament eklemde kemikleri birbirine bağlayan düzenin parçasıdır. Tendon kas ile kemik arasındaki kuvvet aktarımını sağlar; bağladıkları yapılar farklıdır.'),
    s('Kas Doku ve Kas Çeşitleri', [52,53,54], [
      'p52’de kas demetinden kas lifine, miyofibrilden sarkomere doğru çizimi takip et. Bu yapılar farklı büyüklük düzeyleridir. Aktin ve miyozin filamentlerini bütün kas hücresiyle aynı şey sayma; bunlar hücre içindeki kasılma düzeninin bileşenleridir.',
      'p53–54’te iskelet, düz ve kalp kasını aynı ölçütlerle karşılaştır. Çizgilenme, çekirdek düzeni, istemli/istemsiz kontrol ve çalışma özellikleri birbirinden ayrı satırlardır. Kalp kasının çizgili olması, denetiminin iskelet kasıyla tamamen aynı olduğu anlamına gelmez. Yapısal benzerlik ile kontrol biçimini ayrı değerlendir. Bu karşılaştırma p55’te ayrıntısı verilen iskelet kası modelinin hangi kas türü için anlatıldığını da sınırlar.'
    ], 'Kas demeti → kas lifi → miyofibril → sarkomer büyüklük sırasını ve üç kas türünü izle.', 'Kalp kasının çizgili olması neden istemli çalıştığını göstermez?', 'Çizgilenme filamentlerin düzenini, istemli/istemsiz kontrol ise sinirsel düzenlenmeyi anlatır. Kalp kası çizgili yapıya sahipken istemsiz çalışır.'),
    s('Sarkomerdeki Bantlaşma ve Kasılma Mekanizması', [55], [
      'Gevşemiş ve kasılmış sarkomer çizimlerini aynı Z çizgilerinden başlayarak karşılaştır. Kasılmada Z çizgileri yaklaşır, sarkomer kısalır. Aktin ve miyozin filamentlerinin kendi uzunlukları aynı kalırken birbirlerinin üzerinden kaymaları örtüşmeyi değiştirir.',
      'A, I ve H bantlarını çizimden izle. A bandı miyozin uzunluğuyla bağlantılı olduğundan aynı kalır; I ve H bölgeleri daralır. Bu sonucu “bütün çizgiler kısalır” diye ezberlemek yerine her bölgenin hangi filamentleri içerdiğini söyle. Bütün kasın kısalması, yapı taşlarının her birinin kısalmasını gerektirmez. Kayan filament modeli bu görünürdeki farkı açıklar.'
    ], 'Kasılma/Gevşeme çizimlerinde Z çizgileri, A bandı, I bandı ve H bandını aynı sırayla karşılaştır.', 'Kas kısaldığı hâlde A bandının aynı kalması nasıl açıklanır?', 'Miyozin filamentinin uzunluğu değişmez. Kısalma filamentlerin kayıp daha çok örtüşmesiyle oluşur; A bandı miyozin uzunluğunu yansıttığı için aynı kalır.'),
    s('Kasılma ve Gevşeme Mekanizması', [56], [
      'p56’daki sırayı sinir uyarısı, kalsiyumun düzenlenmesi ve aktin-miyozin etkileşimi üzerinden takip et. Sarkoplazmik retikulum ile sitoplazma arasındaki Ca2+ hareketi, bağlanma bölgelerinin kullanılabilirliğini etkiler. Kalsiyumun rolü enerji vermek değil, etkileşimin başlamasını sağlayan düzenlemeye katılmaktır.',
      'Miyozin başının hareketinde ATP’nin kullanımını ve yeniden ayrılma basamağını izle. Gevşeme de enerjiyle ilişkili süreçler içerir; kalsiyumun geri taşınması ve çapraz köprü döngüsünün sona ermesi pasif bir “her şey durdu” olayı değildir. Bu yüzden ATP yokluğunu doğrudan normal gevşeme olarak yorumlama. Mekanizmanın her basamağında hangi yapı bağlanıyor, hangisi ayrılıyor diye sor.'
    ], 'Ca2+, Sarkoplazmik retikulum, Aktin üzerindeki özel protein ve Miyozin başı etiketlerini ok sırasıyla izle.', 'Kalsiyum ile ATP’nin kasılmadaki rolleri neden aynı değildir?', 'Kalsiyum bağlanma düzenini etkinleştiren düzenlemeye katılır. ATP çapraz köprü döngüsüne ve iyonların geri taşınması gibi enerji gerektiren basamaklara katkı verir.'),
    s('Enerji Metabolizması, Kasılmanın Kontrolü ve Kas-İskelet İlişkisi', [57,58,59,60,61], [
      'p57’de enerji kaynakları ve egzersiz süresini birlikte gösteren açıklamaları oku. Hazır ATP, fosfat deposu ve hücresel enerji dönüşüm yollarının katkıları zamanla değişebilir; kasın bütün etkinlik boyunca yalnız tek kaynağı kullandığını varsayma. p58’de tek kasılma ve art arda uyarı grafiklerinde yatay eksenin zaman olduğunu kontrol et.',
      'p59’da antagonistik kasların aynı hareket için nasıl karşılıklı düzenlendiğini çizimden izle. Kasların kemiği çekmesiyle eklem hareketi oluşur; bir kasın her yönde aktif itme yapması gerekmez. Devamındaki rahatsızlık ve koruma açıklamalarını kemik, eklem ve kasın birlikte çalışmasına bağla. Bir yapının hasarı yalnız o yapı adını değil, bütün hareket zincirinin işleyişini etkileyebilir.'
    ], 'p57’de enerji katkıları, p58’de kasılma-zaman çizimleri ve p59’da Kasılır/Gevşer etiketlerini karşılaştır.', 'Art arda çok sık uyarı ile tek uyarı aynı kasılma grafiğini verir mi?', 'Vermez. Kas tam gevşemeden gelen uyarılar kasılmaların eklenmesine yol açabilir; uyarı sıklığı kasılmanın zaman içindeki biçimini değiştirir.')
  ]);

  add('bio-ayt-05', 'Sindirim Sistemi', 'AYT-bio', '62–76. sayfalarda besinin izlediği yolu ve her organda gerçekleşen işlemi kitabın şekil ve tepkimeleriyle okuyacağız.', [
    s('Sindirimin Amacı ve Çeşitleri; Sindirim Sisteminin Genel Yapısı', [62,63], [
      'p62’de büyük yağ damlası, küçük damlacıklar ve lipaz etkisi arasındaki farkı incele. Safranın damlaları küçültmesi kimyasal bağların enzimle hidroliz edilmesiyle aynı değildir. Mekanik parçalama yüzeyi artırırken kimyasal sindirim büyük molekülleri emilebilecek küçük birimlere dönüştürür.',
      'p63’te ağızdan anüse uzanan kanalı, tükürük bezleri, karaciğer ve pankreas gibi yardımcı yapılardan ayır. Besin kanal boyunca ilerler; her yardımcı organın içinden geçmesi gerekmez. Bir salgının organda üretilmesi ile etkisini gösterdiği yere verilmesi farklı basamaklardır. Kanal ve salgı yolu ayrımını ilk haritada kurmak sonraki sayfalardaki enzim kaynaklarını anlamanı sağlar.'
    ], 'p62’de Safra tuzları ve Lipaz enzimi etiketlerini; p63’te kanal/yardımcı yapı ayrımını izle.', 'Safranın yağı küçük damlacıklara ayırması neden tek başına kimyasal sindirim değildir?', 'Yağın moleküler bağlarının hidrolizi gerçekleşmez; fiziksel dağılım ve yüzey artışı olur. Kimyasal parçalanmayı uygun enzimlerin etkisi yürütür.'),
    s('Ağız, Yutak ve Yemek Borusu', [64,65,66], [
      'Ağız sayfasında çiğneme ve tükürükle başlayan işlemleri ayrı oku. Mekanik küçültme ile enzimatik sindirim aynı yerde birlikte bulunabilir ama farklı değişimlerdir. Bir besinin ağızda bulunması, içerdiği bütün organik moleküllerin sindiriminin burada başladığı anlamına gelmez.',
      'p65’te yutma çiziminde küçük dil ve gırtlak kapağının konumlarını izleyerek lokmanın doğru yola yönlendirilmesini açıkla. p66’da yemek borusunun kasılma-gevşeme düzenini takip et. Peristaltik ilerleme, besinin yalnız yer çekimiyle düştüğü bir boru modeli değildir. Bu sayfalardaki temel işlem taşıma ve yönlendirmedir; her geçilen organ mutlaka yeni sindirim enzimi üretmez.'
    ], 'Yutma şemasında gırtlak kapağı ve sfinkterleri; yemek borusunda Kasılma/Gevşeme etiketlerini takip et.', 'Yemek borusunda besinin ilerlemesini yalnız yer çekimiyle açıklamak neden eksiktir?', 'Peristaltik kasılma ve gevşemeler besini kanal boyunca iter. Kanalın kas faaliyeti, yalnız aşağı düşmeden farklı aktif bir taşıma düzenidir.'),
    s('Mide, İnce Bağırsak ve Kalın Bağırsak', [67,68,69], [
      'p67’de midenin salgı ve kas hareketleriyle besine etkisini oku. Asidik ortam ve protein sindirimiyle ilgili enzim düzeni birlikte değerlendirilir. Midenin kendi yüzeyinin korunması, bu kuvvetli kimyasal ortamın dokuyla kontrollü ilişkisine bağlıdır.',
      'p68’de ince bağırsağın sindirim ve emilimdeki rolüne, p69’da kalın bağırsağın görevlerine geç. Aynı kanalın devamı olmaları aynı işi yaptıklarını göstermez. İnce bağırsakta sindirim ürünlerinin alınmasıyla kalın bağırsaktaki su ve diğer maddelerle ilgili işlemleri ayır. Büyük yüzey sağlayan bağırsak yapısını, emilimin verimliliğiyle ilişkilendir; yalnız organın toplam uzunluğunu ezberlemekle yetinme.'
    ], 'Mide → İnce Bağırsak → Kalın Bağırsak sırasındaki yapı ve görev başlıklarını karşılaştır.', 'Kalın bağırsağın bulunması, bütün besin monomerlerinin esas olarak burada emildiğini gösterir mi?', 'Göstermez. Besinlerin sindirim ve emiliminin büyük bölümü ince bağırsakla ilişkilidir. Kalın bağırsağın görevleri farklı ağırlıklara sahiptir.'),
    s('Tükürük Bezleri, Pankreas, Karaciğer ve Safra Kesesi', [70,71], [
      'p70’te yardımcı yapıların salgılarını, bunların verildiği kanala bağla. Pankreasın sindirim enzimleri ve ortam koşullarını düzenleyen salgısı, endokrin bölümde öğrendiğin insülin/glukagonla aynı salgı yolu üzerinden değerlendirilmez. Aynı organın dış salgı ve iç salgı işlevlerini ayır.',
      'p71’de karaciğer ile safra kesesi arasındaki üretim-depolama ilişkisini oku. Safra karaciğerde üretilir; safra kesesiyle ilişkisi üretim yeriyle aynı değildir. Safra bir sindirim enzimi değildir. Kitabın Karaciğerin Diğer Görevleri başlığı, bu organın yalnız safra üretimine indirgenemeyeceğini gösterir. Her salgı için nerede üretilir, nereye gider, neyi değiştirir sorularını sırayla yanıtla.'
    ], 'p70’te Pankreas, p71’de Karaciğer ve Safra Kesesi başlıklarında üretim ve etki yerlerini bul.', 'Safra kesesinin alınması safra üretiminin de tamamen yok olması demek midir?', 'Safra üretim yeri karaciğerdir; safra kesesi depolama ve verilme düzeniyle ilişkilidir. Üretim organıyla depolama yapısı aynı değildir.'),
    s('Besinlerin Kimyasal Sindirimi', [72,73], [
      'p72’de karbonhidratların sindirimini başlangıç maddesi, enzim ve ürün sırasıyla izle. Bir enzimin son ürünü başka bir enzimin substratı olabilir. Nişastadan monomerlere kadar ilerleyen yol, tek bir enzimin tek basamakta bütün dönüşümü yaptığı anlamına gelmez.',
      'p73’te protein ve yağların sindirimine geç. Proteinlerin farklı büyüklükte peptitlere ve sonunda amino asitlere dönüşmesini, yağların sindirim ürünleriyle karıştırma. Her tepkime için hangi bağın hidrolizi ve hangi küçük birimlerin oluşması anlatılıyor diye sor. Kitaptaki organ adlarını enzimlerin üretim yeriyle otomatik eşitleme; pankreasta üretilen bir enzim bağırsakta çalışabilir. Sindirimin gerçekleştiği ortam ile enzimin kaynağını ayrı izlemek gerekir.'
    ], 'Karbonhidrat, protein ve yağ şemalarında substrat → enzim → ürün oklarını ve organ adlarını takip et.', 'Bir enzimin ince bağırsakta çalışması mutlaka ince bağırsak hücresinde üretildiğini gösterir mi?', 'Hayır. Enzim pankreas gibi yardımcı bir organda üretilip kanalla bağırsağa verilebilir. Üretim ve çalışma yerleri farklı olabilir.'),
    s('Nükleik Asitlerin Sindirimi ve Besinlerin Emilimi', [74], [
      'Sayfanın ilk başlığında nükleik asitlerin daha küçük bileşenlere ayrılmasını oku. Ardından Besinlerin Emilimi başlığına geçtiğinde olay değişir: sindirim molekülü küçültür, emilim oluşan maddelerin bağırsak sınırını geçip iç ortama alınmasıdır. Bir maddenin sindirilmesiyle emilmesi aynı basamak değildir.',
      'Villus ve taşıma yollarını incelerken kan ile lenf yolunu ayır. Farklı sindirim ürünleri aynı ilk taşıma yolunu izlemek zorunda değildir. Bağırsak yüzeyinin kıvrımlar ve çıkıntılarla artması, emilim alanını büyütür. Su, mineral ve vitaminlerin alınmasını her zaman önce polimer hidrolizi gerektiren bir süreç gibi gösterme; maddenin başlangıç yapısı belirleyicidir.'
    ], 'Besinlerin Emilimi bölümünde bağırsak yüzeyi, kan kılcalları ve lenf bağlantısını ayırt et.', 'Sindirimin tamamlanması emilimin de tamamlandığı anlamına gelir mi?', 'Gelmez. Moleküllerin uygun küçüklüğe ayrılması bir basamaktır; bağırsak hücreleri üzerinden kan veya lenfe geçmeleri ayrı bir taşıma sürecidir.'),
    s('Sindirim Sistemi Rahatsızlıkları ve Sağlıklı Yapının Korunması', [75,76], [
      'Reflü, gastrit ve ülser örneklerini aynı hastalığın farklı adları gibi okumadan, hangi yapı veya sürecin etkilendiğine bak. Besinin geri kaçışı, yüzeyde iltihap veya doku hasarı farklı durumları anlatır. p76’daki diğer bağırsak örneklerini de su dengesi ve kanal işlevleriyle ilişkilendir.',
      'Sağlığı koruma önerilerini önceki sayfalarda öğrendiğin işlevlerle bağla. Yeterli su, uygun beslenme ve hijyen farklı süreçlere katkı verir. Bu bölümdeki hastalık adları tek bir belirtiden tanı koymak için kullanılmaz; normal yapı-görev ilişkisinin bozulmasının sonuçlarını anlamaya yarar. Mekanik sindirim, enzimatik sindirim, taşıma ve emilim basamaklarından hangisinin etkilendiğini söylemek öğrenmeyi somutlaştırır.'
    ], 'Rahatsızlıkların adını, etkilenen yapı ve normal işleviyle birlikte oku.', 'İshalde su kaybının önemini hangi normal bağırsak göreviyle ilişkilendirirsin?', 'Bağırsaklarda suyun alınması ve dışkının su içeriğinin düzenlenmesi normal işlevlerdendir. Bu dengenin bozulması fazla su kaybına yol açabilir.')
  ]);

  add('bio-ayt-06', 'Kan Dolaşımı, Lenf Dolaşımı ve Bağışıklık', 'AYT-bio', '77–97. sayfalarda kalp ve damarlardan kan dokuya, lenfe ve bağışıklık belleğine kitabın düzeniyle ilerleyeceğiz.', [
    s('Dolaşım Sisteminin Genel Yapısı ve Kalbin Yapısı', [77,78], [
      'Kalp çiziminde önce sağ ve sol tarafı şeklin bakış yönüne göre belirle. Kulakçıklar ve karıncıklar kanın farklı basamaklarda bulunduğu odacıklardır. Kapakçıkların konumları kanın tek yönlü ilerlemesine katkı verir; kanı pompalayan temel etki kalp kasının kasılmasıyla oluşan basınç farkıdır.',
      'Damar adlarını yalnız taşıdığı oksijene göre öğrenme. Atardamar kalpten çıkan, toplardamar kalbe dönen damardır. Akciğer dolaşımı bu tanımın oksijenli/oksijensiz ayrımıyla aynı olmadığını açıkça gösterir. Bölmelerin kas kalınlığını pompaladıkları yolun gereksinimiyle ilişkilendir. Anatomiyi bu biçimde okursan bir sonraki sayfadaki döngüde kanın neden belirli yönde ilerlediğini açıklayabilirsin.'
    ], 'Kalbin odacık, kapakçık ve giren/çıkan damarlarını çizimde sırayla bul.', 'Akciğer atardamarının oksijence fakir kan taşıması atardamar tanımına aykırı mıdır?', 'Değildir. Atardamarın tanımı kalpten uzaklaşan kanı taşımasıdır; oksijen düzeyi tanımın kendisi değildir.'),
    s('Kanın Kalpteki Hareketi ve Kalp Ritminin Kontrolü', [79,80], [
      'p79’daki dört aşamayı okurken hangi odacığın kasılıp hangisinin gevşediğini söyle. Kapakların açılması veya kapanması basınç ilişkilerine bağlıdır. Kanın yönünü yalnız ezber bir ok olarak değil, basıncın yüksek olduğu bölgeden düşük bölgeye akış olarak düşün.',
      'p80’de ritim oluşumu ve iletimini sağlayan düzeni takip et. Kalbin kendi uyarı oluşturabilmesi ile sinir ve hormonların çalışma hızını düzenlemesi birlikte doğru olabilir. Sinirsel düzenleme bulunması, her kalp atımının mutlaka beyinden gelen ayrı bir komutla başlatıldığı anlamına gelmez. Uyarının kalp dokusunda yayılması, odacıkların uygun sırada kasılmasına katkı verir.'
    ], 'Dört döngü aşamasında kapakların durumunu; p80’de uyarının kalpte izlediği yolu incele.', 'Kalp ritminin otonom sinirlerle değişmesi kalbin kendi uyarı oluşturmasını dışlar mı?', 'Dışlamaz. Kalbin uyarı oluşturma düzeni vardır; otonom sinirler ve hormonlar bu düzenin hızını ve etkinliğini değiştirebilir.'),
    s('Küçük ve Büyük Kan Dolaşımı', [81,82], [
      'p81’de küçük dolaşımı sağ karıncıktan başlayarak akciğerler ve sol kulakçığa kadar izle. Büyük dolaşımda sol karıncıktan dokulara, oradan sağ kulakçığa dönüşü takip et. İki yol birbirinden kopuk devreler değildir; kalpte art arda bağlanan dolaşım halkalarıdır.',
      'Oksijen düzeyinin nerede değiştiğini ayrıca işaretle. Akciğer kılcallarında kanla hava arasında, doku kılcallarında kanla hücreler arasında gaz alışverişi olur. Kalp odacıkları arasından geçmek tek başına kanı oksijenlendirmez. Dolaşım yolunu anlatırken damar adı, akış yönü ve kanın oksijen durumunu üç ayrı bilgi olarak söyle. Bu ayrım karmaşık bir şekli yeniden kurmanı kolaylaştırır.'
    ], 'Küçük ve Büyük Kan Dolaşımı yollarını farklı başlangıç karıncıklarından başlayarak takip et.', 'Kan sağ karıncıktan çıktıktan hemen sonra neden oksijenlenmiş sayılmaz?', 'Oksijenlenme kalpten çıkış anında değil, akciğer kılcallarıyla alveoller arasındaki gaz alışverişinde gerçekleşir.'),
    s('Kan Damarları ve Kılcal–Doku Sıvısı Alışverişi', [83,84,85], [
      'p83’te atardamar, kılcal ve toplardamar yapılarını karşılaştır. Duvar kalınlığı, kas/bağ doku ve kapakçık özellikleri akış koşullarıyla ilişkilidir. p84’te toplam kesit alanı ile kanın akış hızının aynı büyüklük olmadığını grafiklerden gör; tek bir kılcal dar olsa da bütün kılcalların toplam alanı büyüktür.',
      'p85’te madde alışverişini okurken kan basıncı ve ozmotik etkilerin yönlerini ayrı değerlendir. Doku sıvısıyla kan arasındaki geçiş, damarın bütün noktalarında aynı yönde olmak zorunda değildir. Lenf yolunun geri dönüşe katkısını da sonraki bölümle ilişkilendir. Bir grafikte hızın düşük olması, kanın durduğu veya madde alışverişinin gerçekleşmediği anlamına gelmez.'
    ], 'p84’te Kesit Alanı/Akış Hızı ve Kan Basıncı grafiklerini; p85’te alışveriş oklarını izle.', 'Kılcallarda toplam kesit alanı büyükken akış hızının düşük olması neden yararlıdır?', 'Daha yavaş geçiş kan ile dokular arasında madde alışverişi için uygun süre sağlar. Toplam alan bütün kılcalların birlikte değerlendirilmesidir; tek damar çapıyla aynı nicelik değildir.'),
    s('Kan Doku: Plazma, Hücresel Elemanlar ve Pıhtılaşma', [86,87,88], [
      'p86’da plazma ile hücresel elemanları ayır. Alyuvarların gaz taşınmasıyla ilişkisini, kanın bütün görevlerini tek hücreye yüklemeden oku. p87’de akyuvarlar ve trombositlere geçtiğinde savunma ile pıhtılaşmanın farklı görevler olduğunu gör.',
      'Zedelenmiş damarda pıhtı oluşumu çizimini olay sırasıyla izle; trombositlerin katkısını normal kanın her yerde sürekli pıhtılaşması gibi yorumlama. p88’de kan grupları tablosunda antijen ve antikorun bulunduğu yeri ayır. Hücre yüzeyindeki yapı ile plazmadaki antikor aynı şey değildir. Grup adının arkasındaki bu moleküler farkı anlamak, uygun olmayan birleşmelerin neden sorun oluşturabileceğini açıklar.'
    ], 'Plazma/Alyuvarlar başlığından p87 pıhtı şemasına, ardından p88 ABO tablosuna ilerle.', 'Kan grubundaki antijen ile antikoru aynı yerde saymak neden yanlıştır?', 'ABO modelinde antijenler alyuvar yüzeyiyle, ilgili antikorlar plazmayla ilişkilidir. Konum ve görevleri farklı moleküler bileşenlerdir.'),
    s('Lenf Dolaşımı ve Dolaşım Sistemi Rahatsızlıkları', [89,90,91,92,93], [
      'p89’da lenf sıvısını doku sıvısının dolaşıma geri dönmesiyle ilişkilendir. Lenf damarları ve lenf düğümleri aynı işlevi üstlenen tek bir boru sistemi değildir; sıvının taşınmasıyla bağışıklıkla ilgili süzme/yanıt ilişkilerini ayır. p90’da lenfin izlediği yolları okların yönüyle takip et.',
      'Ödem nedenlerini incelerken sıvı çıkışı ile geri dönüş arasındaki dengeyi düşün. Fazla sıvının dokuda birikmesi yalnız fazla su içilmesiyle açıklanamaz. p91–93’teki dolaşım rahatsızlıklarını normal damar, basınç ve kalp görevleriyle bağla. Damar tıkanması, kapak işlevi veya basınç değişimi farklı süreçleri etkileyebilir; aynı belirti listesi bütün mekanizmaların aynı olduğu anlamına gelmez.'
    ], 'Lenf dolaşımı yolunu, Ödeme Neden Olan Durumlar açıklamasını ve devamdaki rahatsızlıkları izle.', 'Lenf dönüşünün azalması dokuda neden sıvı birikimine katkı verebilir?', 'Dokuya çıkan sıvının bir bölümü lenfle dolaşıma geri taşınır. Bu yol aksarsa çıkış ve geri dönüş dengesi bozulup doku sıvısı artabilir.'),
    s('Doğal Bağışıklık ve Savunma Hatları', [94,95], [
      'p94’te birinci ve ikinci savunma hattını ayrı oku. Deri ve salgılar gibi dış engellerle, içeri giren etkenlere karşı çalışan hücresel ve kimyasal yanıtlar farklı basamaklardır. Doğal bağışıklık hızlı ve genel savunma sağlar; her patojene ilk kez rastlanıldığında sıfırdan tamamen aynı ayrıntılı özgül yanıtın kurulmasıyla tanımlanmaz.',
      'p95’teki örnekleri fagositoz, iltihaplanma ve diğer savunma süreçleriyle ilişkilendir. Bir akyuvarın mikroorganizmayı içine alıp parçalama görevi ile antikor üretimi aynı mekanizma değildir. Doğal ve kazanılmış sistemler birbirinden kopuk çalışmaz; sonraki sayfadaki özgül yanıtın düzenlenmesine doğal savunma da katkı verebilir.'
    ], 'Birinci Savunma Hattı ve İkinci Savunma Hattı başlıklarında örnekleri iki grupta oku.', 'Deri bariyeri ile antikor üretimini aynı savunma basamağı saymak neden yanlıştır?', 'Deri girişe karşı genel bir dış engeldir. Antikor üretimi belirli antijenlere yönelik kazanılmış yanıtın parçasıdır; zamanlama ve mekanizmaları farklıdır.'),
    s('Kazanılmış Bağışıklık ve Bağışıklık Hafızası', [96,97], [
      'p96’da humoral ve hücresel yanıtı, B ve T hücrelerinin iş bölümüyle oku. Antikorlarla etkili olan yol ile hedef hücrelere yönelik hücresel yanıt farklı mekanizmalar içerir. Her savunma hücresinin doğrudan antikor salgıladığı sonucuna gitme.',
      'p97’de birincil ve ikincil yanıt grafiğinde yatay eksen gün, düşey eksen kandaki antikor derişimidir. Aynı antijenle ikinci karşılaşmanın daha hızlı ve güçlü yanıt oluşturabilmesini bellek hücreleriyle ilişkilendir. Ardından aktif ve pasif bağışıklığı karşılaştır: hazır antikor almakla kendi özgül yanıtını geliştirmenin süre ve bellek sonuçları farklıdır. Grafikteki antikor artışını patojen sayısının aynı miktarda arttığı şeklinde okuma.'
    ], 'p97’de ilk/ikinci karşılaşma işaretlerini ve iki antikor eğrisini; ardından aktif/pasif başlıklarını karşılaştır.', 'Hazır antikor verilmesi neden aşıyla aynı bellek sonucunu zorunlu olarak oluşturmaz?', 'Hazır antikor pasif koruma sağlar. Aktif bağışıklıkta kişinin kendi özgül yanıtı ve bellek hücreleri gelişir; hazır antikorun bulunması tek başına bu sürecin gerçekleştiğini göstermez.')
  ]);

  guides['bio-tyt-02'].sections.push(s('Sağlıklı Beslenme', [44,45], [
    'Bileşikler bölümünü tamamladıktan sonra p44’te besin gruplarına geç. Süt, et-yumurta-kuru baklagil, sebze-meyve ve p45’teki ekmek-tahıl gruplarını tek bir molekül türüyle özdeşleştirme. Bir besin aynı anda protein, yağ, karbonhidrat, su, mineral ve vitaminlerden farklı miktarlarda içerebilir.',
    'Başlıktaki “Lipit, Karbonhidrat, Protein, Vitamin, Su ve Minerallerin Sağlıklı Beslenme ile İlişkisi” ifadesini, önceki sayfalardaki görevleri birlikte kullanarak açıkla. Beslenme çeşitliliği farklı gereksinimlerin karşılanmasına yardım eder. Enerji sağlama, yapı oluşturma ve düzenleme birbirini tamamlar; yalnız kalori miktarı bütün beslenme niteliğini açıklamaz. Kitabın grup örneklerini kişiye özel miktar reçetesi gibi kullanmadan, besin içeriği ile hücresel gereksinim arasındaki ilişki olarak oku.'
  ], 'p44–45’te dört besin grubunu ve Kritik Bilgi kutusunu önceki bileşik görevleriyle ilişkilendir.', 'Bir besinin protein grubunda örneklenmesi hiç yağ veya vitamin içermediğini gösterir mi?', 'Göstermez. Besin grupları öne çıkan içerik ve kullanım özelliklerine göre düzenlenir; gerçek bir besin birden çok bileşeni birlikte içerebilir.'));
  guides['bio-tyt-05'].sections.push(s('Bilimsel Yöntem ve Basamakları', [72], [
    'Kitabın madde geçişlerinden sonraki sayfasında bilimsel yöntem basamakları bulunur. Problem, gözlem, hipotez ve deney ilişkisini şemadaki sırayla oku. Hipotez yalnız bir tahmin cümlesi değil, gözlem ve deneyle sınanabilecek bir açıklamadır. Bir sonuç hipotezle uyuşmadığında açıklamanın gözden geçirilmesi gerekebilir.',
    'Taşıma konusundan bir deney düşünürken bağımsız değişkeni araştırmacının değiştirdiği etken, bağımlı değişkeni ölçülen sonuç olarak belirle. Diğer önemli koşulların sabit tutulması, sonucun hangi etkenden kaynaklandığını değerlendirmeyi kolaylaştırır. Kontrol grubu karşılaştırma sağlar. Bir deneyde iki koşulu aynı anda değiştirip bütün sonucu yalnız birine bağlamak güvenilir bir çıkarım değildir. Şemayı ezber adımlar yerine kanıtın açıklamayı nasıl denetlediği üzerinden oku.'
  ], 'Bilimsel Yöntem Basamakları şemasındaki hipotez–deney–sonuç bağlantılarını izle.', 'Osmoz deneyinde hem sıcaklığı hem çözelti derişimini değiştirirsen su geçişindeki farkı neden yalnız derişime bağlayamazsın?', 'İki etken birlikte değişmiştir. Sıcaklığın etkisini ayıran uygun karşılaştırma olmadan gözlenen farkın yalnız derişimden kaynaklandığı gösterilemez.'));
  guides['bio-tyt-06'].sections.push(
    s('Eşeysiz Üreme: Bölünme, Tomurcuklanma ve Rejenerasyon', [109,110], [
      'p109’da eşeysiz üremenin genel özelliklerini okurken tek ebeveyn ve gamet birleşmesi olmaması ölçütlerini ayır. Hücre bölünmesi eşeysiz üremeye katkı verebilir, ancak her mitoz yeni bir birey üretmez. Çok hücrelide büyüme ve onarım ile tek hücrelide birey sayısının artması farklı sonuçlardır.',
      'Bölünerek üremeden p110’daki tomurcuklanma ve rejenerasyona geç. Tomurcuğun gelişmesiyle yeni birey oluşmasını ve parçanın yeni bir organizmayı tamamlamasını örneklerden izle. Rejenerasyonun her durumda üreme olmadığını özellikle düşün: bir organın yenilenmesi birey sayısını artırmayabilir. Genetik benzerlik genel sonuç olsa da mutasyon olasılığı nedeniyle “hiçbir koşulda farklılık olmaz” genellemesi kurulmaz.'
    ], 'Bölünme, Tomurcuklanma ve Rejenerasyon çizimlerinde başlangıç ve son birey sayılarını karşılaştır.', 'Kertenkelenin kuyruğunu yenilemesi neden tek başına eşeysiz üreme sayılmaz?', 'Yeni bir birey oluşmamıştır; mevcut bireyin bir yapısı onarılmıştır. Rejenerasyonun üreme sayılması için birey sayısını artıran bir sonuç gerekir.'),
    s('Sporla Üreme, Partenogenez ve Vejetatif Üreme', [111,112,113], [
      'p111’de sporla üreme ve partenogenezi farklı başlangıç yapılarıyla oku. Spor ile gameti aynı hücre türü sayma; partenogenezde ise döllenmeden gelişme söz konusudur. Şemadaki mayoz ve mitoz etiketlerini hangi canlının hangi aşamasına ait olduklarını belirleyerek takip et; tek örneğin ploitlik sonucunu bütün türlere genelleme.',
      'p112–113’te stolon, yumru, rizom, çelik ve soğan örneklerinde kullanılan bitki organını bul. Doku kültürü de yeni bitkilerin elde edilmesine ilişkindir. Vejetatif üremenin avantajlarını hız ve istenen özelliklerin korunması üzerinden açıkla; buna karşılık düşük kalıtsal çeşitliliğin değişen çevrede sınırlılık oluşturabileceğini düşün. Aynı anaçtan elde edilen bireylerin aynı çevrede bulunması zorunlu değildir; genotip benzerliği fenotipin her koşulda özdeşliğini garanti etmez.'
    ], 'p111’de spor/partenogenez şemalarını, p112–113’te vejetatif organ örneklerini ve Doku Kültürü başlığını izle.', 'Çelikle üretilen iki bitkinin boylarının farklı olması neden genetik olarak farklı olduklarını kesinleştirmez?', 'Genetik olarak benzer bitkiler ışık, su ve besin gibi farklı çevre koşullarında farklı büyüyebilir. Fenotip yalnız genotipin değil çevrenin de etkisini taşır.')
  );
  guides['bio-tyt-08'].title = 'Kalıtım, Çaprazlamalar ve Genetik Varyasyonlar';
  guides['bio-tyt-08'].sections.push(
    s('Eş Baskınlık, Çok Alellilik ve Kan Gruplarının Kalıtımı', [132,133,134], [
      'p132’de eş baskınlık örneğini, heterozigot bireyde iki alelin etkisinin birlikte görülmesi üzerinden oku. Bu durum tam baskınlıktaki baskın fenotiple aynı model değildir. p133’te çok alellilik, popülasyonda bir gen için ikiden fazla alel bulunabilmesidir; diploit bir bireyin aynı lokusta bütün bu alelleri birden taşıdığı anlamına gelmez.',
      'ABO tablosunda fenotip, genotip, alyuvar antijeni ve plazma antikorunu yatay okuyarak eşleştir. AB heterozigotluğunu eş baskınlıkla, A ve B alellerinin 0 karşısındaki durumunu baskınlıkla açıkla. p134’te Rh uyuşmazlığını anne-bebek arasında uygun koşullarda gelişen bağışıklık etkileşimi olarak incele; bütün farklı kan gruplarını aynı mekanizma sayma. Genotipin kalıtımı ile antijen-antikor etkileşimi farklı açıklama basamaklarıdır.'
    ], 'Fenotip–Genotip–Antijen–Antikor tablosunu aynı satırda oku; ardından Rh Uyuşmazlığı açıklamasına geç.', 'Üç ABO aleli bulunması bir bireyin neden üç alel taşımadığını açıklar mısın?', 'Çok alellilik popülasyon düzeyindedir. Diploit birey bu lokusta anneden ve babadan birer alel alır; toplam iki alel taşır.'),
    s('Eşeye Bağlı Kalıtım ve Akraba Evliliği', [135,136,137,138,139], [
      'p135–136’da otozom ve gonozom ayrımını, vücut hücresi ile gamet kromozom formüllerinden oku. p137–138’de X’e bağlı örneklerde aleli X üzerinde göstererek çaprazlama kur. Erkek bireyde X üzerindeki bir alelin karşısında aynı lokusu taşıyan ikinci X bulunmaması, çekinik özelliğin ortaya çıkma olasılığını etkiler.',
      'Renk körlüğü ve hemofili örneklerini Y’ye bağlı modelle karıştırma. Babadan oğula doğrudan X aktarımı beklenmez; oğul X’i annesinden alır. p139’da akraba evliliğinin etkisini ortak çekinik alellerin bir araya gelme olasılığıyla ilişkilendir. Bu durum yeni bir zararlı alelin zorunlu olarak oluşması değildir; ailede bulunan alellerin homozigot durumda buluşma olasılığı artabilir.'
    ], 'X’e bağlı renk körlüğü/hemofili tablolarını ve Y’ye bağlı kalıtımı farklı geçiş yollarıyla oku.', 'X’e bağlı bir alel babadan oğula neden doğrudan aktarılmaz?', 'Baba oğluna Y kromozomunu verir; oğlun X kromozomu anneden gelir. Bu modelde babanın X üzerindeki aleli oğula doğrudan geçmez.'),
    s('Soyağacı Analizi ve Örnekleri', [140,141,142], [
      'p140’ta sembolleri öğrenmeden genotip atamaya başlama. Boyanmış birey hangi fenotipi gösteriyor, cinsiyet sembolleri neyi anlatıyor, kuşaklar nasıl bağlanıyor önce bunları belirle. Soyağacı bir akrabalık ve fenotip kaydıdır; bütün genotipler baştan yazılı değildir.',
      'p141–142’de otozomal ve gonozomal örnekleri aynı aile ilişkileri üzerinden sınayarak karşılaştır. Görünüşte sağlam iki ebeveynden etkilenmiş çocuk doğması, uygun modelde çekinik alel taşıyıcılığını düşündürür. Ancak tek bir örüntüden hemen kesin model seçmeden diğer bütün bireylerle tutarlılığı kontrol et. Bir varsayımın bir bireyde çelişmesi elenmesini gerektirebilir. Kan grubu örneğinde de fenotipten olası genotiplere geri dönerek çaprazlama mantığını kullan.'
    ], 'Sembol açıklamasını; p142’de Otozomal Baskın/Çekinik ve X’e Bağlı örnekleri aynı ölçütle karşılaştır.', 'Soyağacında yalnız bir ebeveyn-çocuk çiftine bakmak neden yeterli olmayabilir?', 'Birden fazla kalıtım modeli o çifti açıklayabilir. Modelin bütün ailedeki geçişlerle tutarlı olması gerekir; diğer bireyler olası modelleri ayırır.'),
    s('Genetik Varyasyonların Kaynakları ve Biyolojik Çeşitlilik', [143,144], [
      'p143’te çeşitlilik kaynaklarını yeni alel oluşması ve mevcut alellerin yeni birleşimleri olarak ayır. Mutasyon kalıtsal materyalde değişim oluşturabilir; mayozdaki parça değişimi, bağımsız dağılım ve rastgele döllenme ise mevcut bilgilerin farklı kombinasyonlarını meydana getirebilir.',
      'p144’te biyolojik çeşitlilik açıklamasını yalnız tür sayısına indirgeme. Aynı tür içindeki genetik farklılıklar, tür çeşitliliği ve farklı yaşam ortamları birlikte değerlendirilebilir. Çevrenin bireyde oluşturduğu her değişimin kalıtsal olduğunu söyleme. Genotip değişmeden de çevre fenotipi etkileyebilir. Kalıtsal çeşitlilik ile bireyin yaşamı boyunca gösterdiği değişimlerin ayrımı, canlılar ve çevre konusunun da temelidir.'
    ], 'Genetik varyasyon kaynaklarını ve p144 Biyolojik Çeşitlilik başlığındaki düzeyleri karşılaştır.', 'Krossing over ile mutasyon çeşitliliği aynı yolla mı oluşturur?', 'Hayır. Krossing over mevcut alellerin kromozom üzerindeki kombinasyonlarını değiştirebilir. Mutasyon kalıtsal materyalde değişim oluşturup yeni alellerin kaynağı olabilir.')
  );
  guides['bio-tyt-10'].title = 'Ekosistem Ekolojisi, Çevre Sorunları ve Biyolojik Çeşitliliğin Korunması';
  guides['bio-tyt-10'].sections.push(
    s('Hava Kirliliği, Asit Yağmurları ve Küresel İklim Değişikliği', [159,160], [
      'p159’da çevre sorunlarının nedenlerinden hava kirliliğine ilerle. Kirletici kaynağı ile ortaya çıkan etkiyi ayrı söyle. Bir maddenin atmosferde bulunmasıyla yoğunluğunun insan etkinlikleri sonucu değişmesi aynı durum değildir. Kaynakların azaltılması, yalnız oluşan etkiyi sonradan gidermeye çalışmaktan farklı bir müdahale basamağıdır.',
      'p160’ta asit yağmurları ile küresel iklim değişikliğini karşılaştır. İkisi atmosferle ilgili olsa da kimyasal süreçleri aynı değildir. Asit yağmurlarında suyla tepkime sonucu asitliği artıran maddeler, iklim değişikliğinde ise enerji dengesini etkileyen sera gazları önemlidir. Ozon tabakası, sera etkisi ve asit yağmurunu birbirinin adı gibi kullanma. Her örneği kaynak → ortamda dönüşüm → canlı/cansız çevre etkisi sırasıyla açıkla.'
    ], 'Hava Kirliliği, Asit Yağmurları ve Küresel İklim Değişikliği başlıklarını neden-sonuç olarak karşılaştır.', 'Asit yağmurları ile sera etkisini tek bir olay saymak neden yanlıştır?', 'Atmosferdeki maddeler ve etkiledikleri süreçler farklıdır. Biri yağışın kimyasal asitliğini, diğeri Dünya’nın enerji dengesini değiştiren mekanizmalarla ilişkilidir.'),
    s('Su, Toprak, Radyoaktif ve Ses Kirliliği', [161,162,163], [
      'p161’de su kirliliğini değerlendirirken suya giren madde ile ekosistemdeki dolaylı sonuçlarını birlikte oku. Besin maddelerinin aşırı artması üretimi ve ayrıştırmayı değiştirerek çözünmüş oksijen üzerinde sonuçlar doğurabilir. Suyun dışarıdan berrak görünmesi bütün kimyasal ve biyolojik koşulların uygun olduğunu göstermez.',
      'p162’de toprak ve radyoaktif kirlilik, p163’te ses kirliliği ayrı başlıklardır. Kirletici her zaman görünür bir çöp olmak zorunda değildir. Toprakta kalıcı maddeler besin ilişkilerine katılabilir; ses ise fiziksel bir çevre etkisidir. Bir çözüm önerirken hangi kirleticiye ve hangi aktarım yoluna müdahale edildiğini belirt. Her çevre sorunu için yalnız ağaç dikme gibi tek bir genel yanıt kullanma.'
    ], 'Dört kirlilik başlığında kirleticiyi, yayıldığı ortamı ve etkilediği canlı süreçleri ayrı belirle.', 'Suyun berrak olması neden içeriğinin ekolojik açıdan güvenli olduğunu kesinleştirmez?', 'Görünmeyen çözünmüş kimyasallar, mikroorganizmalar veya oksijen dengesindeki değişimler bulunabilir. Görünüş bütün çevresel ölçütleri temsil etmez.'),
    s('Erozyon, Habitat Tahribi ve Biyoçeşitliliğin Azalması', [164,165], [
      'p164’te erozyonu toprağın taşınmasıyla ilişkilendir. Bitki örtüsünün azalması toprağın korunmasını zayıflatabilir; bunun sonucu yalnız aynı yerdeki bitki sayısının düşmesi değildir. Toprak kaybı su ilişkilerini, verimliliği ve başka habitatları da etkileyebilir.',
      'Doğal yaşam alanlarının tahribi ve orman yangınlarından p165’te biyoçeşitliliğin azalmasına geç. Bir türün yaşadığı alanın parçalanması, bireylerin kaynaklara ve eşlere erişimini sınırlayabilir. Etkiyi yalnız tek bir bireyin ölümüyle sınırlandırma; popülasyon büyüklüğü ve türler arası ilişkiler de değişebilir. Önceki besin ağı bilgisini kullanarak bir türdeki azalmanın başka türlere nasıl dolaylı yansıyabileceğini açıklamaya çalış.'
    ], 'Erozyon ve Doğal Hayat Alanlarının Tahribi başlıklarını p165’te Biyoçeşitliliğin Azalması ile bağla.', 'Bir yaşam alanının parçalanması neden toplam alan aynı kalsa bile sorun yaratabilir?', 'Parçalar arasında geçiş zorlaşabilir, kaynak ve eşlere erişim azalabilir. Yaşam alanının bağlantılılığı, yalnız toplam yüzölçümü kadar önemli olabilir.'),
    s('Ekolojik, Karbon ve Su Ayak İzi; Çözüm Önerileri', [166,167], [
      'p166’da ekolojik ayak izi ile karbon ayak izini aynı ölçü sanma. Kullanılan kaynaklar ve ortaya çıkan atıklarla ilişkili baskıyı değerlendiren yaklaşım, sera gazı salımlarıyla ilgili ölçümden daha geniş veya farklı kapsam taşıyabilir. Her kavramın neyi saydığını açıklamadan yalnız “düşük olması iyidir” demek yetersizdir.',
      'p167’de su ayak izini doğrudan içtiğimiz su miktarından daha geniş düşün. Üretim süreçlerinde kullanılan su da tüketim tercihlerinin çevresel etkisine katılabilir. Çözüm önerilerini kaynak tüketimini azaltma, tekrar kullanma, geri dönüşüm ve kirliliği önleme basamaklarıyla ilişkilendir. Aynı ürünün atığını geri dönüştürmekle o ürünün gereksiz tüketimini baştan azaltmak farklı müdahalelerdir.'
    ], 'Ekolojik Ayak İzi, Karbon Ayak İzi ve Su Ayak İzi tanımlarını yan yana oku.', 'Bir ürünün su ayak izi neden yalnız ürünün içindeki su miktarı değildir?', 'Ürünün elde edilmesi ve üretiminde kullanılan su da değerlendirilir. Dolaylı su kullanımı, son üründe fiziksel olarak bulunan suyla aynı büyüklük değildir.'),
    s('Doğal Kaynakların Sürdürülebilirliği ve Biyolojik Çeşitliliğin Korunması', [168,169,170,171], [
      'p168–169’da kaynak kullanımını yenilenme ve uzun süreli gereksinimlerle birlikte oku. Yenilenebilir bir kaynak da yenilenme hızından daha hızlı tüketilirse baskı altında kalabilir. Sürdürülebilirlik, kaynağın bugün kullanılmasının yanında gelecekteki işlevini ve erişilebilirliğini korumayı gerektirir.',
      'p170’te endemik türlerin belirli alanlara özgülüğünü, p171’de soyu tükenen türler, biyokaçakçılık ve gen bankalarını incele. Gen bankasında materyal saklanması doğal yaşam alanlarının korunmasını gereksiz yapmaz; bunlar farklı koruma yollarıdır. Bir türün kaybı yalnız bir isim eksilmesi değil, genetik bilginin ve ekolojik ilişkilerin de kaybıdır. Kitabın son sayfasını çeşitliliğin oluşumu ile korunması arasındaki bağlantıyı kurarak tamamla.'
    ], 'Endemik türler, Biyokaçakçılık ve Gen Bankaları başlıklarını kaynakların korunmasıyla ilişkilendir.', 'Gen bankalarının bulunması doğal habitatları korumayı neden gereksiz yapmaz?', 'Gen bankası belirli kalıtsal materyali saklar; canlıların doğal etkileşimlerini, yaşam alanlarını ve bütün ekosistem süreçlerini tek başına korumaz. Yerinde koruma farklı bir gereksinimi karşılar.')
  );

  add('bio-ayt-07', 'Solunum Sistemi ve Üriner Sistem', 'AYT-bio', '98–119. sayfalarda hava ve kanın yolunu, ardından böbrekte kan-süzüntü ilişkisini kitabın çizimleriyle okuyacağız.', [
    s('Solunum Sisteminin Genel Yapısı ve Organları', [98,99,100], [
      'p98’de sistemin genel görevinden organ haritasına geç. Burun, yutak, gırtlak, soluk borusu ve akciğerler boyunca hava yolunu izle. Havanın bir kanaldan geçmesiyle gazın solunum yüzeyinden kana geçmesi aynı basamak değildir. Her yapı gaz alışverişini aynı ölçüde gerçekleştirmez.',
      'p99–100’de havanın temizlenmesi, ısıtılması ve nemlendirilmesi gibi görevleri yapı özelliklerine bağla. Soluk borusunun destek yapısıyla akciğer içindeki dallanmayı ayır. Dallanma sonunda geniş toplam yüzey elde edilmesi, çok sayıdaki küçük alışveriş biriminin birlikte çalışmasını sağlar. Akciğerin hava ile dolması, kanın akciğer dokusunun içinde serbestçe havayla karıştığı anlamına gelmez; iki ortam uygun sınırlar üzerinden alışveriş yapar.'
    ], 'Hava yolunu organ adlarıyla takip et; soluk borusu ve akciğerin yapı açıklamalarını karşılaştır.', 'Soluk borusundan hava geçmesi neden burada esas gaz alışverişi yapıldığı anlamına gelmez?', 'İletim yolu ile alışveriş yüzeyi farklı yapılardır. Esas alışveriş, geniş yüzey ve ince sınır sağlayan alveol-kılcal düzeninde gerçekleşir.'),
    s('Alveoller, Soluk Alıp Verme Mekanizması ve Kontrolü', [101,102,103], [
      'p101’de alveolleri çevreleyen kılcalları ve sürfaktan açıklamasını oku. İnce yüzey ve geniş toplam alan gaz difüzyonuna uygundur. Sürfaktanın yüzey gerilimiyle ilişkisi alveollerin açık kalmasına katkı verir. Bu işlev, oksijeni doğrudan hemoglobine taşıyan bir pompa gibi düşünülmez.',
      'Soluk alma ve verme çizimlerinde diyaframın konumu, göğüs hacmi ve basıncı sırayla değerlendir. Hacim değişimi basınç farkı oluşturur; hava bu farkla hareket eder. p103’te kontrol bölümünde kanın kimyasal koşullarının soluk düzenini etkileyebilmesini incele. Hava akışı bir basınç olayı, alveol-kan gaz geçişi ise kısmi basınç farkıyla difüzyondur; aynı mekanizma diye anlatma.'
    ], 'p101–102’de diyafram/hacim/basınç sırasını, p103’te kontrol açıklamasını takip et.', 'Soluk almada akciğer hacmi artarken hava neden içeri girer?', 'Göğüs ve akciğer hacmindeki artış içerideki basıncın dış havaya göre düşmesine yol açar. Hava oluşan basınç farkı yönünde içeri hareket eder.'),
    s('Solunum Gazlarının Taşınması ve Hemoglobin', [104,105,106], [
      'p104’te Hb + O2 ve HbO2 ifadelerini akciğer ve doku kılcalları etiketleriyle birlikte oku. Oksijenin bağlanması ve ayrılması çevrenin koşullarına bağlıdır. Hemoglobin bütün yol boyunca oksijeni hiç bırakmadan taşıyan kapalı bir kap değildir; dokularda bırakması işlevin parçasıdır.',
      'p105’te pH’a bağlı eğrileri aynı oksijen basıncında karşılaştır. Düşey eksende neyin ölçüldüğünü kontrol ederek düşük pH koşulunun oksijen bırakmayla ilişkisini açıkla. CO2 taşınmasında ise çözünmüş, hemoglobine bağlı ve bikarbonatla ilişkili yolları ayır. Karbonik anhidrazlı tepkimeyi doku ve akciğer yönlerinde oku. Tek bir tepkimeyi bütün CO2 taşınmasının tek biçimi gibi kullanma.'
    ], 'p104’te bağlanma/ayrılma denklemlerini, p105’te farklı pH eğrilerini ve p106’daki dönüş yönünü izle.', 'Aktif dokuda oluşan koşulların hemoglobinden oksijen ayrılmasını kolaylaştırması neden işlevseldir?', 'Oksijen gereksinimi yüksek dokuların metabolik koşulları oksijenin bırakılmasını destekleyebilir. Böylece taşınan oksijen gereksinim duyulan hücrelere aktarılır.'),
    s('Solunum Sistemi Hastalıkları ve Sağlıklı Yapının Korunması', [107,108], [
      'Bu sayfalarda amfizem, verem ve diğer örnekleri önce etkiledikleri yapı üzerinden oku. Alveol yüzeyinin veya esnekliğinin değişmesiyle, enfeksiyonla ortaya çıkan bozulma aynı mekanizma değildir. Farklı hastalıklar benzer solunum güçlüğü oluşturabilir; benzer belirti aynı nedene sahip olduklarını göstermez.',
      'Koruma açıklamalarını solunum yolunun temizleme düzeni ve alveollerin alışveriş yüzeyiyle ilişkilendir. Solunum sisteminin sağlığı yalnız içeri giren oksijen miktarına bağlı değildir; yüzeyin yapısı, hava yolunun açıklığı ve dokuların durumu da önemlidir. Kitaptaki örnekler normal yapı-görev ilişkisini anlamak içindir. Bir hastalığın adını tek belirtiyle eşleştirmek yerine hangi basamağın aksadığını söyle.'
    ], 'Rahatsızlık adlarını alveol, hava yolu ve alışveriş göreviyle eşleştir; p108’de korunma başlığını oku.', 'Alveol yüzeyinin azalması neden gaz alışverişini etkileyebilir?', 'Difüzyon için kullanılabilir toplam yüzey azalır. Hava akciğere ulaşsa bile kanla gaz alışverişinin kapasitesi düşebilir.'),
    s('Üriner Sistemin Görevleri, Organları ve Nefronun Yapısı', [109,110,111,112], [
      'p109’da üriner sistemin görevlerini su, iyon, asit-baz ve atık uzaklaştırma başlıklarıyla ilişkilendir. p110’da böbrek, üreter, idrar kesesi ve üretrayı sıralarken idrarın oluşturulduğu yerle taşındığı/depolandığı yapıları ayır. Üreter ile üretra aynı kanal değildir.',
      'p111’de nefron çizimini iki farklı yol olarak oku: kanın izlediği damar yolu ve süzüntünün tüplerde izlediği yol. Glomerulus ile Bowman kapsülü komşudur ama biri damar ağı, diğeri süzüntünün toplandığı yapıdır. p112’de glomerulus kılcallarının özelliklerini diğer kılcallarla karşılaştır. Kan ve süzüntü arasındaki geçiş, bütün kanın damar dışına boşalması anlamına gelmez; hücre ve büyük moleküllerin durumu farklıdır.'
    ], 'Organ haritasından nefrona geç; kan damarları ve nefron tüpünün yollarını farklı renk/etiketlerden takip et.', 'Süzüntünün Bowman kapsülünde oluşması kan hücrelerinin de normalde buraya geçtiği anlamına gelir mi?', 'Hayır. Süzülme sınırı seçici davranır; kan hücreleri ve büyük plazma proteinleri normal koşullarda kan tarafında kalır. Süzüntü kanın tamamıyla aynı içerikte değildir.'),
    s('İdrar Oluşumu: Süzülme, Geri Emilim ve Salgılama', [113,114,115,116], [
      'p113’te üç işlemin ok yönlerini ayrı oku. Süzülmede kan tarafındaki bazı maddeler kapsüle geçer. Geri emilimde tüp içindeki madde kana döner. Salgılamada ise kandan tüpe ek madde verilir. Aynı maddenin birden fazla süreçte yer alabilmesi mümkündür.',
      'p114–115’te geri emilim ve salgılama ayrıntılarını bu ok düzenine yerleştir. Bir maddenin süzülmesi, son idrarda kesin bulunacağı anlamına gelmez; geri alınabilir. p116’daki miktar açıklamalarında son idrara katılan miktarı süzülen eksi geri emilen artı salgılanan olarak düşün. Suyun geri emilmesi derişimi de değiştirir; derişim artışını her zaman o maddenin toplam miktarının arttığı diye yorumlama.'
    ], 'Süzülme/Geri emilim/Salgılama oklarının hangi ortamdan hangi ortama yöneldiğini p113’te belirle.', 'Süzülen glikozun normal son idrarda çok az bulunması veya bulunmaması nasıl mümkündür?', 'Süzüntüye geçmiş glikoz nefron boyunca geri emilebilir. Süzülme başlangıç geçişidir; son idrar içeriği sonraki geri emilim ve salgılamayla belirlenir.'),
    s('Homeostazide Böbreklerin Rolü ve Üriner Sistem Rahatsızlıkları', [117,118,119], [
      'p117’de su dengesi ve asit-baz açıklamalarını, nefronda geri emilimle ilişkilendir. ADH’nin etkisiyle belirli bölümlerin su geçirgenliğinin değişmesi, kana dönen su miktarını ve son idrarın hacim/derişimini etkiler. Hormonun böbrekte etki etmesi, böbrekte üretildiği anlamına gelmez.',
      'p118–119’da taş, enfeksiyon, yetmezlik ve diyaliz gibi örnekleri farklı işlev bozuklukları olarak oku. Diyaliz belirli atıkların ve su/iyon dengesinin düzenlenmesine yardım eder; sağlıklı böbreğin bütün düzenleyici işlevlerini tek başına aynı biçimde yerine getirmez. Koruma açıklamalarını normal süzülme ve geri emilim süreçleriyle bağla. Böylece sistemin yalnız atık torbası değil, iç ortamı düzenleyen bir yapı olduğunu görürsün.'
    ], 'p117’de ADH/su dengesi açıklamasını; p119’da Diyaliz ve Böbrek Nakli başlığını incele.', 'ADH etkisiyle su geri emilimi artarsa idrarın hacmi ve derişimi hangi yönde değişebilir?', 'Diğer koşullar aynıysa daha fazla su kana döner; idrar hacmi azalırken kalan maddelerin derişimi artabilir. Madde miktarı ile su miktarının ayrı değerlendirilmesi gerekir.')
  ]);

  add('bio-ayt-08', 'Üreme Sistemi ve Embriyonik Gelişim', 'AYT-bio', '120–134. sayfalarda gametlerin oluşumu, hormon döngüleri, döllenme ve gelişimi kitabın çizim sırasıyla okuyacağız.', [
    s('Erkek Üreme Sistemi, Spermatogenez ve Hormonal Kontrol', [120,121,122], [
      'p120’de sperm üretim yeri ile spermin taşındığı kanalları ayır. Yardımcı bezlerin salgılarıyla sperm hücresinin kendisi aynı yapı değildir. p121’de spermatogenez çiziminde mitoz, mayoz ve farklılaşma basamaklarını ayrı takip et. Sayı azalması mayozla, hareket edebilen sperm biçiminin kazanılması farklılaşmayla ilişkilidir.',
      'p122’de hipotalamus–hipofiz–testis bağlantısını okların yönüne göre oku. FSH ve LH’nin farklı hücresel hedefleri; testosteron ve inhibinin geri bildirim rolleri vardır. Hormonlar yalnız ileri doğru bir üretim zinciri oluşturmaz; son ürünler önceki merkezlerin etkinliğini sınırlar. Çizimde bütün okların uyarıcı olmadığını fark etmek, negatif geri bildirimi mekanizma üzerinden öğrenmeni sağlar.'
    ], 'Spermatogenez basamaklarını ve p122’de GnRH, FSH, LH, testosteron/inhibin geri oklarını izle.', 'Spermin haploit olmasıyla kuyruk kazanması neden aynı olay değildir?', 'Haploitlik mayozla kromozom takımının azalmasıdır. Kuyruk ve diğer biçim özellikleri hücrenin farklılaşmasıyla kazanılır; iki süreç ayrı basamaklardır.'),
    s('Dişi Üreme Sistemi ve Oogenez', [123,124], [
      'p123’te yumurtalık, yumurta kanalı ve rahmi çizimde bul. Yumurtanın oluşturulduğu yer, döllenmenin gerçekleştiği yer ve embriyonun yerleştiği yer farklıdır. Bu konumları tek bir “üreme organı” adı altında birleştirmek döllenme ve gelişim sırasını karıştırır.',
      'p124’te oogenez çizimini zaman etiketleriyle oku. Birincil oositin profaz I’de, ikincil oositin metafaz II’de duraklaması ve döllenmeyle ikinci bölünmenin tamamlanması gösterilir. Kutup hücrelerini oluşan büyük hücreyle aynı sitoplazma miktarında sayma. Mayozun genetik paylaşımı ile sitoplazmanın eşit bölünmesi aynı koşul değildir. Folikül gelişimi ve oositin mayoz durumu ilişkili olsa da aynı yapının iki farklı adı değildir.'
    ], 'p124’te Doğumdan önce/Ergenlikten menopoza zaman etiketlerini ve Profaz I/Metafaz II duraklamalarını izle.', 'Oogenezde mayoz ürünlerinin eşit büyüklükte olmaması kromozom paylaşımının gerçekleşmediğini mi gösterir?', 'Hayır. Kromozomların dağıtımı ile sitoplazmanın miktar olarak paylaşımı farklıdır. Kutup hücreleri az sitoplazma alırken büyük üreme hücresi daha çok sitoplazmayı korur.'),
    s('Menstrual Döngü ve Dişi Üreme Sisteminin Hormonal Kontrolü', [125,126,127], [
      'p125’te grafiği yukarıdan aşağıya okurken aynı gün çizgisini takip et. Hipofiz hormonları, yumurtalık hormonları, folikül/korpus luteum ve rahim iç yüzeyindeki değişimler aynı zaman ekseninde gösterilir. Böylece bir hormon yükselmesinin hangi yumurtalık ve rahim olayıyla ilişkili olduğunu görebilirsin.',
      'p126’daki açıklamalarla folikül, ovulasyon ve luteal evreleri grafiğe yerleştir. p127’de geri bildirim oklarını incele: döngünün her anında bütün hormonların birbirini aynı yönde etkilediğini varsayma. Uygun dönemde östrojenin pozitif geri bildirimle LH artışına katkısı, diğer dönemlerdeki negatif geri bildirimden farklıdır. Kanama, ovulasyon ve hormonal tepe aynı olay değildir; zamanlarını ayrı belirle.'
    ], 'p125’te tek bir günü tüm grafik satırları boyunca izle; p127’de Pozitif/Negatif geri bildirim oklarını karşılaştır.', 'LH tepesini grafikte görmek hangi olayla ilişkilendirilir ve neden tek başına kanamayla eşitlenmez?', 'LH yükselmesi ovulasyonla yakından ilişkilidir. Menstruasyon farklı bir evrede rahim iç tabakasındaki değişimdir; ortak zaman ekseni bu olayların farklı zamanlarını gösterir.'),
    s('Döllenme ve Üreme Sisteminin Sağlıklı Yapısının Korunması', [128,129], [
      'p128’de sperm ile ikincil oositin etkileşmesinden zigot oluşumuna kadar sırayı oku. Döllenmede iki haploit genetik katkının birleşmesi diploit durumu kurar. Bu, gelişimin daha sonraki bütün özelliklerinin o anda görünür hâle geldiği anlamına gelmez; hücre bölünmeleri ve farklılaşma ileride gerçekleşir.',
      'p129’daki yardımcı üreme uygulaması çiziminde gametlerin elde edilmesi, zigot/embriyo gelişimi ve transferi birbirinden ayır. Yöntemin değişmesi döllenme ile mitoz arasındaki temel farkı ortadan kaldırmaz. Sağlığı koruma bölümünü de normal organ ve süreçlerle ilişkilendir. Tıbbi uygulama örneklerini tek tip sonuç garantisi gibi okumadan, hangi basamağa yardım edildiğini kavramaya çalış.'
    ], 'p128’de çekirdek birleşimine; p129’da gamet–zigot–embriyo transferi sırasına bak.', 'Zigotun diploit olması neden ilk mitozdan önce kurulur?', 'Diploit takım, döllenmede iki haploit genetik katkının birleşmesiyle oluşur. Sonraki mitozlar bu bilgiyi eşleyip hücrelere dağıtır; diploitliği ilk kez oluşturan işlem değildir.'),
    s('Segmentasyon, Gastrulasyon, Organogenez ve Plasenta', [130,131,132], [
      'p130–131’de zigot, iki/dört hücreli evre, morula ve blastosist sırasını takip et. İlk bölünmelerde hücre sayısı artarken başlangıçtaki büyük hücrenin sitoplazması daha küçük blastomerlere paylaşılır. Bu nedenle hücre sayısının artması bütün embriyonun aynı oranda büyüdüğü anlamına gelmez.',
      'p131’de ekstraembriyonik zarların görev tablosunu oku; p132’de gastrulasyonla oluşan tabakaları ve organogenezi izleyerek farklılaşmaya geç. Plasenta ve göbek bağı açıklamasında anne ile embriyo arasındaki madde alışverişini, kanların doğrudan aynı damar boşluğunda karışması olarak düşünme. Maddelerin bir sınır üzerinden geçmesi ile iki dolaşımın bütünüyle birleşmesi farklı durumlardır. Bölünme, hücrelerin yer değiştirmesi ve görev kazanması gelişimin ayrı yönleridir.'
    ], 'Morula/Blastosist çizimleri, Ekstraembriyonik Zarlar tablosu ve p132’de Ektoderm/Mezoderm/Endoderm etiketlerini izle.', 'Segmentasyonda hücre sayısı arttığı hâlde embriyonun başlangıç hacmi neden çok artmayabilir?', 'Başlangıçtaki sitoplazma art arda bölünmelerle daha küçük hücrelere paylaşılır. Hücre sayısı artışı ile toplam biyokütle/hacim artışı aynı süreç değildir.'),
    s('Embriyonik ve Fetal Dönem; Gelişimi Etkileyen Faktörler', [133,134], [
      'p133’te embriyonik ve fetal dönem ayrımını gelişimin hangi yönünün öne çıktığıyla oku. Organ taslaklarının oluşması ile oluşmuş yapıların büyüyüp olgunlaşması farklı süreçlerdir. Gelişimin her günü aynı etkilere aynı duyarlılıkta olmak zorunda değildir.',
      'p134’te olumsuz etkenler ve izleme açıklamalarını, gelişmekte olan organların gereksinimleriyle ilişkilendir. Madde alışverişi ve hormonal düzenleme embriyonun çevreyle ilişkisini mümkün kılar; bu ilişki bütün zararlı etkenlerden tam koruma anlamına gelmez. Kitabın örneklerini bireysel risk hesabı yerine gelişimin biyolojik düzenini anlamak için kullan. İzlemenin amacı anne ve bebeğin durumuna ilişkin bilgi edinmek ve gerektiğinde uygun değerlendirmeyi sağlamaktır.'
    ], 'Embriyonik Dönem/Fetal Dönem başlıklarını ve p134’te gelişimi olumsuz etkileyen faktörleri karşılaştır.', 'Bir etkenin gelişimin farklı dönemlerinde farklı sonuç oluşturabilmesi nasıl açıklanır?', 'Farklı dönemlerde farklı yapılar oluşur veya olgunlaşır. Etkenin zamanı, hedef dokunun o andaki gelişim durumuyla birlikte sonucu etkileyebilir.')
  ]);

  add('bio-ayt-09', 'Komünite ve Popülasyon Ekolojisi', 'AYT-bio', '135–148. sayfalarda etkileşim tabloları, rekabet/av-avcı grafikleri, büyüme ve yaş dağılımlarını okuyacağız.', [
    s('Komünitenin Yapısına Etki Eden Faktörler ve Ekolojik Niş', [135,136], [
      'Komüniteyi farklı tür popülasyonlarının aynı alandaki ilişkileriyle tanımla. p135’te tür çeşitliliği ve dağılımını etkileyen koşulları, p136’da habitat ve ekolojik nişi oku. Aynı habitatı paylaşmak aynı nişe sahip olmak demek değildir; kaynakların kullanım biçimi ve zamanları farklı olabilir.',
      'Baskın tür açıklamasında birey sayısı, biyokütle veya ekolojik etki gibi ölçütleri bağlamına göre değerlendir. En büyük vücuda sahip bireyin türü her durumda baskın değildir. Komünite yapısı yalnız bir türün özelliğinden oluşmaz; cansız koşullar ve türler arası ilişkiler birlikte rol alır. Bu başlangıç sayfaları, sonraki rekabet ve simbiyoz örneklerinin hangi düzeyde incelendiğini belirler.'
    ], 'Habitat, ekolojik niş ve baskın tür açıklamalarını farklı sorulara yanıt veren kavramlar olarak oku.', 'Aynı gölde yaşayan iki türün aynı nişi paylaşması zorunlu mudur?', 'Değildir. Farklı besinleri, derinlikleri veya zamanları kullanabilirler. Habitat ortaklığı bütün kaynak kullanımının aynı olduğu anlamına gelmez.'),
    s('Komünitede Rekabet', [137,138], [
      'p137’de ilişki tablosunun artı, eksi ve sıfır işaretlerini tarafların yarar/zarar durumları olarak oku. Rekabette ortak sınırlı kaynağın kullanılması iki taraf üzerinde de maliyet oluşturabilir. Aynı alanda yaşamak tek başına rekabet kanıtı değildir; ortak kaynağın sınırlılığı önem taşır.',
      'p138’de P. aurelia ve P. caudatum grafiklerini karşılaştır. Türlerin ayrı ve birlikte bulunduğu koşullardaki büyümeyi izleyerek yalnız son günün birey sayısını değil zaman içindeki değişimi değerlendir. Kontrol koşulu olmadan bir türün azalmasını diğer türün etkisine bağlamak daha zayıf olur. Deney, belirli koşullarda benzer nişlerin rekabet sonuçlarını gösterir; her ekosistemde bütün tür çiftlerinin mutlaka aynı sonuçla karşılaşacağını söylemez.'
    ], 'p137’de ilişki işaretlerini; p138’de iki Paramesyum türünün ayrı/birlikte büyüme eğrilerini karşılaştır.', 'Bir türün diğerinin yanında azalmasını yorumlarken ayrı yetiştirildiği grafiğe neden bakılır?', 'Karşılaştırma, azalmanın yalnız ortamın genel koşullarından mı yoksa birlikte bulunmanın etkisinden mi kaynaklanabileceğini ayırmaya yardım eder.'),
    s('Av-Avcı İlişkisi', [139], [
      'Vaşak ve tavşan sayılarının zamana bağlı grafiğinde önce iki eğrinin tepe zamanlarını karşılaştır. Avın artması avcı için besin artışı sağlayabilir; avcı sayısındaki değişim aynı anda ve aynı büyüklükte olmak zorunda değildir. Zaman gecikmesi ilişkiyi yorumlarken önemlidir.',
      'Avcı arttığında av üzerindeki baskının artması, av azaldığında avcı için besin kısıtının oluşması karşılıklı etkileşimi açıklar. Ancak gerçek popülasyonları yalnız bu iki değişken belirlemez; hastalık, iklim ve diğer besin kaynakları da etkili olabilir. Grafikte bir eğrinin yükselmesini diğer eğrinin bütün zamanlarda zorunlu olarak aynı yönde değişeceği bir kural gibi okuma. Dönemsel dalgalanmanın mekanizmasını okların yerine zaman sırasıyla anlat.'
    ], 'Vaşak/Tavşan eğrilerinin artış, tepe ve azalış zamanlarını aynı yatay eksende karşılaştır.', 'Avcı sayısının tepesinin av sayısından sonra gelmesi nasıl açıklanabilir?', 'Av artışı avcıların beslenme ve üremesini destekleyebilir; avcı popülasyonunun yanıtı zaman alır. Bu yüzden iki eğrinin tepeleri gecikmeli görünebilir.'),
    s('Simbiyotik İlişkiler ve Süksesyon', [140,141,142,143], [
      'p140–142’de amensalizm, mutualizm, kommensalizm ve parazitizmi iki tarafın sonucuna göre karşılaştır. Artı işareti yararı, eksi zararı, sıfır belirgin etkilenmeme durumunu temsil eder. Bir canlının diğerinin yakınında bulunması ilişkinin adını tek başına belirlemez; kaynak aktarımı ve sonuç bilinmelidir.',
      'p143’te süksesyon başlığına geçince konu aynı iki türün günlük ilişkisi olmaktan çıkar, komünitenin zaman içindeki değişimine dönüşür. Önceki türlerin çevreyi değiştirmesi sonraki türlerin yerleşmesini etkileyebilir. Başlangıç koşulları birincil ve ikincil süreçlerde farklıdır. Son durumu her zaman hiç değişmeyen, dış etkilerden bağımsız bir topluluk gibi düşünme; ekosistemler çevresel değişim ve bozulmalara yanıt verir.'
    ], 'Simbiyoz örneklerinde iki tarafın işaretlerini; ardından p143’te süksesyon sırasını izle.', 'Parazitizm ile avcılık ikisinde de bir taraf yararlıysa neden aynı ilişki değildir?', 'Yarar/zarar işareti genel sonucu gösterir; ilişkinin biçimi ve sürekliliği farklıdır. Parazit konakla belirli bir yaşam ilişkisi sürdürürken avcılıkta avın tüketilmesi öne çıkar.'),
    s('Popülasyon Yoğunluğu, Dağılımı ve Büyüklüğü', [144,145], [
      'p144’te yoğunluğu belirli alan veya hacimdeki birey sayısı olarak oku. Toplam birey sayısı ile yoğunluk aynı değildir; alan büyüklüğü değişirse aynı sayıda bireyin yoğunluğu değişebilir. Kümeli, düzenli ve rastgele dağılım çizimleri ise bireylerin mekânsal düzenini gösterir.',
      'p145’te büyüklük değişimini doğum ve içe göçün eklenmesi, ölüm ve dışa göçün çıkarılmasıyla düşün. Çok doğum olması popülasyonun kesin büyüdüğünü göstermez; kayıplar daha fazla olabilir. Dağılım şekliyle zaman içindeki büyüme eğrisini de karıştırma. Biri mekânda konumları, diğeri sayıların zamana bağlı değişimini anlatır; eksenler ve çizimin amacı farklıdır.'
    ], 'Kümeli/Düzenli/Rastgele dağılım çizimlerini ve popülasyon büyüklüğü bilançosunu ayrı oku.', 'Doğum sayısı artan bir popülasyon hangi durumda yine küçülebilir?', 'Ölüm ve dışa göç toplamı, doğum ve içe göç toplamından büyükse net birey kaybı olur. Yalnız doğuma bakmak yeterli değildir.'),
    s('Hayatta Kalma Eğrileri, Taşıma Kapasitesi ve Yaş Dağılımı', [146,147,148], [
      'p146’da Tip I, II ve III eğrilerinde düşey eksenin hayatta kalan birey sayısını, yatay eksenin yaşam süresini gösterdiğini belirle. Eğriler belirli yaşlarda ölüm olasılığının dağılımını karşılaştırır; doğrudan popülasyonun yıllara göre büyüme grafikleri değildir. Logaritmik ekseni eşit aralıklı normal sayı çizgisi gibi okuma.',
      'p147’de taşıma kapasitesini kaynak ve çevre koşullarıyla ilişkilendir. Kapasite, bütün zamanlarda değişmez bir tavan olmak zorunda değildir. Yaş dağılımı şekillerinde üreme öncesi, üreme ve üreme sonrası grupların göreli büyüklüğünü değerlendir; gelecek büyüme eğilimi hakkında bilgi verebilirler. Yalnız bugünkü toplam birey sayısı gelecekteki değişimi belirlemek için yeterli değildir.'
    ], 'p146’da Tip I–II–III eğrilerini, p147–148’de taşıma kapasitesi ve yaş dağılımı çizimlerini farklı eksenlerle oku.', 'Aynı toplam birey sayısına sahip iki popülasyon neden farklı büyüme eğilimi gösterebilir?', 'Yaş dağılımları, doğum-ölüm oranları, göç ve çevre koşulları farklı olabilir. Üreme çağına yaklaşan birey oranı gibi bilgiler toplam sayıdan bağımsız ek bilgi sağlar.')
  ]);

  add('bio-ayt-10', 'Nükleik Asitler, Protein Sentezi ve Biyoteknoloji', 'AYT-bio', '149–171. sayfalarda keşif deneylerinden DNA/RNA’ya, bilgi akışına ve biyoteknoloji uygulamalarına ilerleyeceğiz.', [
    s('Nükleik Asitlerin Keşif Süreci ve Nükleotitlerin Yapısı', [149,150,151,152,153], [
      'Keşif bölümündeki deneyleri okurken uygulama, gözlem ve çıkarımı ayır. Bakterilerde dönüşüm gözlenmesi kalıtsal bilginin aktarılabildiğine kanıt verir; aktarıcı maddenin kimyasal kimliğinin belirlenmesi için farklı deney düzenekleri gerekir. Bir deneyin gösterdiğinden daha geniş bir iddiayı onun sonucuymuş gibi yazma.',
      'Deneylerde kontrol gruplarının neyi dışladığını düşün. Isıyla öldürülmüş örnek veya belirli molekülleri parçalayan uygulama, sonucun hangi bileşenle ilişkili olduğunu sınar. Nükleotit yapısına geçtiğinde baz, şeker ve fosfatı bul. Azotlu baz ile bütün nükleotit aynı şey değildir. DNA/RNA ayrımında şeker farkı ve baz çeşitleri, kalıtsal bilgi taşıyan molekülün kimyasal temelini kurar.'
    ], 'Keşif deneylerinde işlem ve sonuçları; nükleotit çiziminde üç bileşeni ayrı ayrı belirle.', 'Dönüşüm gözlenmesi tek başına aktarılan maddenin kesin DNA olduğunu gösterir mi?', 'Tek başına göstermez. Dönüşüm kalıtsal bilginin aktarımını destekler; maddenin kimliğini ayırmak için DNA ve diğer bileşenleri hedefleyen ek deneyler gerekir.'),
    s('DNA, RNA Çeşitleri ve Genetik Materyalin Organizasyonu', [154,155,156,157], [
      'p154–155’te DNA’nın iki zinciri ve tamamlayıcı bazları arasındaki düzeni incele. Zincir omurgasındaki fosfodiester bağlarıyla karşılıklı bazlar arasındaki hidrojen bağları farklı konumdadır. GC oranı aynı uzunluktaki DNA’nın bazı özelliklerini etkileyebilir; ancak omurga bağlarının sayısını baz türüne göre artırmaz.',
      'p156’da rRNA, mRNA ve tRNA’yı çizimleriyle oku. tRNA’daki antikodon ve amino asit bağlanma bölgesi farklı görevler taşır; rRNA ribozomun yapısal/işlevsel bileşenidir. p157’de nükleotitten kromatine ve kromozoma ilerleyen paketlenmeyi izle. DNA’nın sıkı paketlenmesi baz dizisinin başka bir molekül dizisine dönüştüğü anlamına gelmez; aynı bilginin hücre içinde düzenlenme biçimidir.'
    ], 'p156’da Antikodon bölgesi ve amino asit bağlanma yerini; p157’de Nükleozom–Kromatin–Kromozom sırasını takip et.', 'tRNA’nın ribozomda görev yapması neden ribozomun kalıcı yapısal bileşeninin tRNA olduğunu göstermez?', 'Bir yapıda geçici görev yapmak o yapının kalıcı bileşeni olmakla aynı değildir. tRNA amino asit taşır ve kodonla eşleşir; ribozomun RNA bileşeni rRNA’dır.'),
    s('DNA’nın Kendini Eşlemesi ve Enzim–Görev Tablosu', [158,159,160], [
      'p158’de yarı korunumlu eşlenme çiziminde eski ve yeni zincirleri renklerinden takip et. Her yeni DNA’nın bir eski, bir yeni zincir taşıması ana fikirdir. Eski DNA’nın bütünüyle korunup yanına tamamen yeni iki zincirli DNA kurulması farklı ve bu çizimle uyuşmayan bir modeldir.',
      'p159’da prokaryot ve ökaryot eşlenmesini başlangıç noktaları ve hücresel konum bakımından karşılaştır. p160’taki Enzim–Görevi tablosunda helikazın açma, DNA polimerazın yeni zinciri sentezleme ve ligazın parçaları birleştirme işlerini ayır. Aynı süreçte çalışmaları aynı bağa aynı etkiyi yaptıklarını göstermez. Birden çok başlangıç noktası toplam eşlenmeyi hızlandırabilir; bu sonuç tek polimerazın mutlaka daha hızlı çalıştığını kanıtlamaz.'
    ], 'Eski/yeni zincir renklerini ve p160’ta Helikaz–DNA Polimeraz–DNA Ligaz satırlarını karşılaştır.', 'Bir DNA daha kısa sürede eşleniyorsa polimerazın birim zamandaki ekleme hızının kesin arttığı söylenir mi?', 'Söylenemez. Daha çok başlangıç noktasında eşzamanlı çalışma toplam süreyi azaltabilir. Toplam süre ile tek enzimin çalışma hızı ayrı büyüklüklerdir.'),
    s('Genetik Şifre ve Protein Sentezinde Genetik Bilgi Akışı', [161], [
      'Bilgi akışı şemasında DNA, RNA ve protein arasında hangi okun hangi olaya karşılık geldiğini söyle. DNA’daki bilginin RNA’ya aktarılması transkripsiyon, mRNA bilgisinin amino asit dizisine çevrilmesi translasyondur. DNA’nın kendini eşlemesi ise bilginin kopyalanmasıdır; bu üç işlem aynı ürünleri oluşturmaz.',
      'Kodon kavramını üç nükleotitlik birim olarak oku. Bir kodon bir amino asidi belirtebilir veya sonlandırma işareti olabilir. Aynı amino asit için birden çok kodon bulunabilmesi, tek kodonun aynı anda rastgele birçok amino asidi belirttiği anlamına gelmez. Dil benzetmesini kullanırsan nükleotit dizisinin başka bir kimyasal diziyi belirlediğini vurgula; DNA’nın doğrudan proteine dönüştüğünü söyleme.'
    ], 'DNA–RNA–Protein akışındaki okları ve kodonla ilgili açıklamaları birlikte oku.', 'Transkripsiyon ile translasyonun ürünleri neden farklıdır?', 'Transkripsiyonda DNA kalıbından RNA sentezlenir. Translasyonda mRNA’daki kodon sırası kullanılarak amino asitler polipeptit zincirine bağlanır.'),
    s('Protein Sentezinin Mekanizması ve Poliribozom', [162,163,164], [
      'p162’de transkripsiyonla başlayan mekanizmayı, p163’te ribozom ve tRNA etkileşimine kadar sırayla izle. mRNA kodonu ile tRNA antikodonu eşleşir; tRNA’nın taşıdığı amino asit büyüyen zincire katılır. Baz eşleşmesi ile amino asitler arasındaki peptit bağı farklı konumlarda oluşan farklı bağlardır.',
      'Başlatma, uzama ve sonlanma aşamalarında ribozomun mRNA üzerinde ilerlemesini takip et. Dur kodonu için amino asit taşıyan bir tRNA gelmesi gerektiğini varsayma. p164’te poliribozom çiziminde bir mRNA üzerinde birden çok ribozomun çalıştığını gör. Bu, aynı mesajdan çok sayıda polipeptit üretilmesini sağlayabilir; tek ribozomun aynı anda birbirinden bağımsız birçok mRNA’yı okuduğu anlamına gelmez.'
    ], 'Kodon–Antikodon temasını, amino asit zincirini ve p164’te aynı mRNA üzerindeki çoklu ribozomları izle.', 'Poliribozomda bir mRNA’dan çok sayıda ürün çıkması mRNA’nın her ürün için tüketildiğini gösterir mi?', 'Göstermez. Aynı mRNA birden çok ribozom tarafından okunabilir ve tekrar kullanılabilir; mesaj kalıp olarak görev yapar.'),
    s('Genetik Mühendisliği, Model Organizmalar, DNA Parmak İzi ve Gen Klonlama', [165,166,167,168], [
      'p165’te klasik ve modern biyoteknoloji ayrımını uygulamanın hangi düzeyde değişiklik yaptığına bakarak oku. Melezleme ve seçme ile belirli genlerin doğrudan aktarımı aynı teknik değildir. p166’da model organizmanın hangi araştırma sorusuna uygun özellikler taşıdığını düşün; tek bir canlının bütün araştırmalar için en iyi model olması gerekmez.',
      'p167’de DNA parmak izi ile kök hücre, p168’de kök hücre çeşitleri ve gen klonlama ayrı başlıklardır. DNA karşılaştırması bireyler arasındaki farklılıkları inceleyebilir; klonlama belirli materyalin kopyalarının elde edilmesiyle ilgilidir. Kök hücrenin bölünme ve farklılaşma kapasitesini, zaten özelleşmiş bütün hücrelerin her koşulda her dokuya dönüşebilmesi gibi genelleme.'
    ], 'Klasik/Modern Biyoteknoloji ayrımını; DNA Parmak İzi, Kök Hücreler ve Gen Klonlama başlıklarını sırayla oku.', 'Gen klonlama ile bir canlının bütününün klonlanması neden aynı kapsamda değildir?', 'Gen klonlamada belirli DNA bölgesinin kopyaları elde edilir. Canlı klonlamada bütün organizmanın gelişimiyle ilgili daha kapsamlı bir süreç söz konusudur.'),
    s('Biyoteknolojinin İnsan Hayatına Etkisi; Biyogüvenlik ve Biyoetik', [169,170,171], [
      'p169–170’te sağlık uygulamalarını hedeflerine göre ayır: bir ürünün mikroorganizmada üretilmesi, yapay doku elde edilmesi ve gen tedavisi aynı müdahale değildir. İnsülin üretiminde aktarılmış bilginin hücre tarafından ifade edilmesi, önceki protein sentezi sayfalarının uygulamasıdır.',
      'p171’de tarım, hayvancılık, endüstri ve çevre uygulamalarını okuduktan sonra biyogüvenlik ve biyoetik başlığına geç. Bir tekniğin işe yarayabilmesi bütün uygulamalarının aynı yarar ve risk dengesine sahip olduğu anlamına gelmez. Değerlendirmede organizma, aktarılan özellik, kullanım alanı ve çevreyle ilişki önem taşır. Bilimsel mekanizmayı anlamak ile uygulamanın hangi koşullarda uygun olduğuna karar vermek farklı fakat bağlantılı sorulardır.'
    ], 'İnsülin, Gen Terapisi, GDO ve Biyogüvenlik/Biyoetik örneklerinde hangi basamağın değiştirildiğini belirle.', 'Bir bakteriye insan geni aktarılıp protein üretilmesi hangi temel bilgi akışına dayanır?', 'Aktarılan DNA bilgisinden RNA sentezi ve ardından ribozomda protein üretimi gerçekleşir. Gen aktarımının ürüne dönüşmesi, genin uygun biçimde ifade edilmesine bağlıdır.')
  ]);

  add('bio-ayt-11', 'Canlılık ve Enerji, Fotosentez, Kemosentez ve Hücresel Solunum', 'AYT-bio', '172–196. sayfalarda ATP’den fotosentez ve solunuma; en sonda fermantasyon karşılaştırmasına kitap üzerinden ilerleyeceğiz.', [
    s('ATP Molekülü, ATP Döngüsü ve Fosforilasyon Çeşitleri', [172,173,174], [
      'p172’de ATP’nin adenin, riboz ve üç fosfat bileşenini bul. p173’te besindeki enerji, ATP sentezi ve ATP kullanımını birleştiren okları izle. ATP besinin yerine geçen uzun süreli depo değil, enerji gerektiren hücresel işlerin yürütülmesine katılan yenilenen bir aracıdır.',
      'p174’te substrat düzeyinde, oksidatif ve fotofosforilasyonu enerji aktarım yolu açısından karşılaştır. Hepsinde ADP’ye fosfat eklenerek ATP sentezi söz konusudur; enerjinin sağlandığı mekanizma farklıdır. “Fosforilasyon” sözcüğünü gördüğünde mutlaka kloroplast veya yalnız ışık düşünme. Aynı ATP ürünü farklı hücresel yollarla elde edilebilir; yöntemi belirlemek için olayın kaynağı ve bulunduğu yapı bilinmelidir.'
    ], 'ATP döngüsü oklarını ve p174’te üç fosforilasyon başlığını karşılaştır.', 'ATP’nin aynı molekül olması neden üretildiği yolun da aynı olduğunu göstermez?', 'Aynı ürün farklı enerji dönüşüm mekanizmalarıyla sentezlenebilir. Substrat düzeyinde, oksidatif ve ışıkla bağlantılı fosforilasyon farklı yolları anlatır.'),
    s('Fotosentezin Önemi, Genel Denklemleri, Kloroplast ve Pigmentler', [175,176,177,178], [
      'p175’te fotosentezin önemini ve keşif çalışmalarını okuyarak hangi deneyin hangi bileşen hakkında bilgi verdiğini ayır. p176’da genel denklemde su, karbondioksit, organik ürün ve oksijenin yerlerini bul. Açığa çıkan oksijenin kaynağıyla organik molekülün karbon kaynağını aynı madde sayma.',
      'p177’de kloroplastta tilâkoit ve stroma bölmelerini, p178’de pigmentlerin ışıkla ilişkisini incele. Bir pigmentin ışığı soğurması, her dalga boyunun aynı oranda kullanıldığı anlamına gelmez. Kloroplastın farklı bölmeleri sonraki iki reaksiyon grubunun konumunu açıklayacak. Genel denklem toplam sonucu gösterir; bütün basamakların tek anda ve tek enzimle gerçekleştiği bir olay şeması değildir.'
    ], 'p176’da su/CO2 kaynaklarını; p177’de kloroplast bölmelerini; p178’de pigment açıklamalarını izle.', 'Fotosentezde oluşan oksijenle organik ürünün karbonu neden aynı başlangıç molekülünden gelmek zorunda değildir?', 'Farklı atomlar farklı kaynaklardan sağlanır. Oksijen gazının kaynağı suyla, organik yapıya katılan karbonun kaynağı CO2 ile ilişkilidir.'),
    s('Fotosentez Sürecinin Şeması ve Işığa Bağımlı Reaksiyonlar', [179,180], [
      'Şemada önce ışığın ulaştığı tilâkoit düzenini bul. Suyun kullanılması, oksijenin açığa çıkması ve ATP/NADPH oluşması arasındaki bağlantıyı takip et. Işıktan gelen enerji, sonraki karbon bağlama basamaklarında kullanılabilecek kimyasal enerji ve indirgeme gücüne dönüştürülür.',
      'Oksijen çıkışını doğrudan glikozun parçalanmasına bağlama; burada suyun işlenmesiyle ilişkili farklı bir süreç vardır. ATP ile NADPH’nin isimlerini birlikte ezberlemek yerine sonraki reaksiyonlara hangi katkıyı taşıdıklarını söyle. Şemadaki oklar madde ve enerji bağlantılarını gösterir. Kloroplast içinde ATP’nin üretilmesi, bu ATP’nin tamamının hücrenin her bölgesine bir depo gibi dağıtıldığı anlamına gelmez; yerel kullanım bağlantısını izle.'
    ], 'Su → O2 ve ışık enerjisi → ATP/NADPH bağlantılarını fotosentez şemasında ayrı takip et.', 'Işığa bağımlı reaksiyonlar neden yalnız oksijen üreten bir aşama olarak açıklanamaz?', 'Oksijen çıkışına ek olarak ATP ve NADPH oluşur. Bunlar sonraki karbon bağlama reaksiyonlarının yürütülmesine katkı sağlar.'),
    s('Işıktan Bağımsız Reaksiyonlar ve Reaksiyonların Karşılaştırılması', [180,181], [
      'p180’de Calvin döngüsüne CO2’nin girişini ve ışığa bağımlı evreden gelen ATP/NADPH kullanımını izle. “Işıktan bağımsız” ifadesi ışığın doğrudan tepkime girdisi olmadığına işaret eder; bu evrenin önceki evreden tamamen kopuk olduğunu anlatmaz.',
      'p181’de PGAL ile organik ürünlerin oluşumunu, ardından karşılaştırma tablosunu oku. İki sütunu yer, girdiler, ürünler ve enerji ilişkisi bakımından karşılaştır. Bir evrenin ürününün diğerinin girdisi olması, birlikte çalışan bir sistemi gösterir. ADP ve taşıyıcıların geri dönmesiyle CO2’nin organik yapıya katılması aynı ok değildir. Madde döngüsü ve enerji aktarımının hangi bileşenler üzerinden yürüdüğünü ayrı söyle.'
    ], 'Calvin döngüsünde CO2, ATP/NADPH ve PGAL oklarını; p181’de iki evrenin karşılaştırma tablosunu izle.', 'Calvin döngüsünün ışıktan bağımsız adlandırılması neden karanlıkta sınırsız sürdüğünü göstermez?', 'Döngü ATP ve NADPH gibi ışığa bağımlı reaksiyonların sağladığı ürünlere ihtiyaç duyar. Doğrudan ışık kullanmaması bu kaynak bağımlılığını ortadan kaldırmaz.'),
    s('Fotosentez Hızını Etkileyen Faktörler', [182,183], [
      'p182’de minimum kuralını, aynı anda gerekli olan etkenlerden yetersiz olanın hızı sınırlandırması olarak oku. Işık şiddetini artırınca eğri yataylaşıyorsa süreç durmuş değildir; başka bir etken sınırlandırıcı hâle gelmiş olabilir. Bir faktörün artışı bütün koşullarda sınırsız hız artışı sağlamaz.',
      'p183’te CO2 yoğunluğu ve ışığın dalga boyu grafiklerini eksenlerinden başlayarak oku. Dalga boyuyla ışık şiddeti farklı değişkenlerdir. Sıcaklık etkisini enzimlerin çalışma koşullarıyla ilişkilendir. Tarımsal aydınlatma açıklamasında amaç yalnız daha çok ışık değil, uygun koşulların birlikte sağlanmasıdır. Net gaz değişimini yorumlarken fotosentez yapan hücrelerde solunumun da sürdüğünü hesaba kat; ölçülen net değer iki sürecin bileşkesidir.'
    ], 'Işık şiddeti, sıcaklık, CO2 ve dalga boyu grafiklerinde önce ekseni sonra plato/tepeyi oku.', 'Işık artırıldığı hâlde fotosentez hızı değişmiyorsa fotosentez durmuş mudur?', 'Hayır. Hız sıfırdan farklı sabit bir düzeyde olabilir. CO2 veya başka bir koşul sınırlandırıcıysa ek ışık net artış sağlamayabilir.'),
    s('Kemosentez ve Fotosentezle Karşılaştırılması', [184,185], [
      'p184’te enerji elde etme ile organik besin sentezleme basamaklarını ayrı izle. Kemoototrof canlılar belirli inorganik maddelerin oksidasyonundan sağlanan enerjiyi organik madde sentezinde kullanabilir. Işığın zorunlu enerji kaynağı olmaması, enerji gereksiniminin bulunmadığı anlamına gelmez.',
      'p185’te madde döngülerine katkı açıklamasını azot gibi elementlerin farklı kimyasal biçimleri arasındaki dönüşümlerle ilişkilendir. Fotosentez ve Kemosentezin Karşılaştırılması tablosunda organik besin üretme ortaklığını, enerji kaynağı farklılığından ayır. Her kemosentez örneğinin fotosentezdeki gibi oksijen gazı açığa çıkarması gerektiğini varsayma. Üretici olma ölçütü ile kullanılan enerji kaynağı aynı soru değildir.'
    ], 'Kemosentez şemasında enerji ve besin oklarını; p185’te karşılaştırma tablosunu yatay oku.', 'Kemosentez yapan bir canlının ışığa ihtiyaç duymaması neden heterotrof olduğunu göstermez?', 'Beslenme sınıfı organik maddeyi nasıl sağladığıyla ilgilidir. Kemoototrof canlı inorganik karbon kaynaklarından organik madde sentezler; enerjiyi ışık yerine kimyasal dönüşümlerden alır.'),
    s('Oksijenli Solunumun Önemi, Mitokondri ve Evreleri', [186,187,188,189,190], [
      'p186’da mitokondrinin bölmelerini bulduktan sonra p187’de aşamaların genel şemasına, p188’de glikoliz açıklamasına bak. Glikolizin sitoplazmayla ilişkisini belirle; bütün oksijenli solunum basamakları mitokondrinin aynı bölmesinde gerçekleşmez. p188’de pirüvatın oksidasyonu ve Krebs döngüsünü; p189’da ETS’yi sıraya koy.',
      'Her aşamada karbonun, elektron taşıyıcılarının ve ATP’nin durumunu ayrı izle. CO2 çıkışı ile oksijenin son elektron alıcısı olarak kullanılması aynı basamakta olmak zorunda değildir. ETS’de proton farkı ve ATP sentezi bağlantısı, ATP’nin yalnız glikozun doğrudan parçalandığı yerde oluşmadığını gösterir. p190’da farklı besinlerin solunuma katılma yolları ve deney açıklamasını bu evrelere yerleştir; yağ ve proteinlerin bütün basamaklara aynı noktadan girdiğini varsayma.'
    ], 'Glikoliz → Pirüvat oksidasyonu → Krebs → ETS sırasını konumlarıyla; p190’da besinlerin giriş yollarını izle.', 'Oksijenin kullanılması ile CO2’nin oluşması neden aynı tepkime basamağı olarak düşünülmez?', 'CO2 karbonlu ara ürünlerin dönüşümlerinde çıkabilir. Oksijen ETS sonunda elektronların aktarımıyla ilişkili görev yapar; süreçteki rolleri ve konumları farklıdır.'),
    s('Oksijensiz Solunum, Fotosentez–Solunum İlişkisi ve Kemiosmotik Görüş', [191,192,193], [
      'p191’de oksijensiz solunumda ETS bulunabildiğini ve son elektron alıcısının oksijenden farklı olabileceğini izle. Oksijen kullanılmaması, olayın mutlaka fermantasyon olduğunu göstermez. Sürecin elektron taşıma düzeni ayırt edicidir.',
      'p192’de fotosentez ile solunum karşılaştırmasını okurken girdilerin ve ürünlerin toplam düzeyde ilişkili olduğunu gör. Bu ilişki iki sürecin aynı mekanizmanın basitçe ters çevrilmiş hâlleri olduğunu söylemez. p193’te mitokondri ve kloroplastın kemiosmotik çizimlerinde protonların hangi bölmede biriktiğini ve ATP sentazdan hangi yönde geçtiğini ayrı takip et. Ortak ilke proton farkının ATP sentezinde kullanılmasıdır; bölmelerin adları ve proton birikim yönleri organellere göre farklıdır.'
    ], 'p191’de son elektron alıcısını; p192 karşılaştırmasını ve p193’te iki organelin proton/ATP sentaz oklarını izle.', 'Oksijensiz solunumla fermantasyonu ayırırken neden yalnız oksijen yokluğuna bakılamaz?', 'İki süreç de oksijen kullanmadan gerçekleşebilir. ETS ve son elektron alıcısının düzeni gibi mekanizma bilgileri ayrımı sağlar; fermantasyon ETS kullanan solunumla aynı yol değildir.'),
    s('Etil Alkol ve Laktik Asit Fermantasyonu', [194,195,196], [
      'p194’te genel özelliklerden etil alkol yoluna, p195’te laktik asit yoluna ilerle. Her ikisinde glikolizden gelen NADH’ın yeniden NAD+ hâline dönebilmesi, glikolizin sürdürülmesine yardım eder. ATP katkısını son ürün oluşumuna rastgele yükleme; net ATP glikolizde substrat düzeyinde fosforilasyonla ilişkilidir.',
      'p196’daki ortak ve farklı özellikler karşılaştırmasını oku. Etil alkol fermantasyonunda CO2 çıkışı görülürken laktik asit yolunda aynı CO2 çıkışı beklenmez. Bu nedenle kapta gaz oluşmaması bütün enerji dönüşümlerinin durduğunu kanıtlamaz. Son ürünler, CO2 ve NAD+ yenilenmesini ayrı satırlarda düşündüğünde iki yolun ortak amacını ve farklı kimyasal sonuçlarını aynı anda açıklayabilirsin.'
    ], 'İki fermantasyon şemasında NAD+/NADH dönüşümünü ve CO2 çıkışını; p196’da ortak/farklı özellikleri karşılaştır.', 'Laktik asit fermantasyonunda CO2 çıkmaması ATP elde edilmediğini mi gösterir?', 'Hayır. Glikoliz sırasında net ATP elde edilebilir. CO2 çıkışı bütün ATP üreten süreçlerin ortak göstergesi değildir; iki fermantasyonun son ürün yolları farklıdır.')
  ]);

  add('bio-ayt-12', 'Bitki Biyolojisi; Canlılar ve Çevre', 'AYT-bio', '197–241. sayfalarda bitkisel dokular, organlar, hormonlar, taşıma, üreme ve kitabın Canlılar ve Çevre bölümünü okuyacağız.', [
    s('Meristem Doku', [197,198,199,200], [
      'p197’de çiçekli bitkinin temel kısımlarını gördükten sonra meristemlerin yerlerini bul. Uç meristem boyca büyümeyle, yanal meristemler kalınlaşmayla ilişkilidir. p198–199’da kökene göre birincil ve ikincil meristem ayrımını yerlerine göre sınıflandırmayla karıştırma; iki farklı ölçüt kullanılır.',
      'Bölünebilme yeteneği bitkide belirli bölgelerde büyümenin sürmesini sağlar. Ancak meristem hücresinin bölünmesiyle oluşan her hücre sonsuza kadar aynı özellikte kalmaz; bazıları farklılaşarak diğer dokulara katılır. Devam sayfalarındaki kalınlaşma düzenini çizimlerden takip et. Yaş halkası veya gövde kalınlığıyla ilgili bir gözlemi yorumlarken hangi meristemin hangi dokuyu oluşturduğunu belirt.'
    ], 'Uç/Yanal meristem yerlerini; birincil/ikincil sınıflandırmayı ve büyüme çizimlerini ayrı ölçütlerle izle.', 'Bitkinin uzamasıyla kalınlaşması neden aynı meristem konumuyla açıklanmaz?', 'Uç meristemlerin etkinliği boyca büyümeye, yanal meristemlerin etkinliği ise kalınlaşmaya katkı verir. Büyümenin yönü ve dokuların konumu farklıdır.'),
    s('Temel Doku: Parankima, Kollenkima ve Sklerenkima', [201,202,203], [
      'p201’de parankima türlerini işlevlerine göre oku: özümleme, havalandırma, iletim ve depo görevleri farklı hücresel düzenlerle ilişkilidir. Aynı genel doku adı altında iş bölümünün bulunması, her parankima hücresinin aynı miktarda kloroplast taşıdığı anlamına gelmez.',
      'p202–203’te kollenkima ile sklerenkimayı karşılaştır. Destek görevi ortak olsa da hücrelerin canlılık durumu ve çeper özellikleri farklıdır. Taş hücreleri ile lifleri şekil ve bulundukları örnekler üzerinden izle. p203’teki karşılaştırma tablosunu aynı satır boyunca oku; yalnız “ikisi de destek” ifadesi ayırt edici özellikleri kaybettirir. Genç ve büyüyen yapıyla daha sertleşmiş yapıların destek gereksinimleri aynı olmayabilir.'
    ], 'Parankima türlerini ve p203 Kollenkima–Sklerenkima karşılaştırma tablosunu incele.', 'İki dokunun destek sağlaması neden hücrelerinin aynı özellikte olduğunu göstermez?', 'Aynı işlev farklı çeper yapıları ve hücresel durumlarla sağlanabilir. Kollenkima ile sklerenkimanın canlılık ve çeper özellikleri bu nedenle ayrı karşılaştırılır.'),
    s('İletim Doku: Ksilem ve Floem', [204,205], [
      'p204’te ksilem elemanlarını su ve minerallerin taşınmasıyla ilişkilendir. p205’te floemin organik maddelerin taşınmasındaki görevini oku. İki doku aynı demet içinde bulunabilir ama taşınan maddeler, hücresel düzen ve mekanizma bakımından farklıdır.',
      'Ksilem ve Floem Karşılaştırması tablosunda canlılık durumu, taşıma yönü ve yapı özelliklerini ayrı satırlardan takip et. “Bitkide her şey yalnız kökten yaprağa çıkar” genellemesi floemin kaynak-hedef ilişkisini açıklamaz. Buna karşılık floemde farklı borularda farklı yönler bulunabilmesi, tek bir boruda aynı anda kuralsız iki yönlü akış demek değildir. İletim dokusunun yapısı, sonraki taşıma bölümünün ön koşuludur.'
    ], 'p205’te Ksilem ve Floem Karşılaştırması tablosunu satır satır oku.', 'Yaprakta üretilen şekerin köke taşınması hangi doku ve ilişkiyle açıklanır?', 'Floem kaynak-hedef ilişkisiyle organik madde taşır. Üretici yaprak kaynak, depolayan veya kullanan kök hedef olabilir; taşıma her zaman yukarı yönlü değildir.'),
    s('Örtü Doku; Stoma, Hidatot ve Lentisel', [206,207,208], [
      'p206’da epidermisi bitkinin çevreyle sınırını oluşturan doku olarak oku. Koruma ile madde alışverişi birlikte düzenlenir; bütün yüzeyin tamamen geçirimsiz olması bitkinin yaşam gereksinimlerini karşılamaz. p207’de tüylerin farklı görevlerini, her tüyün kök emici tüyü olduğu varsayımından ayır.',
      'p208’de periderm ve lentisellere geç. Stoma, hidatot ve lentisel karşılaştırmasında taşınan maddenin gaz, su buharı veya sıvı su oluşuna dikkat et. Bunlar aynı açıklığın farklı adları değildir. Stomanın açılıp kapanabilmesiyle lentiselin düzeni aynı mekanizma değildir. Yapı-görev eşleşmesi özellikle terleme ve gaz alışverişi sorularında hangi yoldan geçiş olduğunu belirlemeni sağlar.'
    ], 'Stoma–Hidatot–Lentisel karşılaştırmasını ve örtü dokunun farklılaşmış yapılarını incele.', 'Terleme ile damlamayı ayırmak için suyun hangi özelliğine bakılır?', 'Suyun buhar hâlinde mi yoksa sıvı hâlde mi çıktığı ve kullanılan yapı önemlidir. Stoma ile hidatot aynı geçişi aynı mekanizmayla gerçekleştirmez.'),
    s('Kök ve Gövde', [209,210,211,212], [
      'p209’da kökün görevleri ve iç yapısını, p210’da tek ve çift çenekli kök kesitlerini karşılaştır. Dıştan içe dokuların yerleşimi suyun toprağın içinden iletim dokusuna nasıl ulaştığını anlamaya yardım eder. Kökün bütün yüzeyini aynı etkinlikte emilim yapan tek tip bir boru gibi düşünme.',
      'p211–212’de gövdenin görev ve kesitlerine geç. İletim demetlerinin dizilişi gibi farklılıkları kök kesitiyle karşılaştırırken hangi organı incelediğini açıkça söyle. Aynı bitkide kök ve gövde dokularının yerleşimi aynı olmak zorunda değildir. Gövde yalnız yaprağı tutan bir destek değil, maddelerin farklı organlar arasında iletimine ve kimi örneklerde depolamaya da katılan bir organdır.'
    ], 'Tek/çift çenekli kök kesitlerini ve gövde kesitlerindeki iletim demeti dizilişlerini karşılaştır.', 'Bir bitkinin kök kesitiyle gövde kesitinin farklı görünmesi neden çelişki değildir?', 'Organların görevleri ve doku yerleşimleri farklıdır. Aynı iletim ve destek dokuları farklı organlarda farklı düzenlenebilir.'),
    s('Yaprak; Nemli ve Kurak Bölge Bitkileri', [213,214], [
      'p213’te yaprağın enine kesitinde örtü doku, fotosentezle ilişkili hücreler ve iletim dokusunu bul. Yaprak yalnız ince bir yüzey değildir; ışık alma, gaz alışverişi, su dengesi ve iletim aynı organda düzenlenir. Hücrelerin konumu bu görevlerin birlikte yürütülmesine katkı verir.',
      'p214’te Nemli ve Kurak Bölge Bitkilerinin Karşılaştırılması tablosunu aynı özellik üzerinden yatay oku. Su kaybını sınırlayan yapılar, ışık alma ve gaz alışverişiyle birlikte değerlendirilir. Kalın kütikula veya stoma düzeni gibi bir özelliği tek başına “daha gelişmiş” diye niteleme; bulunduğu çevredeki işlevsel sonucu önemlidir. Farklı çevre koşulları farklı yapıların avantaj sağlamasına yol açabilir.'
    ], 'Yaprağın enine kesitini ve p214’te Nemli Bölge/Kurak Bölge sütunlarını aynı satırda karşılaştır.', 'Su kaybını azaltan bir yapının gaz alışverişiyle birlikte değerlendirilmesi neden gerekir?', 'Bitki suyu korurken fotosentez ve solunum için gaz alışverişini de sürdürmelidir. Yapının sonucu bu gereksinimler arasındaki denge içinde anlaşılır.'),
    s('Bitki Gelişiminde Hormonların Etkisi', [215,216,217], [
      'p215’te oksinden başlayarak hormonları sırayla oku. Bir hormonun etkisi derişime, hedef dokuya ve diğer hormonlarla ilişkiye bağlıdır; “oksin her koşulda bütün organları aynı oranda büyütür” genellemesi kurulmaz. Kök ve gövdenin aynı derişime farklı yanıt verebilmesi bu bağlamı önemli kılar.',
      'p216–217’de giberellin, sitokinin, absisik asit ve etileni görevleriyle eşleştir. Büyüme, hücre bölünmesi, dormansi, su kaybının düzenlenmesi ve olgunlaşma aynı olay değildir. Bir sürecin birkaç hormonun dengesinden etkilenmesi mümkündür. Hormon adını tek bir sözcüklük görevle eşitlemeden kitabın verdiği etkileri birlikte oku; sonraki tropizma örneğinde özellikle oksinin eşit dağılmamasının büyümeyi nasıl etkilediğine döneceğiz.'
    ], 'Oksin → Giberellin → Sitokinin → ABA → Etilen sırasındaki görev açıklamalarını takip et.', 'Bir hormonun kök ve gövdede farklı etki göstermesi neden çelişki değildir?', 'Hedef dokuların duyarlılığı ve yanıt mekanizmaları farklı olabilir. Hormonun derişimi ve diğer hormonlarla ilişkisi de sonucu etkiler.'),
    s('Tropizma, Nasti ve Fotoperiyodizm', [218,219,220,221,222], [
      'p218’de fototropizma çiziminde ışığın geliş yönünü ve oksin dağılımıyla ilişkili farklı büyümeyi izle. p219–220’de yer çekimi, su, kimyasal madde ve dokunmaya yönelim örneklerini, uyaranın yönüyle büyüme yönünü karşılaştırarak oku.',
      'p220–221’de nasti hareketine geçtiğinde uyaranın yönüne bağlılık ölçütünü değiştir. Tropizma ve Nasti Karşılaştırması tablosu bu ayrımı görünür kılar. p222’de fotoperiyodizm, basitçe ışığa doğru eğilme değildir; aydınlık/karanlık sürelerine verilen gelişimsel yanıttır. Çiçeklenmede gün ve kesintisiz gece süresinin ilişkisini örneklerden oku. Farklı bitkilerin aynı süreye aynı yanıt vermesi zorunlu değildir.'
    ], 'Fototropizmada Oksin çizimini, Tropizma/Nasti tablosunu ve Fotoperiyodizm bölümündeki süre ilişkisini karşılaştır.', 'Bitkinin ışığa yönelmesiyle gün uzunluğuna bağlı çiçeklenmesi neden aynı tepki değildir?', 'İlki uyaranın yönüne bağlı büyüme yönelimidir. Fotoperiyodizm aydınlık-karanlık süresinin gelişimsel olayları düzenlemesidir; yön ve süre farklı uyaran özellikleridir.'),
    s('Köklerde Emilim ve Ksilemde Su–Mineral Taşınması', [223,224,225,226], [
      'p223–224’te su ve minerallerin kökten girişini doku katmanları üzerinden izle. Topraktan kök yüzeyine ulaşma ile iletim dokusuna geçme aynı sınırı aşmak değildir. Hücre duvarı ve hücre içi yolları, seçici sınırların nerede devreye girdiğini belirleyerek oku.',
      'p225’te kök basıncı ve kılcallık, p226’da terleme ve kohezyon-gerilim açıklamasına geç. Yapraktan su kaybı süreklilik gösteren su sütununda çekişe katkı verir; su molekülleri arasındaki kohezyon ve çeperle etkileşim önemlidir. Yüksek ağaçlarda taşımayı yalnız kökün suyu yukarı itmesiyle açıklama. Ksilem borularının bütün uzunluğu boyunca canlı hücre pompalarının sırayla suyu ittiği bir mekanizma da değildir.'
    ], 'Kök giriş yollarını; p225 Kök Basıncı/Kılcallık ile p226 Terleme ve Kohezyon Gerilim Teorisini sırasıyla oku.', 'Yapraklardan terleme kökte başlayan su alımıyla nasıl bağlantı kurar?', 'Su kaybı ksilemdeki sürekli su sütununda gerilime katkı verir. Kohezyon ve su potansiyeli farklarıyla birlikte kökten yaprağa su hareketi desteklenir.'),
    s('Stomalar, Çevresel Faktörler ve Floemde Basınç Akış', [227,228,229,230,231], [
      'p227’de açık ve kapalı stoma çizimlerinde bekçi hücrelerinin durumunu karşılaştır. Su ve iyon değişimi, hücrelerin turgorunu ve açıklığı etkiler. p228–229’da sıcaklık, nem, rüzgâr ve diğer çevresel etkileri okurken terlemenin yalnız stoma sayısıyla belirlenmediğini gör.',
      'p230’da floemde kaynak-hedef ilişkisine ve basınç akış sırasına geç. Organik maddenin yüklenmesi, su hareketi ve basınç farkının oluşması birbiriyle bağlantılıdır. Kaynak her zaman aynı organ olmak zorunda değildir; depo organ dönemine göre kaynak veya hedef olabilir. p231’de deneyleri bu taşıma yollarını sınayan düzenekler olarak oku. Ksilemdeki çekiş modeliyle floemdeki basınç akışını aynı mekanizma diye anlatma.'
    ], 'Açık/Kapalı stoma çizimini; p230 Basınç Akış Teorisi sırasını ve p231 deneylerini takip et.', 'Bir depo kökün bazen hedef bazen kaynak olabilmesi nasıl açıklanır?', 'Besin depoladığı dönemde başka organlardan organik madde alarak hedef olur. Depolarını büyüyen organlara verdiğinde kaynak rolü üstlenebilir.'),
    s('Çiçek, Gametlerin Oluşumu ve Bitkilerde Eşeyli Üreme', [232,233,234], [
      'p232’de çiçeğin genel yapısında erkek ve dişi üreme yapılarıyla diğer yapıları ayır. Çiçek organının adı ile oluşan hücrenin adı aynı şey değildir. p233’te çiçek çeşitlerini, bütün bitkilerin aynı çiçekte aynı organ düzenini taşıdığı varsayımından uzaklaşarak oku.',
      'p234’te erkek ve dişi üreme yapılarındaki mayoz, mitoz ve gamet oluşumu sırasını izle. Polen tanesini doğrudan sperm hücresinin eş anlamlısı gibi kullanma; polenle taşınan yapı ve içinde oluşan erkek gametler farklı düzeylerdir. Aynı şekilde tohum taslağı ile yumurta hücresi farklı yapılardır. Bu ayrımlar sonraki sayfadaki tozlaşma ve döllenmenin iki ayrı olay olduğunu açıklamayı sağlar.'
    ], 'Çiçek çiziminde organları; p234’te mayoz/mitoz basamaklarında oluşan hücre ve yapıların adlarını izle.', 'Polen tanesini sperm hücresiyle aynı saymak hangi ayrımı kaybettirir?', 'Polen, erkek gametofitle ilişkili çok hücreli düzeni/taşınan yapıyı ifade eder; sperm hücreleri onun gelişim sürecinde oluşan gametlerdir. Yapı ile gamet aynı düzey değildir.'),
    s('Tozlaşma, Çift Döllenme, Tohum, Meyve ve Çimlenme', [235,236,237,238], [
      'p235’te tozlaşmayı polenin uygun yere ulaşması, döllenmeyi gamet çekirdeklerinin birleşmesi olarak ayır. Çift döllenme şemasında bir sperm çekirdeğinin yumurtayla, diğerinin merkezdeki çekirdeklerle birleşmesini takip et. Zigot ve endospermin kökenlerini ayrı söyle.',
      'p236’da tohum ve meyve oluşumunda hangi çiçek yapısının neye dönüştüğünü izle. p237–238’de çimlenme ve dormansiye geç. Uygun su, sıcaklık ve oksijen koşulları sağlansa da dormansi gibi nedenlerle hemen çimlenme gerçekleşmeyebilir. İlk gelişimde depo besinlerin kullanılması, filizin başlangıçtan itibaren yalnız fotosenteze dayanmadığını gösterir. Döllenme, tohum olgunlaşması ve çimlenme aynı zamanda gerçekleşen tek olay değildir.'
    ], 'Çift döllenme oklarını; tohum/meyve kökenlerini ve çimlenme koşulları başlıklarını sırayla oku.', 'Tozlaşma gerçekleşmesi neden döllenmenin de kesin tamamlandığını göstermez?', 'Polenin ulaşması yalnız ilk basamaktır. Polen tüpü gelişimi, gametlerin taşınması ve uygun çekirdek birleşmelerinin gerçekleşmesi gerekir.'),
    s('Canlılar ve Çevre: Varyasyon, Seçilim ve Adaptasyon', [239,240,241], [
      'p239’da varyasyon, mutasyon ve doğal seçilimi ayrı kavramlar olarak oku. Popülasyonda farklı özellikler bulunur; çevre koşullarında bazı kalıtsal özellikleri taşıyan bireylerin üreme başarısı daha yüksek olabilir. Seçilim, bireyin gereksinim duyduğu için kendine uygun mutasyonu bilinçli olarak oluşturması değildir.',
      'p240’ta antibiyotik direnci ve pestisit örneklerinde uygulamadan önce bulunabilen kalıtsal farklılıkların önemini düşün. Dirençli bireylerin göreli çoğalması popülasyonun yapısını değiştirir. p241’de yapay seçilimde hangi bireylerin üreyeceğinin insan tercihiyle etkilenmesini doğal seçilimden ayır. Adaptasyon bireyin kısa süreli alışmasıyla aynı anlamda kullanılmaz; kalıtsal özelliklerin nesiller boyunca yaşama ve üreme başarısıyla ilişkisini anlatır.'
    ], 'Varyasyon → Doğal Seçilim → Adaptasyon bağlantısını ve antibiyotik/pestisit örneklerini; ardından Yapay Seçilim uygulamalarını oku.', 'Antibiyotik sonrası dirençli bakterilerin oranının artması neden bütün bakterilerin ihtiyaca göre aynı anda direnç kazandığını göstermez?', 'Başlangıçta dirençli farklılık taşıyan bireyler bulunabilir. Duyarlıların azalması ve dirençlilerin üremesi oranları değiştirir; popülasyon değişimi her bireyin aynı yönlü dönüşümü değildir.')
  ]);

  guides['bio-tyt-02'].title = 'Canlıların Temel Bileşikleri ve Sağlıklı Beslenme';
  guides['bio-tyt-02'].intro = '16–45. sayfalarda inorganik bileşiklerden ATP ve sağlıklı beslenmeye ilerleyeceğiz. Aradaki Enzimler bölümü, ayrı derste 31–35. sayfalarla ayrıntılı işlenir.';
  guides['bio-tyt-05'].title = 'Hücre Zarından Madde Geçişleri ve Bilimsel Yöntem';
  guides['bio-tyt-05'].intro = '64–72. sayfalarda taşıma sınıflandırması, zar çizimleri, osmoz, kesecikli taşıma ve kitabın bilimsel yöntem sayfasını okuyacağız.';
  guides['bio-tyt-06'].title = 'Hücre Döngüsü, Mitoz ve Eşeysiz Üreme';
  guides['bio-tyt-06'].intro = '101–113. sayfalarda bölünme gereksinimi, interfaz, mitoz, sayı grafikleri ve döngü kontrolünden eşeysiz üreme çeşitlerine ilerleyeceğiz.';
  guides['bio-tyt-08'].intro = '123–144. sayfalarda kalıtım kavramları, olasılık, çaprazlamalar, kan grupları, eşeye bağlı kalıtım, soyağacı ve genetik çeşitliliği sırayla okuyacağız.';
  guides['bio-tyt-10'].intro = '145–171. sayfalarda ekolojik düzeyler ve madde döngülerinden çevre sorunlarına, sürdürülebilirlik ve çeşitliliğin korunmasına ilerleyeceğiz.';

  window.BOOK_GUIDES = window.BOOK_GUIDES || {};
  Object.assign(window.BOOK_GUIDES, guides);
})();
